CREATE TABLE IF NOT EXISTS public.house_lord_knowledge (
 item_key text PRIMARY KEY,
 lord_house smallint NOT NULL CHECK (lord_house BETWEEN 1 AND 12),
 destination_house smallint NOT NULL CHECK (destination_house BETWEEN 1 AND 12),
 title text NOT NULL,
 bullets jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_house_lord_destination ON public.house_lord_knowledge(lord_house,destination_house);
CREATE INDEX IF NOT EXISTS idx_house_lord_title ON public.house_lord_knowledge USING gin (to_tsvector('simple', title));
ALTER TABLE public.house_lord_knowledge ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.house_lord_knowledge FROM anon, authenticated;
