INSERT INTO public.house_lord_knowledge(item_key,lord_house,destination_house,title,bullets) VALUES
("1in1",1,1,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 1","[\"ตำแหน่งนี้ทรงพลังมาก ส่งผลดีต่อสุขภาพ ระบบภูมิคุ้มกันแข็งแรง\",\"ร่างกายโดยรวมมีพลัง ส่วนที่เป็นที่สังเกตได้ชัดจะขึ้นอยู่กับราศี เช่น เมษ = ศีรษะ หรือสมอง, พฤษภ = ใบหน้า, กรกฎ = หน้าอก, สิงห์ = ช่วงท้อง ฯลฯ\",\"ส่งเสริมความมั่นใจในตัวเอง รักตัวเอง ชอบให้คนสนใจ\",\"ถ้าได้รับมุมร้าย อาจมีอีโก้สูง และอยากควบคุมมากเกินไป\",\"มีความสามารถในการใช้มือสูง ทำธุรกิจหรืองานสร้างสรรค์ได้ดี\",\"เรียนรู้เร็ว มีวินัย มีพลังใจสูง ก้าวหน้าอย่างรวดเร็ว\",\"อาจมีปัญหาเรื่องความสัมพันธ์ โดยเฉพาะถ้าอยู่ในราศี Cardinal (เมษ, กรกฎ, ตุล, มกร)\",\"มีแนวโน้มแต่งงานมากกว่าหนึ่งครั้ง\"]"::jsonb),
("1in2",1,2,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 2","[\"เกิดผลดีด้านการเงิน รายได้ดีตั้งแต่วัยเด็ก\",\"ชอบเรียนรู้ มีความสุขกับการเรียน มีจิตใจสดใส\",\"มีแนวโน้มใฝ่ธรรมะหรือศาสนา\",\"ผูกพันกับครอบครัวมาก มักอยู่ใกล้ครอบครัว หรือมีปฏิสัมพันธ์บ่อย\",\"มีค่านิยมและศีลธรรมที่ชัดเจน อาจขัดแย้งกับคู่รักเรื่องค่านิยม\",\"ตั้งมาตรฐานความสัมพันธ์สูงเกินไป จนผิดหวังง่าย\",\"มีแนวโน้มมีปัญหาในธุรกิจที่เกี่ยวข้องกับมรดกหรือหุ้นส่วน\",\"ถ้ามีดาวอังคาร เสาร์ ราหู เกตุ อยู่ร่วม ต้องเรียนรู้ความอดทนและการยอมรับในความสัมพันธ์\"]"::jsonb),
("1in3",1,3,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 3","[\"มีพรสวรรค์หลากหลายด้าน รายได้จากหลายทาง\",\"เรือนที่ 3 เป็นเหมือนสนามรบ แต่เจ้าชะตาสามารถใช้ “ปากกา” แทน “ดาบ” คือสื่อสารเก่ง\",\"เหมาะกับงานกฎหมาย สื่อสาร สื่อสารมวลชน การเขียน\",\"อาจมีระยะห่างหรือเข้าใจผิดกับบิดา (เรือนที่ 9)\",\"เจออุปสรรคในต่างแดนหรือการศึกษาสูง (โดยเฉพาะถ้าเจ้าลัคน์เป็นดาวบาปเคราะห์)\",\"เรื่องรักอาจมีความตื่นเต้นสูง ดึงดูดใจ แต่เกิดความเข้าใจผิดหรือทะเลาะได้\",\"อาจมีปัญหากับพี่น้อง หรือพี่น้องต้องการความช่วยเหลือจากเจ้าชะตา\"]"::jsonb),
("1in4",1,4,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 4","[\"ได้รับพรด้านความสุขจากบ้าน พ่อแม่ และบ้านเกิด\",\"ถ้ามีดาวบาปเคราะห์ร่วม จะมีประสบการณ์วัยเด็กที่ส่งผลอย่างมากในชีวิต\",\"บ้านคือศูนย์กลางของกรรม ความรู้สึกอบอุ่น สำคัญมาก\",\"มีความสัมพันธ์แน่นแฟ้นกับพี่น้อง\",\"สามารถมีชีวิตแต่งงานที่มีความสุข ถ้าไม่มีดาวทำมุมร้าย\",\"อารมณ์อ่อนไหว สัมผัสได้ง่าย มักเข้าสู่ความสัมพันธ์เชิงรักได้เร็ว\",\"เรือนที่ 10 จะได้รับผลกระทบ อาจรู้สึกไม่เป็นสุขในที่ทำงาน\",\"เหมาะกับการทำงานที่บ้าน หรือเกี่ยวกับบ้าน เช่น อสังหา ตกแต่งภายใน\",\"การเรียนดี อาจเป็นครู สอนพิเศษจากบ้านได้\"]"::jsonb),
("1in5",1,5,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 5","[\"มีอิทธิพลต่อผู้คนรอบข้าง สร้างความประทับใจดี\",\"ทำให้เจ้านายหรือผู้ใหญ่ชื่นชม อาจได้เป็นผู้นำ\",\"ชอบเสี่ยง กล้าแสดงออก สนใจตลาดหุ้นหรือการลงทุน\",\"มีความคิดสร้างสรรค์สูง หาทางแก้ปัญหาใหม่ๆ\",\"ชอบเรียน ชอบสอน อาจทำงานเกี่ยวกับเด็ก\",\"เด็กมีบทบาททางกรรมในชีวิต อาจมีปัญหากับลูกคนแรกโดยเฉพาะในดวงชาย\",\"เป็นเรือนของกรรมดีจากอดีต ส่งผลให้เจริญรุ่งเรืองในอาชีพ\",\"มีโอกาสโด่งดังหรือนำเสนอผลงานในสาธารณะ\",\"ถ้าเจ้าลัคน์ได้รับมุมดี การศึกษาไปได้ไกล ถ้าไม่ดีอาจมีอุปสรรค\"]"::jsonb),
("1in6",1,6,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 6","[\"เจอความท้าทายในชีวิต แต่พร้อมสู้เหมือนถือดาบมาตั้งแต่เกิด\",\"อาจมีปัญหาสุขภาพ แต่จะขึ้นอยู่กับลักษณะของดาวเจ้าเรือนและดาวร่วม\",\"ถ้ามีดาวศุภเคราะห์ร่วม จะลดผลเสีย\",\"เจ้าชะตาเป็นนักต่อสู้เพื่อสิทธิ์ตนเองและผู้อื่น\",\"ปรัชญาหรือศาสนาช่วยเป็นกำลังใจให้ชีวิต\",\"มักมีศัตรู คู่แข่ง คดีความ การทะเลาะวิวาทอยู่เสมอ\",\"แต่อาจได้ชื่อเสียงจากการต่อสู้หรือการเผชิญหน้ากับปัญหาเหล่านี้\",\"ความสัมพันธ์อาจมีปัญหา เช่น ความลับ ความเข้าใจผิด หรือแม้แต่ความไม่ซื่อสัตย์\",\"ควรสื่อสารอย่างตรงไปตรงมา ซื่อสัตย์กับคู่ครอง\",\"อาชีพที่เหมาะ: กฎหมาย การแพทย์ การรักษา การให้คำปรึกษา งานช่วยเหลือผู้คนในพื้นที่เสี่ยงภัย\",\"มีความรักสัตว์ ต้องการช่วยเหลือสัตว์ และสร้างกรรมดีจากสิ่งนี้ได้\"]"::jsonb),
("1in7",1,7,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 7","[\"เป็นตำแหน่งที่เจ้าลัคน์อ่อนแรง (ขึ้นอยู่กับดาวด้วย)\",\"ถ้าเป็นดาวบาปเคราะห์ เช่น Mars, Saturn, Rahu, Ketu อาจทำให้สูญเสียเป้าหมายในชีวิตเพราะทุ่มเทกับคนอื่นเกินไป\",\"ควรระวังอย่าให้คู่ค้าหรือคู่ชีวิตดึงพลังงานออกไปจนหมด\",\"มีแนวโน้มดึงดูดคนที่ \\\"สูบพลังงาน\\\" โดยเฉพาะในความสัมพันธ์\",\"หากเจ้าเรือนที่ 1 อยู่เรือนที่ 7 ชีวิตจะเปลี่ยนทิศหลังแต่งงาน\",\"ถ้าชีวิตราบรื่นก่อนแต่ง อาจเจอความท้าทายหลังแต่ง\",\"ถ้าชีวิตลำบากก่อนแต่ง หลังแต่งจะดีขึ้น\",\"บางคนอาจปฏิเสธการแต่งงาน เพราะรู้ว่าจะถูกคาดหวังมาก\",\"เรื่องการเงินอาจรั่วไหลอย่างไม่รู้ตัว โดยเฉพาะถ้ามีดาวบาปเคราะห์อยู่เรือนที่ 6 หรือ 8\"]"::jsonb),
("1in8",1,8,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 8","[\"เป็นตำแหน่งที่ทรงพลัง สามารถเปลี่ยนแปลงชีวิตได้อย่างสิ้นเชิง\",\"มีจิตสำนึกเรื่องกรรมสูง สนใจธรรมะ ศาสนา ปรัชญา\",\"เป็นนักวิจารณ์ตนเองที่รุนแรง อาจหลุดเข้าไปในสถานการณ์มืดหรือเสี่ยงได้\",\"สนใจศาสตร์ลึกลับ เช่น โหราศาสตร์ พลังลี้ลับ\",\"มีแนวโน้มละเลยสุขภาพ ควรระวังอุบัติเหตุช่วงมหาทศาของดาวเจ้าเรือน\",\"ทำอาชีพที่ต้องใช้ความเสี่ยงได้ดี เช่น ศัลยแพทย์ ตำรวจ นักสืบ นักผจญเพลิง\",\"อาจดึงดูดคนแต่งงานแล้ว หรือมีความสัมพันธ์กับคนที่แต่งงานแล้ว\",\"มีแนวโน้มอารมณ์รุนแรง ควรควบคุมอารมณ์ในความสัมพันธ์และธุรกิจ\",\"ถ้ามีดาวศุภเคราะห์สนับสนุน จะประสบความสำเร็จในหุ้น การลงทุน\"]"::jsonb),
("1in9",1,9,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 9","[\"เป็นเรือนโชคดี ให้ความสำเร็จ แต่ขึ้นอยู่กับดาวที่เป็นเจ้าเรือน เช่น:\",\"Sun: ได้โชคตั้งแต่เด็ก\",\"Moon: ได้โชคหลังอายุ 24 ปี\",\"Mercury: ได้โชคหลังเรียนจบ\",\"Mars: ได้โชคหลังอายุ 28 ปี\",\"Venus: ได้โชคหลังแต่งงาน\",\"Jupiter: ได้โชคหลังมีลูก\",\"Saturn: ได้โชคหลังอายุ 36 ปี\",\"ต้องรักษาความซื่อสัตย์และจริยธรรม ไม่เช่นนั้นโชคจะหายไปทันที\",\"ได้รับการสนับสนุนจากหัวหน้า เจ้านาย ผู้มีอำนาจ\",\"มีเสน่ห์ในคำพูด รักการโต้วาที ชอบถกเถียงเรื่องปรัชญา\",\"ระวังการใช้วาทศิลป์เพื่อประโยชน์ส่วนตัวเกินไป\",\"มีโอกาสโยกย้ายไปต่างประเทศ หรือต้องออกจากบ้านเกิดจึงจะโชคดี\"]"::jsonb),
("1in10",1,10,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 10","[\"การงานคือจุดศูนย์กลางของชีวิต\",\"ได้รับโชคจากฝ่ายพ่อ หรือครอบครัวฝ่ายพ่อ\",\"ให้พลังแห่งเกียรติยศ ความเป็นผู้นำ และชื่อเสียง\",\"ต้องขยันและซื่อสัตย์ในการทำงาน ไม่เช่นนั้นจะเสียทุกอย่างอย่างรวดเร็ว\",\"ถ้าขยันมาก = ได้มาก ถ้าขยันน้อย = เสียหมด\",\"อาจมีชื่อเสียงหลังเสียชีวิตด้วยซ้ำ (เรือนที่ 1 คือเรือนที่ 4 จากเรือนที่ 10)\",\"ระวังปัญหากับแม่ หรือความเย็นชาทางอารมณ์ในวัยเด็ก\",\"เหมาะกับงานด้านอสังหาริมทรัพย์หากมีดาวศุภเคราะห์สนับสนุน\"]"::jsonb),
("1in11",1,11,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 11","[\"ได้ทุกสิ่งที่ต้องการในชีวิต มีความสำเร็จจากกรรมที่สร้างไว้\",\"แต่สำหรับลัคนา Cardinal (เมษ, กรกฎ, ตุล, มกร) จะมีอุปสรรคมากขึ้น\",\"ต้องพยายามฝ่าฟันถึงจะสำเร็จ แต่ถ้ามีดาวศุภเคราะห์ช่วย ก็จะมีเพื่อนและผู้ใหญ่ช่วยเหลือ\",\"เป็นนักแก้ปัญหาที่ดี มีความคิดสร้างสรรค์ ช่วยผู้อื่นได้\",\"มีโอกาสเป็นที่รู้จัก สังคมสนับสนุน\",\"ดึงดูดเข้าสู่การเมืองหรือการทำงานเพื่อสังคม\",\"ต้องรักษาจริยธรรมสูงในกลุ่มเพื่อน ไม่เช่นนั้นจะสูญเสียทุกอย่าง\",\"มีแนวโน้มรักหลายครั้ง หรือแต่งงานหลายครั้ง\",\"ต้องมีความเป็นเพื่อนในความสัมพันธ์ ถึงจะพบความสุขแท้จริง\",\"การบริจาค ทำบุญ การเสียสละจะนำโชคกลับคืน\"]"::jsonb),
("1in12",1,12,"เจ้าเรือนที่ 1 อยู่ในเรือนที่ 12","[\"ชีวิตต้องการความสันโดษ ความเป็นส่วนตัวสูง\",\"ถ้าเป็นดาวศุภเคราะห์ จะได้รับโชคจากต่างประเทศ มีลางสังหรณ์แม่น\",\"มีความสามารถทางจิตวิญญาณ มีจิตใจเมตตา รักในการให้\",\"ถ้าเป็นดาวบาปเคราะห์ จะมีพลังหนัก อารมณ์แปรปรวน หลับยาก\",\"โชคดีที่สุดเมื่อย้ายไกลจากบ้านเกิด\",\"ชีวิตอาจต้องย้ายถิ่นตลอดเวลา หาความมั่นคงได้ยากจนกว่าดาวบาปเคราะห์จะเป็นผู้ใหญ่ (เช่น Mars = 28, Saturn = 36)\",\"มีแนวโน้มใช้เงินสิ้นเปลืองหรือให้คนอื่นมากเกินไป\",\"อาจประสบภาวะซึมเศร้า หรือสับสน ถ้าไม่มีเวลาสงบเพื่อฟื้นฟูพลังภายใน\",\"ควรปฏิบัติธรรม เช่น สวดมนต์ ทำสมาธิ ทำบุญ ฯลฯ\",\"ความฝันอาจทำนายอนาคตได้ มีญาณหยั่งรู้สูง\",\"เหมาะกับงานในสถานที่ปิด เช่น โรงพยาบาล โรงเรียน สถานสงเคราะห์\",\"รักสัตว์ และการช่วยเหลือสัตว์ทำให้จิตใจสงบ\",\"เจ้าเรือนที่ 2\",\"เจ้าเรือนที่ 2 คือดาวที่ดูแลเรือนแห่งทรัพย์สิน อาหาร และทรัพย์สะสม\",\"เป็นตัวแทนของ \\\"คลังเก็บ\\\" ทุกสิ่งที่คุณเป็นเจ้าของ ทั้งเงิน ของใช้ ทรัพย์สิน\",\"คอยเติมเต็มสิ่งเหล่านี้ให้คุณเสมอ เช่น เสื้อผ้าใหม่ อาหาร ทรัพย์สิน และบัญชีเงินฝาก\",\"ทำหน้าที่ \\\"เสบียง\\\" สำหรับชีวิตปัจจุบัน และยังช่วยวางรากฐานเพื่ออนาคต\",\"ทำงานดีที่สุดเมื่อคุณใช้ทรัพย์สินอย่างมีธรรมะ ไม่ยึดติด หรือเห็นแก่ตัว\"]"::jsonb),
("2in1",2,1,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 1","[\"นำทรัพย์สินเข้ามาสู่เจ้าชะตาโดยตรง บางคนร่ำรวยจากรุ่นสู่รุ่น\",\"มักเป็นรุ่นแรกที่สร้างฐานะ และรุ่นลูกจะสืบทอดต่อ\",\"เหมาะกับงานธุรกิจ และสามารถสร้างรายได้ให้คนอื่นได้ด้วย\",\"บางครั้งรับช่วงกิจการครอบครัวและดัดแปลงให้เข้ากับวิสัยทัศน์ตนเอง\",\"อาจมีความไม่มั่นใจในตัวเองเป็นระยะ ต้องฝึกความเชื่อมั่นในวิสัยทัศน์\",\"มักเป็นคนที่มีภาพลักษณ์มั่งคั่ง คนรอบตัวเห็นเป็นคนมีทรัพย์\",\"รักครอบครัวใหญ่ และต้องการควบคุมสมาชิกในครอบครัวและการเงิน\",\"ขี้หวงการใช้จ่ายของคนในบ้าน อาจทะเลาะกับคนในบ้านเรื่องเงิน\",\"มีแนวโน้มหวงคู่รัก ควบคุม หรือขี้หึง\",\"เหมาะกับงานด้านตลาด การขาย การเป็นหัวหน้าทีม หรือเจ้าของกิจการ\"]"::jsonb),
("2in2",2,2,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 2","[\"ส่งผลแรง มีอำนาจควบคุมการเงินโดยตรง\",\"ใส่ใจการเก็บเงิน ตรวจสอบรายรับรายจ่ายอย่างใกล้ชิด\",\"ขยันสร้างรายได้ ต้องการความมั่นคงทางการเงินสูง\",\"อาจเข้มงวดเกินไปกับลูกหลานหรือคนที่พึ่งพา เช่น ไม่ชอบให้ใช้เงินฟุ่มเฟือย\",\"มีความภูมิใจในชาติตระกูลหรือพื้นเพของตน บางครั้งมากเกินไป\",\"ถ้าเป็นดาวบาปเคราะห์ เช่น Saturn, Mars, Rahu จะยิ่งระวังเรื่องการสูญเสียเงิน\",\"กลายเป็นเหมือน “ปู่โสมเฝ้าทรัพย์” พร้อมปกป้องสิ่งที่เป็นของตน\",\"ควรเรียนรู้การปล่อยวาง เปิดใจแบ่งปันเพื่อสร้างกรรมดีระยะยาว\"]"::jsonb),
("2in3",2,3,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 3","[\"เป็นนักสู้ทางการเงิน ต่อสู้เพื่อสิ่งที่ต้องการ\",\"มีค่านิยมและหลักการที่ชัดเจน และนำเสนอออกมาผ่านคำพูด\",\"เหมาะกับงานด้านสื่อ การพูด การเขียน เทคโนโลยี และโซเชียลมีเดีย\",\"ควรระวังการแสดงออกหรือถกเถียงที่รุนแรง หรือขาดความอ่อนโยน\",\"อาจมีปัญหาทะเลาะเรื่องเงินกับคู่รัก ต้องระวังคำพูด\",\"มีทักษะสูงในงานใช้มือ เช่น ดนตรี การเขียน งานฝีมือ การตลาด\",\"เหมาะกับงานขาย การเดินทาง และโฆษณา\",\"สามารถโน้มน้าวใจคนเก่ง ได้เงินจากการเจรจา\"]"::jsonb),
("2in4",2,4,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 4","[\"เป็นตำแหน่งที่ให้โชคเรื่องบ้าน อสังหาริมทรัพย์ และความสะดวกสบายในชีวิต\",\"ถ้ามีดาวศุภเคราะห์ร่วม เช่น Venus, Moon, Jupiter จะมีบ้านที่งดงามตามที่หวัง\",\"เหมาะกับการทำเงินจากอสังหา ขายบ้าน หรือทำธุรกิจจากบ้าน\",\"ถ้าเป็นดาวบาปเคราะห์ร่วม อาจมีปัญหาหนี้สิน หรือกู้บ้านหนักเกินไป\",\"มีทักษะด้านศิลปะ ดนตรี งานฝีมือ สามารถนำไปใช้สอนผู้อื่นได้\",\"เป็นเรือนแห่งการศึกษา เหมาะกับการเป็นติวเตอร์ออนไลน์ หรือเปิดสอนที่บ้าน หรือด้านศิลปะ\"]"::jsonb),
("2in5",2,5,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 5","[\"มีความสามารถสร้างสรรค์ในการหาเงิน เหมาะกับธุรกิจที่ใช้ไอเดีย\",\"แม้อยู่ในสถานการณ์ยากลำบาก ก็สามารถทำกำไรได้\",\"ต้องระวังการใช้ความสามารถในทางที่ผิด เช่น ทำสิ่งผิดกฎหมาย\",\"มีรายได้จากการสอน การให้ความรู้ หรืองานเกี่ยวกับเด็ก\",\"ถ้าได้รับการศึกษาดี จะเปลี่ยนเป็นรายได้โดยตรง\",\"ชอบเสี่ยง เช่น หุ้น การพนัน ลอตเตอรี แต่ต้องดูดาวประกอบ\",\"ลูกหลานจะมีความสามารถด้านการหาเงิน ได้อิทธิพลจากเจ้าชะตา\"]"::jsonb),
("2in6",2,6,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 6","[\"เป็นนักสู้ที่หาเงินจากการเอาชนะศัตรู คู่แข่ง หรือสถานการณ์ยากลำบาก\",\"ถ้าเป็นดาวศุภเคราะห์ เช่น Moon, Venus, Jupiter, Mercury จะชนะอย่างสง่างาม\",\"ถ้าเป็นดาวบาปเคราะห์ อาจพ่ายแพ้ทางการเงิน แต่ก็ลุกขึ้นสู้ได้เสมอ\",\"มีจิตวิญญาณนักต่อสู้ ล้มแล้วลุก ชนะจากความพยายามไม่ย่อท้อ\",\"ต้องดูดาวร่วมในเรือนที่ 6 ว่าแข่งกับใคร หรือขัดแย้งกับใครในชีวิต\"]"::jsonb),
("2in7",2,7,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 7","[\"มีแนวโน้มเกิดปัญหาความสัมพันธ์ทั้งเรื่องคู่ครองและหุ้นส่วนธุรกิจ\",\"ความขัดแย้งในครอบครัว โดยเฉพาะเรื่องการเงินอาจเกิดขึ้น\",\"อาจรู้สึกไม่พอใจในความสัมพันธ์ เปลี่ยนคู่บ่อย ต้องใช้เวลาศึกษาให้ดีก่อนตัดสินใจ\",\"ถ้าเป็นดาวบาปเคราะห์ (Mars, Saturn, Rahu, Ketu) จะวิจารณ์คู่ครองมากเกินไป\",\"ดีมากสำหรับงานให้คำปรึกษา เช่น แพทย์ จิตแพทย์ นักบำบัด นักจิตวิทยา\",\"ถ้าเป็นดาวศุภเคราะห์ เช่น Moon, Venus, Jupiter, Mercury จะมีมนุษย์สัมพันธ์ดี\",\"หาเงินได้จากการทำงานกับคนอื่น เช่น องค์กรใหญ่ การทำงานเป็นทีม\",\"ระวังหุ้นส่วนธุรกิจที่ไม่น่าไว้ใจ อาจทำให้เสียเงิน\",\"ชอบอยู่กับคนอื่น หาเงินจากสังคม คนรอบข้าง ลูกค้า ฯลฯ\"]"::jsonb),
("2in8",2,8,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 8","[\"มีศักยภาพสร้างความมั่งคั่งโดยเฉพาะผ่านอสังหาริมทรัพย์ มรดก หรือการลงทุน\",\"อาจมีปัญหาทางการเงินในชีวิตสมรสโดยเฉพาะเรื่องทรัพย์สินร่วม\",\"มีปัญหากับพี่น้องที่โตกว่า เรื่องทรัพย์ หรืออำนาจในครอบครัว\",\"มีรายได้จากคนอื่น เช่น คู่ครอง หุ้นส่วน หรือการรับมรดก\",\"ถ้ามีความลับในเรื่องการเงิน ธุรกิจ หรือภาษี อาจย้อนกลับมาทำร้ายในอนาคต\",\"วงจรการเงินขึ้นๆ ลงๆ ต้องปรับตัวตามสถานการณ์\",\"ถ้ามีดาวศุภเคราะห์ร่วม จะพลิกสถานการณ์ไปในทางที่ดี\",\"มีทักษะการฟื้นฟูฐานะ แม้เกิดวิกฤตก็สามารถกลับมาได้\"]"::jsonb),
("2in9",2,9,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 9","[\"เป็นตำแหน่งที่โชคดีด้านการเงิน ได้รับพรจากโชคชะตา\",\"แต่มีความกลัวเรื่องการใช้เงิน หรือไม่กล้าใช้จ่าย\",\"ยึดติดกับการเก็บเงินมากเกินไป ทำให้พลังเงินไม่หมุนเวียน\",\"ถ้าปรับทัศนคติได้ จะเพิ่มโชคทางการเงินอย่างมาก\",\"มีศรัทธาในศาสนา หลักธรรม จริยธรรมที่มั่นคง\",\"ได้รายได้จากการเรียนรู้ การสอน การศึกษาสูง\",\"ขยายธุรกิจครอบครัวสู่ต่างประเทศได้ดี\",\"มีความผูกพันกับพ่อ หรือได้สืบทอดธุรกิจจากพ่อ\"]"::jsonb),
("2in10",2,10,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 10","[\"มีชื่อเสียงในสายงาน อาชีพให้เกียรติ และมีความน่าเชื่อถือ\",\"งานที่ใช้คำพูดจะเสริมรายได้ เช่น ครู นักพูด นักข่าว การเมือง\",\"ครอบครัวต้นตระกูลมีส่วนสนับสนุนอาชีพ เช่น ให้ทุน หรือให้ความรู้\",\"ต้องเรียนรู้ตลอดเวลา การศึกษาเสริมอาชีพโดยตรง\",\"ระวังการคบคนผิด อาจส่งผลเสียต่อชื่อเสียงและโอกาสทางการเงิน\",\"ไม่ควรเล่นหุ้นหรือเสี่ยงโชค อาจเสียหนัก\",\"ถ้าขี้เกียจหรือทำงานไม่เต็มที่จะได้รับผลกรรมทันที เช่น ตกงาน\",\"ให้ระวังเรื่องการให้เงินลูก อาจทำให้ความสัมพันธ์แย่ลง\"]"::jsonb),
("2in11",2,11,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 11","[\"เป็นตำแหน่งที่ดีมาก รายได้เพิ่ม กำไรมาโดยง่าย\",\"เหมาะกับการลงทุนระยะยาว เช่น อสังหาริมทรัพย์\",\"การทำธุรกิจส่วนตัว หรือเป็นนายตัวเองจะรุ่ง\",\"มีโอกาสร่ำรวยมากขึ้นหลังแต่งงาน\",\"อาจมีความขัดแย้งกับแม่เรื่องเงิน หรือวิธีการสอนของครอบครัว\",\"เป็นคนมีวินัยและรับผิดชอบในงาน\",\"ถ้าทำงานประจำจะได้เลื่อนขั้น มีเพื่อนร่วมงานสนับสนุน\",\"รู้จักหาทางสร้างรายได้ให้ตนเองแบบไม่พึ่งใคร\"]"::jsonb),
("2in12",2,12,"เจ้าเรือนที่ 2 อยู่ในเรือนที่ 12","[\"เป็นนักผจญภัยทางการเงิน ชอบเริ่มต้นใหม่ ไม่กลัวเปลี่ยนงานหรือที่อยู่\",\"ชอบใช้จ่าย ฟุ่มเฟือย และไม่ชอบจัดการเรื่องการเงิน\",\"อาจต้องการคนช่วยดูแลด้านการเงินส่วนตัว\",\"กลัวการดูยอดเงินในบัญชี ไม่อยากเจอความจริง\",\"แต่มีจิตใจเอื้อเฟื้อ ชอบทำบุญ ทำให้ได้กรรมดี\",\"แปลกคือ แม้จะจัดการเงินตัวเองไม่เก่ง แต่ช่วยจัดการเงินคนอื่นได้ดี\",\"เหมาะกับงานบริหารการเงินของผู้อื่น เช่น กองทุน การลงทุนต่างประเทศ\",\"อาจมีปัญหากับลูก เช่น เด็กดื้อ ต่อต้าน หรือต้องรับผิดชอบมากเกินไป\",\"การศึกษามักไม่ต่อเนื่อง เรียนช้า หรือเปลี่ยนอาชีพกลางทาง\",\"ต้องเรียนรู้เรื่องการบริหารทรัพย์ ความมั่นคง และการสร้างวินัยทางการเงิน\",\"เจ้าเรือนที่ 3\",\"เรือน 3 เป็นเรือนที่เข้าใจผิดกันบ่อย ที่มักตีความว่าแค่พี่น้อง การสื่อสาร และการเดินทาง\",\"เรือนนี้แท้จริงแล้วแสดงถึง \\\"ความพยายาม\\\" และ \\\"ความกล้า\\\" ของเจ้าชะตา\",\"เป็นเรือนของการลงมือทำ การแข่งขัน การบุกเบิก และการใช้มือในการสร้างชีวิต\",\"เรือนนี้สัมพันธ์กับราศีมิถุน (Gemini) ซึ่งไม่ได้หมายถึงแฝด แต่หมายถึงชายหญิงในการสร้างชีวิต (สัญลักษณ์แห่งการมีเพศสัมพันธ์และการให้กำเนิด)\",\"จึงเป็นเรือนที่เกี่ยวข้องกับพลังสร้างสรรค์ พลังทางเพศ ความปรารถนา และความทะเยอทะยานทางอัตตา\",\"เป็นเรือนแห่งกรรม เพราะสิ่งที่เราทำซ้ำๆ จากมือเรา สร้างผลลัพธ์อย่างลึกซึ้งในชีวิต\",\"ยังเป็นเรือนของพี่น้อง (โดยเฉพาะคนน้อง) เพื่อนบ้าน คนใกล้ตัว และผู้ร่วมงานที่มีความผูกพันใกล้ชิด\",\"เจ้าเรือนที่ 3 ถือว่ามีพลังแบบดาวอังคาร ไม่ว่าดาวดวงไหนจะเป็นเจ้าของเรือน ก็จะแบกพลังการต่อสู้ กล้าหาญ และแม้แต่ความขัดแย้งไปยังเรือนที่มันไปสถิต\"]"::jsonb),
("3in1",3,1,"🜂 เจ้าเรือนที่ 3 อยู่ในเรือนที่ 1 (ลัคนา)","[\"เจ้าเรือนที่ 3 ซึ่งมีพลัง “อังคาร” (พลังแห่งความกล้า ความพยายาม ความทะเยอทะยาน) ได้ย้ายมาอยู่ในลัคนา หรือราศีเกิด\",\"ส่งผลให้เจ้าชะตาเป็น “นักเริ่มต้น” โดยธรรมชาติ มีความกล้า มีพลังชีวิตแรงกล้า\",\"มีความคิดเป็นของตนเอง ไม่ชอบทำตามระบบหรือคำสั่ง ถ้าอยู่ในองค์กรก็จะทำในแบบของตน\",\"เป็นผู้ประกอบการโดยสัญชาตญาณ แม้ไม่ได้มีธุรกิจของตนเอง ก็คิดอย่างเจ้าของ\",\"มีความสามารถในการลงมือทำสิ่งใหม่ เรียนรู้เร็ว ฉลาดเฉียบคม โดยเฉพาะเชิงตรรกะหรือคณิตศาสตร์\",\"เป็นนักสื่อสารที่กล้าแสดงออก มีความสามารถในการตัดสินใจ\",\"ถ้าเจ้าเรือนที่ 3 เป็นดาวอังคารโดยตรง หรืออยู่ร่วมกับอังคารในเรือนนี้ จะมีพลังนักรบสูง เป็นคู่แข่งที่อันตราย\",\"ถ้าอยู่ร่วมกับพฤหัส เจ้าเรือนที่ 3 จะต่อสู้เพื่อความยุติธรรม\",\"มีแรงขับเคลื่อนชีวิตจากอัตตาและความพยายามส่วนตัวสูงมาก\",\"ใส่ใจสุขภาพกาย อาจรักการออกกำลังกาย วิ่ง ฟิตเนส ดูแลรูปร่าง\"]"::jsonb),
("3in2",3,2,"🜃 เจ้าเรือนที่ 3 อยู่ในเรือนที่ 2","[\"เจ้าเรือนที่ 3 ย้ายไปอยู่เรือนที่ 2 ซึ่งเป็นเรือนของปาก คำพูด การกิน การเงิน และค่านิยม\",\"การใช้พลังงานอังคารมาอยู่ที่ “ปาก” อาจทำให้พูดตรงเกินไป ขัดแย้งในความสัมพันธ์\",\"อาจมีแนวโน้มกินหรือดื่มเกินควร ควรระวังปัญหาน้ำหนักหรือการเสพติดอาหาร\",\"เป็นผู้มีค่านิยมที่แน่นแฟ้น เชื่อมั่นในหลักการของตนเอง และพูดออกมาอย่างชัดเจน\",\"อาจเกิดปัญหากับคู่สมรสหรือพี่น้องจากความต่างของค่านิยม เพราะตำแหน่งนี้เป็น 6 เรือนจากเรือนที่ 7 (คู่ครอง)\",\"ด้านบวก: เจ้าเรือนที่ 3 ในเรือน 2 หมายถึง การใช้มือทำเงิน เช่น ธุรกิจ ครอบครัว การลงทุน หรือค้าขาย\",\"มีศักยภาพสร้างความมั่งคั่ง โดยเฉพาะถ้าเชื่อมกับกิจการครอบครัว\",\"อาจมีการพูดเกี่ยวกับเงินหรือค่านิยมบ่อย ๆ จึงต้องระวังเรื่องคำพูด\"]"::jsonb),
("3in3",3,3,"🜁 เจ้าเรือนที่ 3 อยู่ในเรือนที่ 3","[\"เป็นตำแหน่งที่ “ทรงพลังมาก” เพราะดาวเจ้าเรือนปกครองบ้านของตัวเอง\",\"ให้ความสามารถทางการสื่อสารเด่นชัด มีทักษะในการเขียน การพูด การเล่าเรื่อง และการตลาด\",\"พี่น้องมักมีบทบาทสำคัญในชีวิต อาจได้รับการสนับสนุน หรือเป็นหุ้นส่วนที่ดี\",\"ความมั่งคั่งเกิดจากการลงมือทำ ไม่จำเป็นต้องดิ้นรนมาก เพราะตำแหน่งนี้เป็น 9 เรือนจากเรือนที่ 11 (ลาภะ)\",\"ความสัมพันธ์กับพ่ออาจมีแรงผลักดันหรือกดดันในชีวิต ถ้าไม่มีบาปเคราะห์ถือว่าเป็นตำแหน่งที่ดีมาก\",\"เหมาะกับอาชีพด้านสื่อ การเขียน การบรรยาย การแสดง ศิลปะ หรือแม้แต่กลายเป็นคนดัง\"]"::jsonb),
("3in4",3,4,"🜄 เจ้าเรือนที่ 3 อยู่ในเรือนที่ 4","[\"ความพยายามถูกนำมาใช้เพื่อความสุข ความมั่นคง และครอบครัว\",\"เจ้าชะตาเป็นคนที่ “พยายามเพื่อความสุข” และพร้อมจะละทิ้งสิ่งที่ไม่ทำให้รู้สึกดี\",\"สนใจเรื่องอสังหาริมทรัพย์ บ้าน ที่ดิน และการสะสมทรัพย์สินอย่างมั่นคง\",\"รักความเป็นส่วนตัว แต่ก็มีความสามารถเชิงสังคมสูง และผูกมิตรได้ดี\",\"ถ้าใช้พลังงานไม่เหมาะสม อาจเกิดการโต้แย้งในบ้าน เพราะ Mars energy อยู่ในเรือนแห่งหัวใจ\",\"เหมาะจะลงทุนในทรัพย์สินระยะยาวมากกว่าการเสี่ยงโชคหรือการลงทุนสั้น ๆ\",\"มีศักยภาพสร้างชื่อเสียงในวงกว้าง เพราะเรือนที่ 10 (ชื่อเสียง) อยู่ในเรือนตรงข้าม\",\"เหมาะกับงานที่ต้องสร้างความเชื่อมโยงกับคนจำนวนมาก เช่น การสื่อสาร การบำบัด งานสังคม\"]"::jsonb),
("3in5",3,5,"เจ้าเรือนที่ 3 อยู่ในเรือนที่ 5","[\"อาจมีความสัมพันธ์รักหลายครั้ง โดยเฉพาะรักแรกมักไม่ราบรื่น\",\"บ่งบอกถึงพลังทางเพศสูง และมีความต้องการทางอารมณ์สูงในความสัมพันธ์\",\"อาจสับสนเรื่องการเลือกคู่ เพราะมีหลายตัวเลือกมากเกินไป\",\"เป็นคนที่โหยหาความรักอย่างแท้จริง อยากมีความรักที่ลึกซึ้งและยืนยาว\",\"มีความกล้าในการเสี่ยง กล้าเริ่มสิ่งใหม่โดยไม่ลังเล\",\"ถ้าเจ้าเรือนที่ 3 เป็นดาวศุภเคราะห์ เช่น ศุกร์ หรือพฤหัส จะได้กำไรจากการลงทุนหรือกิจกรรมเสี่ยง\",\"เก่งด้านกีฬา ศิลปะ การแสดง งานสร้างสรรค์ทุกชนิด\",\"เรียนรู้เร็วทั้งเรื่องลึกและเรื่องทั่วไป มีพรสวรรค์ในการสอนและถ่ายทอด\",\"จุดอ่อนคือความหุนหันพลันแล่น มักตัดสินใจโดยไม่คิดให้รอบคอบ\",\"ควรฝึกความนิ่งและพิจารณาก่อนลงมือ\"]"::jsonb),
("3in6",3,6,"เจ้าเรือนที่ 3 อยู่ในเรือนที่ 6","[\"อาจมีปัญหากับพี่น้อง โดยเฉพาะการทะเลาะเบาะแว้งหรือความห่างเหิน\",\"ต้องแข่งขันในชีวิตตลอดเวลา เช่น กับเพื่อนร่วมงานหรือในที่ทำงาน\",\"ชีวิตมักมีอุปสรรคให้ต้องฝ่าฟัน แต่มีพลังใจในการต่อสู้สูง\",\"เหมาะกับงานกฎหมาย การแพทย์ พยาบาล จิตแพทย์ หรืออาชีพที่ช่วยเหลือผู้มีปัญหา\",\"ถ้ามีดาวศุภเคราะห์ร่วม เช่น ศุกร์ จะมีปัญหาในความสัมพันธ์ (โดยเฉพาะชาย)\",\"ถ้ามีดาวบาปเคราะห์ร่วม เช่น อังคาร จะเกิดการแข่งขันสูงมากในชีวิต\",\"เจ้าเรือนที่ 3 ให้ความกล้า เมื่ออยู่ในเรือนที่ 6 ยิ่งกล้าชนปัญหา\",\"อาจป่วยบ่อยในบางช่วงชีวิต แต่มีความสามารถในการฟื้นตัวและดูแลสุขภาพได้ดี\"]"::jsonb),
("3in7",3,7,"เจ้าเรือนที่ 3 อยู่ในเรือนที่ 7","[\"เป็นตำแหน่งที่ทรงพลังเพราะอยู่ตรงข้ามลัคนา มีอิทธิพลต่อภาพลักษณ์และความสัมพันธ์\",\"มักมีความสัมพันธ์กับผู้มีอำนาจ เช่น ผู้บริหาร เจ้านาย หรือเจ้าหน้าที่รัฐ\",\"ต้องซื่อสัตย์ในความสัมพันธ์ ไม่อย่างนั้นจะเกิดผลกรรมชัดเจน\",\"เหมาะกับการทำธุรกิจของตัวเอง หรือทำงานร่วมกับผู้อื่นแบบมืออาชีพ\",\"ไม่ชอบฟังคำสั่งใครง่ายๆ ยกเว้นผู้ที่ตนเคารพจริง\",\"ความสัมพันธ์ต้องปรับอีโก้ลง เพราะเจ้าเรือนที่ 3 คืออีโก้ พออยู่เรือน 7 จะชนกับเรื่องความรักและการประนีประนอม\",\"ถ้าดาวนี้เป็นบาปเคราะห์ ความสัมพันธ์ทางเพศอาจมีปัญหา หรือมีความขัดแย้งกับคู่\",\"ถ้ามีน้องชายหรือน้องสาว ต้องให้น้องแต่งงานไปก่อน พี่ถึงจะพบกับคู่ครอง\"]"::jsonb),
("3in8",3,8,"เจ้าเรือนที่ 3 อยู่ในเรือนที่ 8","[\"เป็นคนลึกซึ้ง ไม่เปิดเผย มีความคิดซ่อนเร้นหรือความลับในใจ\",\"อาจมีปัญหากับพี่น้อง เช่น การสูญเสีย แยกจาก หรือช่วยเหลือพี่น้องที่มีปัญหา\",\"มีพลังใจมหาศาล สามารถผ่านวิกฤติในชีวิตได้หลายครั้ง\",\"เก่งด้านการวิจัย งานจิตวิทยา โหราศาสตร์ วิชาเร้นลับ\",\"ชอบขุดคุ้ย หาความจริง ไม่พอใจในคำตอบผิวเผิน\",\"อาจมีอุบัติเหตุ หรือเหตุการณ์กระทันหันที่เปลี่ยนชีวิต\",\"ถ้าร่วมกับดาวบาปเคราะห์ การลงทุน การค้าร่วมอาจนำไปสู่การสูญเสีย\",\"ถ้าร่วมกับดาวศุภเคราะห์ อาจได้รับมรดก หรือช่วยเหลือจากพี่น้อง\"]"::jsonb),
("3in9",3,9,"เจ้าเรือนที่ 3 อยู่ในเรือนที่ 9","[\"อาจมีปัญหากับพ่อ ครู หรือผู้มีอำนาจทางศีลธรรม\",\"ชีวิตดีขึ้นอย่างมากหลังแต่งงานและมีลูก\",\"ชอบเดินทางไกล สนใจต่างประเทศ ศาสนา หรือปรัชญา\",\"ชีวิตมีจุดเปลี่ยนสำคัญหลังการตั้งหลักเรื่องความรักและครอบครัว\",\"ถ้าเจ้าเรือนที่ 3 เป็นบาปเคราะห์ การเรียนสูงอาจสะดุด หรือมีปัญหากับครู\",\"เหมาะกับงานต่างประเทศ การสอน การให้คำปรึกษา การเผยแพร่หลักธรรม\"]"::jsonb),
("3in10",3,10,"เจ้าเรือนที่ 3 อยู่ในเรือนที่ 10","[\"ทำงานหนัก สม่ำเสมอ และมีความก้าวหน้าในอาชีพอย่างมั่นคง\",\"เหมาะกับธุรกิจส่วนตัวหรือการเป็นผู้ประกอบการ\",\"มีความกล้าและริเริ่มในที่ทำงาน ทำสิ่งที่คนอื่นไม่กล้าทำ\",\"อาจมีชื่อเสียงจากความคิดใหม่หรือความกล้าหาญในอาชีพ\",\"ความสัมพันธ์รักอาจไม่มั่นคงในช่วงต้นชีวิต เพราะมีเสน่ห์และดึงดูดใจเพศตรงข้ามมาก\",\"ต้องระวังไม่ให้ด่วนตัดสินใจเรื่องความรักโดยดูแค่รูปลักษณ์\"]"::jsonb),
("3in11",3,11,"เจ้าเรือนที่ 3 อยู่ในเรือนที่ 11","[\"มีแนวคิดสร้างสรรค์ทางรายได้ มักหาโอกาสใหม่ๆ เสมอ\",\"เป็นคนช่างเข้าสังคม มีเพื่อนเยอะ รู้จักคนหลากหลายวงการ\",\"รายได้เกิดจากความพยายามแบบไม่หนักเกินไป แต่ได้ผลดี\",\"ชอบเรียนรู้ และมักได้ประโยชน์จากการศึกษา\",\"เดินทางบ่อยโดยเฉพาะต่างประเทศ ชอบผจญภัย\",\"ถ้าเจ้าเรือนที่ 3 เป็นดาวศุภเคราะห์ พี่น้องให้โชคหรือเป็นแหล่งสนับสนุน\"]"::jsonb),
("3in12",3,12,"เจ้าเรือนที่ 3 อยู่ในเรือนที่ 12","[\"ใช้จ่ายเก่ง ชอบซื้อของที่ไม่จำเป็น ควรระวังการเงิน\",\"มีแนวโน้มเสียสละหรือให้พี่น้องอยู่เสมอ บางครั้งต้องช่วยเหลือพี่น้องที่อยู่ไกล\",\"ลดอีโก้ลงเมื่ออายุมากขึ้น กลายเป็นคนอ่อนโยนและมีเมตตา\",\"เหมาะกับงานในองค์กรใหญ่ เช่น โรงพยาบาล โรงเรียน เรือนจำ\",\"ชอบความสงบ การปลีกวิเวก การทำสมาธิ หรือเรียนรู้เรื่องลึกลับ\",\"เหมาะกับงานช่วยเหลือสัตว์ คนไร้บ้าน หรือผู้ด้อยโอกาส\",\"รู้เรื่องลึกลับ เช่น โหราศาสตร์ พลังงาน จิตวิญญาณ ด้วยสัญชาตญาณ\",\"เจ้าเรือนที่ 4\",\"เป็นเจ้าของความสุข, ความสงบในใจ, ความอุดมสมบูรณ์ทางอารมณ์\",\"ผู้พิทักษ์จิตใจ, ผู้มอบความสุขทั้งภายนอก (บ้าน รถ ที่ดิน) และภายใน (ความสงบใจ)\",\"ไม่ว่าจะเป็นดาวบาปอย่าง ดาวอังคาร, เสาร์, ราหู ก็ยังให้ผลดี เพราะ “หน้าที่ของเจ้าเรือน 4 คือให้คุณอยู่ในโลกนี้ต่อไปด้วยความรู้สึกว่า ชีวิตมีค่า”\",\"มีอิทธิพลต่อ:\",\"แม่ – ความสัมพันธ์เชิงอารมณ์กับแม่\",\"การศึกษา – โดยเฉพาะการศึกษาที่ให้ความรู้สึกเติมเต็ม\",\"ทรัพย์สินและที่อยู่ – รวมถึงโอกาสการถือครองบ้านหรือที่ดิน\",\"ประเทศบ้านเกิดและความผูกพันทางวัฒนธรรม\"]"::jsonb),
("4in1",4,1,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 1","[\"คุณมักเป็นคนที่ดูอบอุ่น มีเสน่ห์ และดึงดูดผู้คน\",\"ความสุขขึ้นอยู่กับตัวคุณเอง ต้องสร้างจากภายใน\",\"บ้านและวัยเด็กมีผลต่อบุคลิกภาพอย่างมาก\",\"มีความผูกพันกับแม่หรือบ้านเกิดอย่างลึกซึ้ง\",\"ชอบอยู่ใกล้บ้านหรือที่ที่รู้สึกปลอดภัย\",\"ถ้าเจ้าเรือนนี้มีบาปเคราะห์ อาจทำให้ไม่มั่นคงภายใน\",\"ให้ความสำคัญกับความสงบ ความสบาย และความมั่นคง\"]"::jsonb),
("4in2",4,2,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 2","[\"ความสุขมาจากครอบครัว รายได้ และการสะสมทรัพย์\",\"บ้านวัยเด็กมีผลต่อทัศนคติเรื่องเงินและคุณค่าชีวิต\",\"มีโอกาสเก็บสะสมทรัพย์หรืออสังหาริมทรัพย์\",\"ใช้ความมั่งคั่งเพื่อสร้างความมั่นคงทางอารมณ์\",\"เด่นด้านการพูด การร้องเพลง หรือศิลปะเกี่ยวกับเสียง\",\"ได้รับการสนับสนุนจากคนใกล้ตัวในครอบครัว\"]"::jsonb),
("4in3",4,3,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 3","[\"ความสุขมาจากการสื่อสาร การเดินทาง หรือการเขียน\",\"กล้าแสดงออก มีความสามารถด้านมือและศิลปะ\",\"ผูกพันกับพี่น้องหรือเพื่อนบ้าน\",\"บ้านอาจเปลี่ยนแปลงบ่อย หรือย้ายบ่อย\",\"มีพรสวรรค์ด้านการเขียน พูด หรือสื่อสร้างสรรค์\",\"แสดงออกทั้งด้านแข่งขันและด้านอ่อนโยน\"]"::jsonb),
("4in4",4,4,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 4","[\"ตำแหน่งที่แข็งแรงที่สุด อยู่ในเรือนของตัวเอง\",\"รักบ้าน รักครอบครัว ผูกพันกับรากเหง้า\",\"ชีวิตจะข้องเกี่ยวกับบ้านและที่อยู่อาศัยตลอด\",\"แม่มีบทบาทสำคัญในชีวิต\",\"สนใจอสังหาริมทรัพย์และการจัดการบ้าน\",\"แสวงหาความสงบและความปลอดภัย\",\"เมื่อได้อยู่ในสถานที่มั่นคง ชีวิตจะเติบโตดีมาก\"]"::jsonb),
("4in5",4,5,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 5","[\"เป็นราชโยค ให้ชื่อเสียงและความนิยม\",\"ผู้คนมองว่าคุณมีเมตตาและเกียรติ\",\"มีลูกศิษย์ หรือผู้ติดตามจำนวนมาก\",\"ประสบความสำเร็จในการศึกษาและความคิดสร้างสรรค์\",\"รักความรู้ทุกประเภท ไม่จำกัดแค่วิชาการ\",\"สนใจศาสตร์ลึกลับ เช่น โหราศาสตร์ จิตบำบัด\",\"ได้รับการสนับสนุนจากผู้เชี่ยวชาญในสายลับเฉพาะ\",\"ทรัพย์สินเพิ่มขึ้นตลอดชีวิต\",\"กล้ารับความเสี่ยง ซึ่งบางครั้งได้ผลตอบแทนสูง\"]"::jsonb),
("4in6",4,6,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 6","[\"วัยเด็กมีปัญหากับแม่ หรือแม่มีปัญหาขณะคลอด\",\"เป็นนักสู้โดยธรรมชาติ มีความสามารถด้านแข่งขัน\",\"มีพลังในการเยียวยาและเปลี่ยนแปลงชีวิตคน\",\"ได้รับการสนับสนุนจากพ่อ ศาสนา และความเชื่อ\",\"ต่างแดนเปลี่ยนชีวิตอย่างลึกซึ้ง\",\"มีแนวโน้มจะเปลี่ยนบ้านหรือที่อยู่บ่อย\",\"อารมณ์โกรธมาเร็ว ต้องฝึกควบคุมจิตใจ\",\"ที่ทำงานควรหลีกเลี่ยงความขัดแย้ง เพื่อความสงบ\"]"::jsonb),
("4in7",4,7,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 7","[\"เป็นคนอิสระ ไม่ฟังใคร แม้กระทั่งแม่\",\"รักงานและการสร้างชื่อในสังคม\",\"เรียนเก่ง และได้รับเกียรติ\",\"ต้องการหารายได้เอง ไม่พึ่งครอบครัว\",\"มีชื่อเสียงในวงสังคม\",\"ไม่ชอบพูดต่อหน้าคนเยอะ แต่พูดดีแบบตัวต่อตัว\",\"เหมาะกับธุรกิจหรือความสัมพันธ์แบบตัวต่อตัว\",\"ความรักมักดี ยกเว้นมีดาวบาปรุนแรง\"]"::jsonb),
("4in8",4,8,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 8","[\"บ้านเกิดมีปัญหา อาจไม่กลับไปอยู่ที่เดิม\",\"พ่อแม่อาจหย่าร้าง มีผลต่อจิตใจ\",\"ความสัมพันธ์กับลูกอาจเป็นเรื่องลับ เช่น แท้ง ลูกไม่เปิดเผย\",\"ไม่ชอบเปิดเผยเรื่องครอบครัวหรือลูก\",\"ชีวิตรักไม่ธรรมดา อาจไม่สนใจเรื่องเพศสัมพันธ์\",\"มีความสัมพันธ์เปลี่ยนแปลงเร็วหรือซับซ้อน\",\"ได้รับการสนับสนุนจากเพื่อนและเครือข่าย\",\"ชีวิตขับเคลื่อนโดยวงสังคมหรือเพื่อน\"]"::jsonb),
("4in9",4,9,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 9","[\"เป็นราชโยค ความสุขมาจากศาสนา ปรัชญา และการเรียนรู้\",\"รักการเรียนทั้งทางโลกและทางธรรม\",\"ชอบพิธีกรรม การเดินทางจิตวิญญาณ\",\"วัยเด็กอาจขาดความอบอุ่นจากแม่\",\"ต่างแดนหรือวัฒนธรรมต่างมีผลดี\",\"ได้รับการสนับสนุนจากครูหรือญาติฝ่ายพ่อ\",\"เป็นคนใจกว้าง รักการให้ทาน\",\"ความสัมพันธ์ดี เพราะให้มากกว่ารับ\"]"::jsonb),
("4in10",4,10,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 10","[\"ได้รับเกียรติจากผู้ใหญ่ หัวหน้าสนับสนุน\",\"งานต้องเป็นสิ่งที่รักจริง ๆ\",\"ที่ทำงานคือบ้านอีกหลัง ต้องรู้สึกอบอุ่น\",\"พ่อแม่อาจแยกทาง ทำให้ต้องพึ่งตนเอง\",\"สนใจเรื่องลึกลับ จิตวิทยา หรือการเยียวยา\",\"อาจมีแนวโน้มหมกมุ่นกับเงินหรือการกิน\",\"สนใจการแปรเปลี่ยน เช่น อัลเคมี การรักษา\"]"::jsonb),
("4in11",4,11,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 11","[\"บ้านมักเปลี่ยนแปลงบ่อย หาที่มั่นคงยาก\",\"เป็นคนเปิดใจ รักอิสระ และมีเมตตา\",\"ชอบช่วยเหลือผู้คน รักการกุศล\",\"มีเพื่อนใหม่เสมอ เปลี่ยนวงสังคมบ่อย\",\"ดึงดูดทางเพศสูง มีความสัมพันธ์หลายแบบ\",\"ลูกมีความสำคัญสูง เป็นศูนย์กลางชีวิต\",\"มีเมตตา เปิดใจ และรักช่วยเหลือผู้อื่น\"]"::jsonb),
("4in12",4,12,"เจ้าเรือนที่ 4 อยู่ในเรือนที่ 12","[\"บ้านวัยเด็กมีปัญหา หรือย้ายไกลตั้งแต่เด็ก\",\"อยู่ต่างแดนให้ผลดีมาก\",\"ชอบอยู่ลำพัง เข้าถึงจิตวิญญาณ\",\"มีศรัทธาในพระเจ้าแม้ไม่ต้องมีศาสนา\",\"ถ้าใช้ด้านลบ อาจหลีกหนีความจริงหรือขี้เกียจ\",\"ชอบทำงานในโรงเรียน โรงพยาบาล หรือองค์กรใหญ่\",\"รักสัตว์ โดยเฉพาะสัตว์เลี้ยงในบ้าน\",\"มีความสุขเมื่อได้ช่วยเหลือผู้ที่ต้องการ\",\"เจ้าเรือนที่ 5\",\"ลูก ความสุข manifestation ความคิดสร้างสรรค์\"]"::jsonb),
("5in1",5,1,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 1 (ลัคนา)","[\"เจ้าชะตามีสติปัญญาเฉียบแหลม มีความสามารถทางวิชาการ และมีสัมผัสพิเศษ\",\"อาจไม่มีบุตร หรือมีความท้าทายในการมีบุตร แต่มีความสุขจากการสอนและให้ความรู้\",\"เป็นคนมีพลัง กล้าหาญ มีความสามารถในการแข่งขัน ชอบแสดงออก\",\"มีแนวโน้มหลงตัวเอง รักความงาม ดูแลรูปลักษณ์อย่างมาก\",\"หากพลังถูกใช้ในทางสร้างสรรค์ จะประสบความสำเร็จทางด้านศิลปะ การแสดง หรือวิถีจิตวิญญาณ\",\"ความรักอาจเริ่มจากความรักตนเอง แล้วค่อยๆ พัฒนาเป็นความรักต่อผู้อื่น\"]"::jsonb),
("5in2",5,2,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 2","[\"มีแนวโน้มมีลูกหลายคน หรือมีความสุขกับการเลี้ยงลูกหลาน\",\"ได้รายได้จากความคิดสร้างสรรค์ การพูด การสอน หรือธุรกิจเกี่ยวกับอาหาร\",\"รักครอบครัว รักบ้าน มีความสุขกับการใช้ชีวิตแบบมั่นคง\",\"มีชื่อเสียงหรือเป็นที่ยอมรับในวงสังคมท้องถิ่น\",\"ชอบเก็บสะสมของ หรือสะสมความมั่งคั่งทางวัตถุ\",\"อาจหมกมุ่นกับการกิน หรือมีปัญหาเกี่ยวกับความสัมพันธ์กับอาหาร\"]"::jsonb),
("5in3",5,3,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 3","[\"มีพรสวรรค์ด้านการพูด การเขียน การแสดงออกผ่านสื่อ\",\"ใกล้ชิดกับพี่น้องหรือเพื่อนบ้าน แต่บางครั้งมีความขัดแย้ง\",\"ชอบเดินทางใกล้ ๆ หรือมีชีวิตชีวาในกิจกรรมประจำวัน\",\"อาจมีด้านลับๆ หรือมีความสนใจในสิ่งที่ไม่เปิดเผย\",\"หลีกเลี่ยงหนี้สิน มีแนวโน้มเก็บสะสมหรือระวังการใช้เงิน\",\"เหมาะกับงานด้านสื่อ งานเขียน หรือการตลาด\"]"::jsonb),
("5in4",5,4,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 4","[\"เป็นราชโยค — เจ้าเรือนตรีโกณไปอยู่เรือนเคนทร\",\"ความสุขมาจากบ้าน ความมั่นคง ที่อยู่อาศัย และความสัมพันธ์กับแม่\",\"ประสบความสำเร็จในเรื่องอสังหาริมทรัพย์ ที่ดิน หรือการทำงานในบ้าน\",\"มีทัศนคติที่ดีต่อการศึกษา การเรียนรู้ให้ความรู้สึกอบอุ่นและปลอดภัย\",\"อารมณ์มั่นคง มีความสุขจากความสงบ\",\"เป็นคนที่ให้ความสำคัญกับรากเหง้าและวัฒนธรรมของตนเอง\"]"::jsonb),
("5in5",5,5,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 5","[\"เป็นตำแหน่งที่เข้มแข็งมาก มีความสามารถทางศิลปะ การสอน และความรู้โดยธรรมชาติ\",\"มีความสุขจากการมีบุตร การเล่น การสอน และกิจกรรมสร้างสรรค์\",\"เป็นครูโดยธรรมชาติ แบ่งปันความรู้ให้ผู้อื่นได้ดี\",\"มีความเข้าใจเชิงลึกเกี่ยวกับจิตวิญญาณ ปรัชญา หรือศาสตร์ลึกลับ\",\"ลูกหลานอาจเป็นที่ภาคภูมิใจ หรือมีพรสวรรค์\",\"ทนทานต่ออุปสรรค ใช้ความรู้ในการฟื้นฟูชีวิตตนเองและผู้อื่น\"]"::jsonb),
("5in6",5,6,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 6","[\"อาจมีความขัดแย้งกับบุตร หรือมีปัญหาสุขภาพเกี่ยวกับลูกคนแรก\",\"เหมาะกับการรับบุตรบุญธรรม หรือดูแลสัตว์เลี้ยง\",\"พบความสุขจากการช่วยเหลือผู้อื่น การเยียวยา หรือการทำงานที่เกี่ยวกับสุขภาพ\",\"มีแนวโน้มเป็นนักกฎหมาย นักบำบัด หรือผู้แนะนำชีวิต\",\"การชำระหนี้กรรมในอดีตจะนำมาซึ่งความสุขและความสำเร็จ\",\"เป็นคนทำงานหนัก และมีจิตใจแห่งการรับใช้\"]"::jsonb),
("5in7",5,7,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 7","[\"รักความสัมพันธ์อย่างลึกซึ้ง โดยเฉพาะกับคู่ครอง\",\"เป็นคนมีเกียรติ ซื่อสัตย์ และรักษาคำพูด\",\"เปิดใจกว้างทางศาสนา เคารพในความเชื่อที่หลากหลาย\",\"รักการให้ความรู้ หรือให้คำปรึกษาในเชิงคู่ครองหรือสาธารณะ\",\"เหมาะกับการเป็นที่ปรึกษา ผู้สื่อสาร หรือผู้จัดการความสัมพันธ์\"]"::jsonb),
("5in8",5,8,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 8","[\"สนใจในเรื่องลึกลับ โหราศาสตร์ จิตวิญญาณ และศาสตร์ซ่อนเร้น\",\"อาจได้มรดก เงินจากคู่ครอง หรือประสบการณ์ทางการเงินเฉียบพลัน\",\"ควรระวังเรื่องรักลับ ๆ หรือปัญหาสุขภาพ (โดยเฉพาะเกี่ยวกับปอดหรือระบบหายใจ)\",\"ลูกอาจมีปัญหาสุขภาพ หรือมีความลับเกี่ยวกับลูก\",\"ต้องปฏิบัติธรรม และการทำสมาธิเพื่อเยียวยาตนเอง\",\"มีพลังแห่งการเปลี่ยนแปลงในระดับลึก\"]"::jsonb),
("5in9",5,9,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 9","[\"เยี่ยมยอดสำหรับการศึกษาสูง การตีพิมพ์ การเดินทาง หรือการเรียนรู้ในต่างแดน\",\"ลูกคนแรกอาจมีชื่อเสียง หรือบรรลุความสำเร็จ\",\"มีความสัมพันธ์ที่ดีมากกับบิดา อาจารย์ หรือผู้นำทางจิตวิญญาณ\",\"สนใจในธรรมะ ปรัชญา และแนวทางชีวิตที่มีความหมาย\",\"จิตใจมั่นคง มีศรัทธา และรักในการแสวงหาความรู้\"]"::jsonb),
("5in10",5,10,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 10","[\"เป็นราชโยค — ดีเด่นในเรื่องอาชีพ ชื่อเสียง และความเป็นผู้นำ\",\"เหมาะกับงานที่เกี่ยวข้องกับการศึกษา สื่อ การสื่อสาร หรือการแนะแนว\",\"ได้รับการยอมรับ มีชื่อเสียงในสายอาชีพ อาจถูกอิจฉา\",\"เป็นคนทำงานเก่ง มีพลังสร้างสรรค์ และมุ่งมั่นสูง\",\"อาจได้รับมรดก หรือชนะคู่แข่งในอาชีพ\"]"::jsonb),
("5in11",5,11,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 11","[\"รักสังคม เพื่อนฝูง และการมีส่วนร่วมในกิจกรรมชุมชน\",\"เป็นที่นิยม เข้ากับผู้อื่นได้ดี มีมนุษยสัมพันธ์เยี่ยม\",\"เรียนรู้ได้หลายแขนง เป็นผู้รักการเรียนรู้ตลอดชีวิต\",\"เหมาะกับการลงทุน มีโชคด้านการเงินและการยอมรับจากสาธารณะ\",\"อาจมีลูกหลายคน หรือได้รับพรในรูปแบบของความอุดมสมบูรณ์\"]"::jsonb),
("5in12",5,12,"เจ้าเรือนที่ 5 สถิตในเรือนที่ 12","[\"มีจิตวิญญาณสูง รักการปลีกวิเวก และมีความสัมพันธ์แน่นแฟ้นกับพระเจ้า\",\"ลูกอาจอยู่ไกล หรือมีเส้นทางชีวิตที่แตกต่างจากคนทั่วไป\",\"ต้องเรียนรู้การปล่อยวางในเรื่องลูก หรือผลลัพธ์ของความรัก\",\"เหมาะกับการใช้ชีวิตแนวสันโดษ ปฏิบัติธรรม หรืออาศัยในต่างแดน\",\"ได้ประโยชน์จากการอุทิศตนเพื่อผู้อื่น หรือการช่วยเหลือสัตว์\",\"ชีวิตอาจเปลี่ยนผ่านอย่างลึกซึ้งผ่านการอยู่ต่างแดน หรือสถานที่เงียบสงบ\",\"เจ้าเรือนที่ 6\"]"::jsonb),
("6in1",6,1,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 1 (ลัคนา)","[\"มีแนวโน้มจะโฟกัสกับตัวเองสูง ต้องการรับใช้ตัวเองมากกว่าผู้อื่น\",\"พลังจากเรือนที่ 6 ทำให้เกิดความเป็นปฏิปักษ์กับคนรอบข้าง โดยเฉพาะครอบครัว (เรือนที่ 2 จากตรงนี้)\",\"มีพลังแบบดาวเสาร์ (Shani) ซึ่งมักส่งผลลบต่อเรือนที่อยู่ติดกัน\",\"ดึงพลังจากดาวอังคารเข้าสู่ลัคนา ทำให้มีนิสัยก้าวร้าวหรือพร้อมจะเผชิญหน้า ไม่เกรงกลัวการพูดตรง\",\"มีแนวโน้มจะเกิดข้อขัดแย้งหรือคดีความ\",\"อาจมีปัญหาสุขภาพเรื้อรังตั้งแต่วัยเด็ก\",\"ความอ่อนแอภายในกลายเป็นสิ่งที่เด่นชัดในตัวบุคคล\",\"ถ้าควบคุมจุดอ่อนเหล่านี้ได้ จะช่วยลดความเสียหายได้มาก\",\"แม้มีความท้าทาย แต่สามารถประสบความสำเร็จทางการเงินและสร้างฐานะได้ด้วยตัวเอง\",\"มีความขัดแย้งหรือไม่สอดคล้องกับค่านิยมของครอบครัว\",\"มีความกล้าหาญสูง เป็นนักสู้ในชีวิต ไม่ยอมแพ้ง่าย\",\"แม้จะมีปัญหาสุขภาพ ก็สามารถลุกขึ้นสู้ใหม่ได้เสมอ\",\"ส่งผลต่อเรือนที่ 3 ทำให้มีความกล้าหาญและอาจได้ชัยจากการต่อสู้\",\"ส่งผลต่อเรือนที่ 7 อาจทำให้การแต่งงานล่าช้าหรือมีความขัดแย้งในความสัมพันธ์\"]"::jsonb),
("6in2",6,2,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 2","[\"กลายเป็นบุคคลสำคัญในครอบครัว แม้จะมีความขัดแย้งภายใน\",\"มีบทบาทเด่นในชุมชน เป็นผู้นำโดยธรรมชาติ\",\"มีความกล้าหาญและพูดตรง ไม่เกรงกลัว\",\"มีอิทธิพลจากคำพูดมาก เสียงพูดทรงพลัง\",\"ต้องระวังเรื่องการพูดปนเท็จหรือเติมแต่งเกินจริง อาจนำไปสู่ผลเสีย\",\"ชอบเดินทาง โดยเฉพาะไปต่างประเทศ\",\"ค่านิยมทางศีลธรรมมักได้จากวัฒนธรรมต่างถิ่น\",\"การใช้ชีวิตในบ้านอาจมีความไม่พอใจบ่อยครั้ง มีการย้ายถิ่นฐาน\",\"ทุ่มเทให้กับมิตรภาพและเครือข่ายสังคม ซึ่งจะให้การสนับสนุนอย่างดี\"]"::jsonb),
("6in3",6,3,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 3","[\"เรือนที่ 3 และ 6 มีพลังร่วมกันในเรื่องอัตตา ความขัดแย้ง และคดีความ\",\"พร้อมจะต่อสู้แม้ในเรื่องเล็กน้อย เป็นนักสู้เชิงเปรียบเปรย\",\"มีอารมณ์ร้อน โดยเฉพาะถ้าเป็นดาวบาป (Mars, Saturn, Rahu, Ketu) ที่ครองเรือนที่ 6\",\"จะเรียกร้องสิทธิ์ทันทีเมื่อรู้สึกว่าโดนเอาเปรียบ\",\"มักมีปัญหากับพี่น้อง หรืออย่างน้อยก็ไม่ลงรอยกัน\",\"อาจมีความห่างเหินจากครอบครัว ความขัดแย้งกับแม่ หรือพ่อ\",\"การเดินทางไกล ความสัมพันธ์กับผู้สอนหรือศาสนาอาจลำบาก\",\"ถ้าดาวที่ครองเรือนที่ 6 เป็นดาวศุภ (Sun, Moon, Jupiter) จะลดทอนความก้าวร้าวลง\",\"ถ้าเป็นดาวบาป จะมีความชัดเจนในการเผชิญหน้าสูง ต้องระวังความเครียดสะสม\",\"ด้านดีคือให้ความสามารถในการคิดริเริ่ม ธุรกิจ และความสำเร็จจากแนวคิดที่ทันสมัย\",\"ดึงดูดคู่แข่งเสมอ ต้องต่อสู้ตลอดเวลา\",\"ถ้าดาวเจ้าครองเรือนดี จะมีโอกาสได้รับชัยชนะในความขัดแย้ง\"]"::jsonb),
("6in4",6,4,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 4","[\"ความสัมพันธ์กับแม่มักไม่ราบรื่น อาจมีความขัดแย้งหรือบ้านไม่น่าอยู่ในวัยเด็ก\",\"มีบาดแผลในใจลึกๆ อันเกิดจากกรรมเก่า ต้องการการเยียวยา\",\"เรือนที่ 4 เป็นเรือนธาตุน้ำ ให้โอกาสในการชำระล้างและเปลี่ยนแปลงภายใน\",\"เจ้าชะตามักได้ประโยชน์จากข้อขัดแย้งหรือความท้าทาย แต่ต้องระวังความยึดติด\",\"มีแนวโน้มคิดวางแผนหรือวางกลยุทธ์มากเกินไปจนหมดพลัง\",\"อาจนำไปสู่ปัญหาสุขภาพถ้าใช้พลังงานผิดทาง\",\"เจ้าครองเรือนที่ 6 ไปยังเรือนที่ 4 ซึ่งเป็นเรือนที่ 11 จากตัวเอง ให้ผลด้านความสำเร็จ การเงิน บ้านที่ใหญ่ขึ้น\",\"อาจมีปัญหากับพี่น้องหรือบุตร โดยเฉพาะเรื่องความไว้เนื้อเชื่อใจ\",\"ส่งผลต่อเรือนที่ 10 ซึ่งคืออาชีพและชื่อเสียง ทำให้มีบางเป้าหมายที่ไม่สามารถบรรลุได้\",\"อย่างไรก็ตาม มีโอกาสประสบความสำเร็จด้านอื่นแทน\",\"เพิ่มพลังการวางแผน มีสติปัญญาดี แต่ควรหลีกเลี่ยงวิธีการลับลวงพราง\",\"มีความผันผวนทางโชคชะตา ต้องเรียนรู้ที่จะปรับตัว\"]"::jsonb),
("6in5",6,5,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 5","[\"มักมีความผันผวนในชีวิต บางครั้งรุ่งเรืองมีชื่อเสียง บางครั้งรู้สึกหลงทางหรือเผชิญปัญหารอบด้าน\",\"เจ้าครองเรือนที่ 6 มาอยู่ในเรือนที่ 5 ซึ่งเป็นตำแหน่งที่ “อยู่เบื้องหลังตัวเอง” (12 เรือนจากเรือนที่ 6) บ่งบอกถึงศัตรูที่ซ่อนอยู่ หรือศัตรูในใจ\",\"แต่เจ้าชะตาไม่ยอมจมอยู่กับสิ่งลบเหล่านี้ มีความเข้มแข็งทางใจ\",\"ตำแหน่งนี้ให้ความสุขสงบในใจ\",\"มีโอกาสเกิดความไม่ลงรอยกับบุตร โดยเฉพาะถ้าเจ้าครองเรือนที่ 5 อยู่ในเรือนไม่ดี\",\"อาจมีปัญหากับเพื่อนหรือเครือข่ายสังคม รู้สึกว่าคนรอบข้างไม่เข้าใจ หรือขัดขวางคุณ\",\"อย่างไรก็ตาม คุณมักจะไม่ยึดติดกับสิ่งเหล่านี้และมีใจที่ปล่อยวาง\",\"การที่เจ้าครองเรือนที่ 6 อยู่ในตำแหน่งเบื้องหลังตัวเอง (12 จากตัวเอง) เป็นสัญญาณดีเรื่องการปล่อยวางจุดอ่อนของตน\",\"เป็นตำแหน่งที่ดีในการฟื้นฟูสุขภาพ เพราะช่วยให้ปล่อยโรคภัยและปัญหาต่างๆ ได้ง่าย\",\"มีแนวโน้มพัฒนาในทางจิตวิญญาณสูง\",\"คู่ครองอาจเป็นผู้ช่วยเหลือ สนับสนุน ให้พลังใจในการรับมือกับศัตรูและความเหนื่อยล้า\",\"ต้องดูเจ้าครองเรือนที่ 7 ประกอบด้วยเพื่อยืนยันคุณภาพของคู่ครอง\"]"::jsonb),
("6in6",6,6,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 6","[\"ในช่วงต้นชีวิต อาจมีปัญหาและการท้าทาย แต่ภายหลังจะนำไปสู่ความตระหนักและบทเรียนที่ลึกซึ้ง\",\"โดยเฉพาะเมื่อเป็นดาวบาป เช่น เสาร์ (Shani), อังคาร (Mars), ราหู (Rahu) ต้องมีศีลธรรมสูง ไม่อย่างนั้นกรรมจะย้อนกลับมา\",\"ตำแหน่งนี้ให้จิตใจที่ไม่ยอมแพ้ “Never say die”\",\"มีแนวโน้มโต้แย้ง เถียง สู้เพื่อสิ่งที่เชื่อ มีไฟในการแข่งขัน\",\"มีความเห็นอกเห็นใจต่อคนที่ไม่เหมือนกับครอบครัวหรือพื้นเพของตน\",\"ใส่ใจสุขภาพอย่างมาก บางคนถึงขั้นเป็นสายฟิตเนส หรือรักสัตว์เล็ก ๆ\",\"มีความท้าทายกับบุตรหรือความสัมพันธ์กับเด็กในชีวิต อาจเกิดปัญหากับบุตรหนึ่งคนโดยเฉพาะ\",\"มีโอกาสปัญหาในความสัมพันธ์ เช่น การนอกใจ หรือขาดความซื่อสัตย์ ต้องระวังเป็นพิเศษ\",\"รายจ่ายขึ้นลงแรง อาจได้มากแต่ก็เสียมาก\",\"มีศัตรูแอบแฝง โดยเฉพาะจากต่างถิ่นหรือต่างประเทศ\",\"อาจเผชิญปัญหาเมื่อเดินทางต่างประเทศ แม้บางครั้งจะประสบความสำเร็จก็ตาม\",\"คำแนะนำ: ใช้ชีวิตแบบเรียบง่าย โฟกัสกับงาน ทำหน้าที่ให้ดีที่สุด จะนำไปสู่ความสำเร็จอย่างมาก\"]"::jsonb),
("6in7",6,7,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 7","[\"เรือนที่ 7 หมายถึงความสัมพันธ์ คู่ครอง และหุ้นส่วนทางธุรกิจ เจ้าครองเรือนที่ 6 เข้ามาทำให้เกิดความขัดแย้งในเรื่องเหล่านี้\",\"พลังของดาวเสาร์และดาวอังคารซึ่งเป็นลักษณะของเรือนที่ 6 ทำให้การแต่งงานล่าช้า หรือความสัมพันธ์มีความตึงเครียด\",\"หุ้นส่วนธุรกิจอาจกลายเป็นคู่แข่งมากกว่าพันธมิตร\",\"ด้านดี: เจ้าครองเรือนที่ 6 เป็นแหล่งของทักษะความสามารถ เมื่อมาอยู่ในเรือนธุรกิจ จะให้ผลดีมากเรื่องรายได้และความสำเร็จ\",\"มีทักษะตลาดสูง รู้จักจัดการงานและทำงานหนักได้ดี\",\"เรือนที่ 10 จากตำแหน่งนี้คือเรือนที่ 4 แสดงว่าได้รับความสุขจากการทำงาน\",\"เคล็ดลับ: ต้องมี “ทัศนคติการบริการ” (service attitude) ต่อคู่ครองและธุรกิจ จึงจะนำไปสู่ความสำเร็จ\"]"::jsonb),
("6in8",6,8,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 8","[\"เรือนที่ 6 และ 8 มีความสัมพันธ์ลึกซึ้งเกี่ยวกับกรรม โรค และการเปลี่ยนแปลง จึงเป็นตำแหน่งที่ทรงพลังและลึกลับ\",\"อาจมีวิกฤติสุขภาพอย่างเฉียบพลันหรือเรื้อรัง ซึ่งเป็นผลของกรรม\",\"อย่างไรก็ตาม เป็นตำแหน่งของการ “ชำระล้าง” และ “แปลงสภาพ” อย่างลึกซึ้ง (water house)\",\"มีพลังในการ “อ่านใจศัตรู” หรือรู้เจตนาของผู้อื่นอย่างลึกซึ้ง\",\"ถ้าใช้ในทางที่ไม่บริสุทธิ์ เช่น การวางแผนลับ การหลอกลวง จะสร้างกรรมร้ายทันที\",\"เหมาะสำหรับอาชีพที่เปลี่ยนแปลงชีวิตคนอื่น เช่น หมอ นักจิตวิทยา นักโหราศาสตร์ นักบำบัด นักเล่นแร่แปรธาตุ\",\"ถือเป็นหนึ่งในราชโยคะให้พลังแปลงชีวิตและจิตวิญญาณ\",\"ต้องระวังเรื่องความไม่ซื่อสัตย์ในความสัมพันธ์ เช่น ชอบคู่ของคนอื่น\",\"บ้านมรดกหรือทรัพย์ของผู้อื่นต้องได้มาด้วยความถูกต้อง ไม่เช่นนั้นจะเกิดปัญหาแรง\",\"ใช้พลังการเยียวยา\"]"::jsonb),
("6in9",6,9,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 9","[\"มีแนวโน้มจะได้ไปใช้ชีวิตในต่างประเทศ หรือเกี่ยวข้องกับวัฒนธรรมต่างชาติ\",\"อย่างไรก็ตาม การไปต่างแดนมักมีความยุ่งยาก เช่น เอกสาร การขอวีซ่า หรือปัญหาในการปรับตัว\",\"อาจมีความขัดแย้งในด้านการศึกษา โดยเฉพาะการศึกษาระดับสูง\",\"มักมีปัญหาหรือช่องว่างกับบิดา เช่น ขาดการเข้าใจ หรือความสัมพันธ์ที่ห่างเหิน\",\"ดวงโชคไม่สม่ำเสมอ บางช่วงโชคดีมาก แต่บางช่วงเหมือนตกต่ำสุดๆ แล้วกลับขึ้นมาใหม่ได้\",\"เป็นตำแหน่งที่ให้ความผันผวนทางโชคชะตาอย่างชัดเจน\",\"มีความสามารถในการทำงานอิสระ เหมาะกับงานฟรีแลนซ์หรือธุรกิจส่วนตัว\",\"ไม่เหมาะกับการทำงานในระบบราชการหรือภายใต้หัวหน้า เพราะมักมีปัญหากับผู้บังคับบัญชา\",\"ไม่เหมาะกับการมีหุ้นส่วนธุรกิจ เพราะอาจเกิดความขัดแย้งบ่อย\",\"ได้รับผลกระทบจากเรือนที่ 3 ซึ่งหมายถึงความสัมพันธ์กับพี่น้องอาจห่างเหิน หรือมีปัญหากัน\",\"คุณมีทักษะมากมาย และทักษะเหล่านี้ช่วยสร้างรายได้ให้คุณเอง\",\"เหมาะกับงานเขียน งานสื่อสาร บล็อกท่องเที่ยว งานในสื่อสารมวลชนโดยเฉพาะงานที่เกี่ยวกับการเดินทาง\",\"เพื่อนคือแรงสนับสนุนสำคัญในชีวิต ทั้งเพื่อนต่างชาติและในประเทศ\",\"อาจมีแนวโน้มจะเข้าสู่วงการการเมือง หรือทำงานเพื่อความเชื่อ อุดมการณ์\",\"ชอบเข้าร่วมกลุ่มทางสังคมหรือกิจกรรมร่วมอุดมการณ์ แม้จะมีความขัดแย้งบ้าง แต่ก็ได้ผลสำเร็จตามมา\"]"::jsonb),
("6in10",6,10,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 10","[\"เป็นตำแหน่งที่ดีมาก มีพลังในการขับเคลื่อนชีวิตอย่างแรงกล้า\",\"เจ้าชะตาทำงานหนักมาก ทุ่มเท 24 ชั่วโมงเมื่อเจองานที่รักหรือเส้นทางชีวิตที่ชัดเจน\",\"มีโอกาสเป็นผู้นำในองค์กรหรือชุมชน\",\"หัวใจของความสุขจากการทำงานมาจาก “การบริการ” และ “การช่วยเหลือผู้อื่น”\",\"มีพรสวรรค์ด้านการพูด มีคารมและดึงดูดใจคนฟังได้มาก\",\"อาจมีปัญหากับบิดา เช่น ห่างเหิน เจ็บป่วย หรือการสูญเสีย\",\"ความสัมพันธ์กับมารดาและชีวิตวัยเด็กอาจมีความตึงเครียดหรือประสบการณ์ที่ขาดความอบอุ่น\",\"มีศัตรูและคู่แข่งในหน้าที่การงานเยอะ แต่สามารถเอาชนะได้\",\"หากดาวประจำเรือนที่ 6 ไม่เสีย จะไม่มีใครสามารถทำร้ายคุณได้\",\"ได้รับการสนับสนุนจากผู้มีอำนาจ ผู้ใหญ่ที่เห็นคุณค่าความขยันของคุณ\",\"ต่างประเทศ การเดินทาง และปรัชญาเป็นสิ่งที่เยียวยาความเครียดภายใน\",\"ต้องระวังอย่าให้ความสัมพันธ์มารบกวนงาน ถ้าเรือนที่ 7 หรือเจ้าครองเรือนเสีย\",\"หากคู่ครองดี จะเป็นผู้ช่วยสนับสนุนด้านอาชีพอย่างมาก\"]"::jsonb),
("6in11",6,11,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 11","[\"เป็นตำแหน่งแปลก แต่ให้ผลดีมากในด้านรายได้และความสำเร็จ\",\"ยิ่งมีศัตรูหรือคู่แข่งมาก ยิ่งทำให้คุณได้ผลประโยชน์กลับคืนมาก\",\"เหมาะกับงานที่ต้องแข่งขันสูง เช่น การเมือง กีฬา ธุรกิจที่มีคู่แข่งชัดเจน\",\"ให้กำไรสูงจากความสามารถเฉพาะตัวและทักษะที่คุณมี\",\"เพื่อนบางคนอาจกลายเป็นศัตรู และศัตรูก็อาจกลายเป็นเพื่อน เป็นวงจรที่ผันผวน\",\"มีรายได้ดีมากจากความสามารถที่วัดผลได้จริง เช่น ศิลปะ การขาย การวางแผน ฯลฯ (ดูเจ้าครองเรือนเพื่อเจาะจงทักษะ)\",\"ตำแหน่งนี้สามารถให้ชื่อเสียงและตำแหน่งทางสังคม เพราะสัมพันธ์กับลัคนาโดยตรง\",\"มีปัญหาเกี่ยวกับการศึกษาระดับสูงหรือบุตร เช่น มีลูกยาก มีความขัดแย้งกับลูก หรือลูกมีปัญหา\",\"การเรียนอาจมีจุดเปลี่ยนหลายครั้ง ไม่ค่อยมั่นคง\"]"::jsonb),
("6in12",6,12,"เจ้าครองเรือนที่ 6 อยู่ในเรือนที่ 12","[\"อยู่ห่างจากเรือนตัวเอง 7 เรือน อาจดูดีเพราะเหมือนหลุดพ้นจากศัตรู แต่จริงๆ ต้องระวัง\",\"ถ้าเป็นดาวบาป ต้องระวังว่าจุดอ่อนจะขยายตัวอย่างไม่รู้ตัว\",\"จุดอ่อนเหล่านี้เช่น ความโกรธ (ถ้าเป็นอังคาร) หรือความใคร่ (ถ้าเป็นศุกร์) จะสร้างปัญหาใหญ่\",\"เรือนที่ 12 เป็นเรือนของโรงพยาบาล โรงเรียน คุก วัด ฯลฯ การทำงานด้านบริการในสถานที่เหล่านี้จะได้ผลดี\",\"การพัฒนาด้านจิตวิญญาณมีอุปสรรค คุณอาจแสวงหาหนทางแต่เจอความขัดแย้งภายใน\",\"มีแนวโน้มสนใจเรื่องเร้นลับ โหราศาสตร์ หรือศาสตร์ทางจิต\",\"มีแนวโน้มพักผ่อนน้อย ใช้ร่างกายหนัก ไม่ดูแลสุขภาพ อาจเกิดโรคเรื้อรังตามมา\",\"มักมีปัญหาเกี่ยวกับเพื่อน เช่น เพื่อนหายตัว เปลี่ยนใจ หรือเกิดเหตุการณ์ไม่คาดฝัน\",\"มีแนวโน้มเกิดอุบัติเหตุ หรือเหตุการณ์ไม่คาดคิดที่เปลี่ยนชีวิต\",\"โฟกัสของชีวิตมักอยู่ที่เรือนที่ 9: การศึกษา ปรัชญา ศาสนา การแสวงหาความจริง\",\"ใช้เวลาอยู่ลำพังเพื่อศึกษาหรือวิจัยสิ่งที่ลึกซึ้ง ให้ผลดี\",\"อาจเกิดความกลัว ความสงสัยในตนเอง แต่การเรียนรู้เชิงจิตวิญญาณจะช่วยบรรเทาได้\",\"เจ้าเรือนที่ 7\",\"เรือนที่ 7 คือ พันธะผูกพัน (Commitment) เป็นข้อตกลงทางสังคม ไม่ว่าจะเป็นการแต่งงาน การเป็นคู่กันโดยไม่จดทะเบียน หรือหุ้นส่วนธุรกิจ\",\"ความสัมพันธ์แบบ “อยู่ด้วยกันนานๆ แบบผูกพัน แม้ไม่ได้แต่ง” ก็ถือเป็นเรือนที่ 7 ได้ ถ้ามีความผูกพันชัดเจนและสังคมรับรู้ว่าเป็นคู่\",\"เรือนที่ 7 สอนให้คุณละอัตตา ไม่เอาตัวเองเป็นศูนย์กลาง คุณต้องสามารถ: เชื่อใจ ทำงานร่วมกัน เปิดใจ หากมี ความลับ การบงการ การโกง ความสัมพันธ์จะพังอย่างรวดเร็ว\"]"::jsonb),
("7in1",7,1,"เจ้าครองเรือนที่ 7 อยู่ในเรือนที่ 1","[\"จุดเน้นของชีวิตคู่จะมาสะท้อนที่ตัวคุณโดยตรง\",\"หากเจ้าครองเรือนที่ 7 เป็นดาวบาปเคราะห์ เช่น เสาร์ ราหู เกตุ หรืออังคาร จะทำให้มีแนวโน้มเห็นแก่ตัว หรือคิดถึงตัวเองมากกว่าคู่\",\"ความสัมพันธ์ ความรัก การแต่งงานมีความสำคัญมากสำหรับคุณ\",\"มักไม่อยากอยู่คนเดียว ต้องการใครสักคนอยู่ข้างกายตลอด\",\"คู่มักเข้ามาในชีวิตในช่วงเวลาที่คุณต้องการมากที่สุดเสมอ\",\"คุณมักจะแสดงออก หรือ เป็นฝ่ายลงมือหาคู่ด้วยตัวเอง เช่น สมัครแอปหาคู่ หรือติดต่อเชิงรุก\",\"เจ้าครองเรือนที่ 7 อยู่ในเรือนที่ 1 หมายถึงคุณมีความทะเยอทะยานในการ “หา” คู่ด้วยตัวเอง ไม่รอให้ชะตาชีวิตพาไป\",\"มีนิสัยแรงกล้าในเรื่องความปรารถนา ถ้าอยากได้ใครแล้วจะพยายามทำทุกวิถีทางให้ได้มา\",\"เป็นนักธุรกิจที่มีพรสวรรค์ แต่เหมาะกับการทำงานคนเดียวมากกว่าทำงานร่วมกับหุ้นส่วน\",\"ชีวิตคู่จะมั่นคงได้จากการ อยู่ร่วมกัน, การสร้างบ้าน หรือ มีรากฐานร่วมกัน\",\"ความสัมพันธ์ทางไกล หรือการเดินทางบ่อยไม่เหมาะกับคุณ\",\"ความปรารถนาลึกที่สุดของคุณก็คือการได้ “ใครสักคน” ที่พร้อมยืนเคียงข้าง — คุณต้องการให้ “เขามาหาคุณ”\",\"หากดาวเจ้าครองเรือนที่ 7 เป็นดาวศุภเคราะห์ เช่น ศุกร์ จันทร์ พฤหัส หรือพุธ อารมณ์เห็นแก่ตัวจะลดลง และมีแนวโน้มประนีประนอมมากขึ้น\",\"อย่างไรก็ตาม คุณยังคงมีแนวโน้ม “เล่นเกมทางใจ” หรือควบคุมอีกฝ่ายแบบแนบเนียนได้บ่อยครั้ง\",\"ความเสี่ยงต่อความสัมพันธ์มาจากเรือนที่ 8 คือเรื่อง ทรัพย์สินร่วม, ภาษี, มรดก, หรือ การซื้อบ้านร่วม\",\"พบได้บ่อยว่าเจ้าชะตาไปอาศัยอยู่ในบ้านของคู่ โดยไม่ได้เป็นเจ้าของร่วม\",\"ความสัมพันธ์จะมีปัญหา หากไม่มีการเปิดใจและแบ่งปันอย่างแท้จริง\",\"อีกความเสี่ยงคือปัญหาสุขภาพหรือวิกฤติชีวิตร่วมกัน อาจเป็นคุณหรือคู่ก็ได้ที่เจอโรคร้ายหรือเหตุการณ์เปลี่ยนชีวิตร่วมกัน\"]"::jsonb),
("7in2",7,2,"เจ้าครองเรือนที่ 7 อยู่ในเรือนที่ 2","[\"มีแนวโน้มมีความสัมพันธ์หลายครั้ง หรือเลือกนาน ตัดสินใจไม่ง่ายเรื่องคนที่จะแต่งงานด้วย\",\"ถ้าอยู่ในราศีที่ดีและไม่มีมุมร้าย ความสัมพันธ์จะนำพาซึ่งความมั่งคั่งทางการเงิน\",\"ชีวิตรักจะเต็มไปด้วยความสุขทางร่างกายและความรู้สึกหรูหรา เช่น ความสุขทางเพศ อาหาร ความสบาย\",\"พบคู่ผ่านกิจกรรมที่เกี่ยวกับอาหาร เช่น ร้านอาหาร ร้านกาแฟ หรือสถานที่ที่มีบรรยากาศนุ่มนวล\",\"คู่ของคุณอาจมาจาก วงศ์ตระกูลเดียวกัน หรือ บ้านใกล้เรือนเคียงสมัยเด็ก\",\"ความมั่นคงทางการเงินจากคู่หรือกับคู่เป็นสิ่งที่คุณให้ความสำคัญมาก\",\"ความต้องการลึกที่สุดคือเรือนที่ 8 ทำให้คุณมักเกี่ยวพันกับสถานการณ์วิกฤติ\",\"อาจทำงานในแวดวงแพทย์ พยาบาล จิตบำบัด นักโหราศาสตร์ หรือพบคู่ที่มีอาชีพเหล่านี้\",\"สิ่งที่ช่วยปกป้องความสัมพันธ์คือเรือนที่ 5 (นับ 4 จากเรือนที่ 2)\",\"คือการสร้างสรรค์ร่วมกัน, งานอดิเรกร่วมกัน, การเรียนรู้ด้วยกัน, หรือการมีบุตร\",\"สิ่งที่คุกคามความสัมพันธ์คือเรือนที่ 9: การเรียนต่อในที่ไกล, การเดินทางไกล, หรือบุคคลที่เป็น ครู/ที่ปรึกษา/พ่อ\",\"การเรียนไกลหรือการแยกกันอยู่ระหว่างเรียนอาจทำให้ความสัมพันธ์สั่นคลอน\",\"ความขัดแย้งกับพ่อของฝ่ายใดฝ่ายหนึ่งก็เป็นตัวแปรที่สำคัญ\",\"หากทั้งสองคน สร้างทรัพย์สินร่วมกัน และมีความก้าวหน้าในทางวัตถุไปพร้อมกัน ความสัมพันธ์จะมั่นคง\",\"เป็นตำแหน่งที่ดีเยี่ยมสำหรับ การทำธุรกิจร่วมกับคู่ หรือความสัมพันธ์ที่มีรากฐานทางการเงินร่วมกัน\"]"::jsonb),
("7in3",7,3,"เจ้าครองเรือนที่ 7 อยู่ในเรือนที่ 3","[\"เรือนที่ 3 มีธรรมชาติของดาวอังคาร เป็นเรือนที่มีการแข่งขัน ท้าทาย และความตึงเครียด ซึ่งไม่ใช่สิ่งที่เหมาะกับความสัมพันธ์ใกล้ชิดเท่าไร\",\"ความสัมพันธ์กับลูก โดยเฉพาะลูกชาย อาจมีปัญหา ควรตรวจสอบดาวเจ้าเรือนที่ 5 และ 9 ร่วมด้วย\",\"อย่างไรก็ตาม นี่คือเรือนที่ 9 จากเรือนที่ 7 จึงมีสายสัมพันธ์ทางกรรมและจิตวิญญาณที่ลึกซึ้งระหว่างคุณกับคู่\",\"คุณอาจพบคู่ขณะเดินทาง หรือในสถานการณ์เกี่ยวกับการศึกษา เช่น เรียนหนังสือ เรียนธรรมะ อยู่กับครูหรือผู้ให้คำปรึกษา\",\"ความสำคัญคือ คุณและคู่ควรมีปรัชญาชีวิต ศีลธรรม และระบบความเชื่อที่ตรงกัน เพราะนั่นคือสิ่งที่จะเชื่อมคุณทั้งคู่ไว้\",\"หากมีความแตกต่างด้านศีลธรรมและความเชื่อ อาจเกิดความขัดแย้งได้ง่าย\",\"สิ่งที่คุ้มครองความสัมพันธ์ คือเรือนที่ 6 (4 เรือนจากเรือนที่ 3)\",\"ผู้ช่วยเหลือในบ้านหรืองาน พนักงาน ลูกน้อง จะช่วยให้ความสัมพันธ์มั่นคง\",\"การเลี้ยงสัตว์ร่วมกัน และกิจกรรมเกี่ยวกับสุขภาพ เช่น ออกกำลังกาย ไปฟิตเนสด้วยกัน มีผลดีต่อความสัมพันธ์\",\"คุณอาจพบคู่ผ่านญาติพี่น้อง หรือขณะเดินทาง หรือแม้แต่ในต่างประเทศ\",\"ความปรารถนาในระดับลึกคือความเข้าใจในธรรมะ ปรัชญาชีวิต ความรู้ขั้นสูง\",\"สิ่งที่คุกคามความสัมพันธ์ คือเรือนที่ 10 (8 จากเรือนที่ 3) หมายถึงเรื่องงานและอาชีพ\",\"อย่านำเรื่องคู่รักไปเกี่ยวข้องกับที่ทำงาน อาจส่งผลเสีย\",\"ระวังการพูดถึงคู่ต่อหน้าคนในที่ทำงาน หรือเปิดเผยชีวิตคู่มากเกินไป\"]"::jsonb),
("7in4",7,4,"เจ้าครองเรือนที่ 7 อยู่ในเรือนที่ 4","[\"คู่ครองมาอยู่ในบ้านของคุณ บ่งบอกว่าคุณสามารถควบคุมหรือมีอิทธิพลต่อคู่ได้ในระดับหนึ่ง\",\"คู่ครองมักแสวงหาความมั่นคง และมองว่าคุณเป็นผู้นำ มีอำนาจ (เพราะเรือนที่ 4 คือ 10 เรือนจากเรือนที่ 7)\",\"คุณเป็นคนมีระเบียบ ฉลาด และใช้ความสามารถในบ้านหรืองานได้ดีมาก\",\"ความปรารถนาลึกสุดคือความสำเร็จในหน้าที่ ชื่อเสียง และสถานะ (เรือนที่ 10 จากเรือนที่ 4)\",\"มักพบคู่ขณะทำงาน หรือที่ทำงานของคุณ อาจจะในบ้าน สำนักงาน หรือสถานที่ประกอบอาชีพ\",\"สิ่งที่รักษาความสัมพันธ์ไว้คือเรือนที่ 7 (4 จากเรือนที่ 4)\",\"การทำธุรกิจร่วมกัน หรือการอยู่ร่วมในสังคม การเจรจา ความไว้ใจจะช่วยให้ความสัมพันธ์มั่นคง\",\"หากไม่มีความเชื่อใจและการแบ่งปันจริงจัง ความสัมพันธ์จะไม่ยืนนาน\",\"สิ่งที่คุกคามความสัมพันธ์คือเพื่อน กลุ่มสังคม และเครือข่ายต่างๆ (เรือนที่ 11 ซึ่งเป็น 8 จากเรือนที่ 4)\",\"เพื่อนของฝ่ายใดฝ่ายหนึ่งอาจทำให้เกิดปัญหา\",\"อีกประเด็นที่สำคัญ: สุขภาพ การดูแลร่างกายร่วมกัน มีผลต่อความสัมพันธ์ หากมีดาวบาปในเรือนที่ 6 หรือ 4 อาจทำให้คุณกดดันคู่เรื่องสุขภาพมากเกินไป\"]"::jsonb),
("7in5",7,5,"เจ้าเรือนที่ 7 อยู่ในเรือนที่ 5","[\"คู่ครองเป็นคนโรแมนติก มีความรักแบบสร้างสรรค์ และทำให้คุณรู้สึกสนุกสนานกับชีวิต\",\"มักได้คู่ที่มีความสามารถทางศิลปะ การแสดง ความคิดสร้างสรรค์ หรือมีเสน่ห์แบบเด็ก ๆ\",\"มีแนวโน้มจะพบรักจากงานอดิเรก สถานบันเทิง หรืองานที่เกี่ยวข้องกับเด็ก ๆ\",\"มักแต่งงานกับคนที่มีความคิดอิสระ หัวใจเป็นเด็ก หรือเป็นคนที่คุณเคยคบหามาตั้งแต่ยังวัยรุ่น\",\"มีโอกาสได้คู่ที่อายุน้อยกว่า หรือมีพลังชีวิตมาก\",\"จุดแข็งของความสัมพันธ์คือ การมีบุตรร่วมกัน ความสุขจากการใช้เวลาร่วมกันอย่างสร้างสรรค์\",\"ความสัมพันธ์จะมั่นคงหากคุณแบ่งปันความฝัน ความคิดสร้างสรรค์ และสนับสนุนกันในการเลี้ยงดูลูก\",\"ความเสี่ยงในความสัมพันธ์มาจากความไม่จริงจัง หรือการเล่นสนุกเกินไป ไม่ลงมือสร้างอนาคตร่วมกันอย่างจริงจัง\",\"อาจมีภาวะที่หนึ่งในคู่รักต้องทำหน้าที่เป็นพ่อแม่ให้กับอีกฝ่าย ทั้งในทางอารมณ์หรือจิตใจ\"]"::jsonb),
("7in6",7,6,"เจ้าเรือนที่ 7 อยู่ในเรือนที่ 6","[\"เป็นตำแหน่งที่มีความท้าทายสูง มักได้คู่ครองที่มาจากเบื้องหลังของความขัดแย้งหรือการต่อสู้บางอย่าง\",\"คู่รักอาจมีหนี้กรรมร่วมกัน ทำให้ต้องเผชิญบททดสอบร่วมกัน เช่น ปัญหาสุขภาพ ความขัดแย้ง หรือความเสียสละ\",\"บางรายได้คู่จากที่ทำงาน โรงพยาบาล หรือสถานที่ที่เกี่ยวข้องกับการดูแล/ช่วยเหลือผู้อื่น\",\"คู่รักอาจมีความแตกต่างด้านนิสัย หรือมีแนวโน้มทะเลาะกันง่าย\",\"มีบทบาทในการเรียนรู้การให้อภัย การบริการ และการรักษาความอดทนในความสัมพันธ์\",\"จุดแข็งของความสัมพันธ์คือการร่วมกันผ่านความยากลำบาก และใช้ชีวิตในรูปแบบการช่วยเหลือกัน\",\"ความสัมพันธ์จะมั่นคงขึ้นเมื่อมีภารกิจร่วมกัน หรือทำธุรกิจ/งานบริการร่วมกัน\",\"ความเสี่ยงของความสัมพันธ์มาจากบุคคลที่สามในที่ทำงาน คู่แข่ง หรือคนที่มีศัตรูเก่าเกี่ยวข้อง\",\"ต้องระวังโรคภัยที่เกิดกับคู่ครอง ซึ่งอาจทำให้เกิดภาระในระยะยาว\"]"::jsonb),
("7in7",7,7,"เจ้าเรือนที่ 7 อยู่ในเรือนที่ 7","[\"เป็นตำแหน่งที่ดีมากโดยธรรมชาติ โดยเฉพาะถ้าเป็นดาวคุณ เช่น ศุกร์ พฤหัส จันทร์ พุธ\",\"แม้เป็นดาวบาป เช่น เสาร์ อังคาร ราหู เกตุ ก็ยังถือว่ามีพลัง แต่ต้องยอมรับบทเรียนจากคู่\",\"มักได้คู่ครองที่มีตำแหน่งหรือมีภารกิจสำคัญในโลก คู่ครองมักแบ่งปันพรสวรรค์หรือโชคดีให้เจ้าชะตา\",\"ต้องให้พื้นที่และอิสระแก่คู่ครอง อย่าจับผิดหรือหึงหวง เพราะการไว้ใจกันจะทำให้ความสัมพันธ์ราบรื่น\",\"คู่ครองมักเป็นแรงบันดาลใจสำคัญที่ช่วยผลักดันให้เจ้าชะตาประสบความสำเร็จ\",\"ความสำเร็จของทั้งสองคนเป็นสิ่งที่หล่อเลี้ยงความรัก ทั้งคู่สามารถทำธุรกิจร่วมกันได้ดี\",\"มักพบคู่ครองในแวดวงธุรกิจ ตลาด สถานที่ที่มีการแลกเปลี่ยน ซื้อขาย หรือในโลกของการงาน\",\"สิ่งที่หล่อเลี้ยงความสัมพันธ์คือเรือนที่ 10: การประสบความสำเร็จในชีวิต มีชื่อเสียงร่วมกัน\",\"ความเสี่ยงมาจากเรือนที่ 2: ต้องระวังคำพูด การสื่อสารที่บาดใจ หรือปัญหาเรื่องการเงิน\",\"ต้องมีความโปร่งใสเรื่องการเงิน อย่าแยกบัญชีหรือปิดบัง เพราะจะทำลายความเชื่อใจ\"]"::jsonb),
("7in8",7,8,"เจ้าเรือนที่ 7 อยู่ในเรือนที่ 8","[\"เป็นตำแหน่งท้าทาย เพราะเรือนที่ 8 คือเรือนแห่งวิกฤต การสูญเสีย และการเปลี่ยนแปลง\",\"ความสัมพันธ์จะเปลี่ยนแปลงเจ้าชะตาอย่างลึกซึ้ง เหมือนชีวิตใหม่หลังการแต่งงาน\",\"มักพบคู่ครองในช่วงวิกฤตชีวิต เช่น สุขภาพ การสูญเสีย หรือทำงานช่วยเหลือคนในภาวะวิกฤต เช่น หมอ นักจิตบำบัด\",\"อาจดึงดูดคู่ที่มีบาดแผลทางจิตใจ หรือเจ้าชะตาเองมีปัญหาเรื่องความไว้ใจและความใกล้ชิด\",\"ชีวิตรักอาจวุ่นวาย มีความสัมพันธ์ระยะสั้น หรือความสัมพันธ์ที่ไม่ยั่งยืน\",\"สิ่งที่หล่อเลี้ยงความสัมพันธ์คือเรือนที่ 11: เครือข่ายเพื่อน การมีกลุ่มสังคมร่วมกัน ช่วยผ่อนคลายความตึงเครียด\",\"พี่น้องคนโตของทั้งคู่สามารถมีบทบาทช่วยเหลือความสัมพันธ์ได้\",\"ความปรารถนาสูงสุดอยู่ที่เรือนที่ 2: ความมั่นคงทางการเงินและครอบครัว\",\"ความเสี่ยงอยู่ที่เรือนที่ 3: การสื่อสารที่ผิดพลาด ความเข้าใจคลาดเคลื่อน การไม่กล้าพูดความจริง\",\"คู่หรือเจ้าชะตาอาจมีโรคประจำตัว หรือปัญหาสุขภาพที่สร้างภาระในความสัมพันธ์\",\"ธุรกิจร่วมกับผู้อื่นไม่เหมาะ ควรทำธุรกิจคนเดียวหรือลงทุนในตลาดหุ้นจะดีกว่า\"]"::jsonb),
("7in9",7,9,"เจ้าเรือนที่ 7 อยู่ในเรือนที่ 9","[\"เป็นตำแหน่งที่ดีมาก เพราะอยู่ในเรือนธรรมะ คู่ครองนำพรและความโชคดีมาให้\",\"เจ้าชะตาเปิดกว้าง มองโลกในแง่ดี มีความสัมพันธ์หลายครั้งและดึงดูดผู้คนได้มาก\",\"มักพบคู่ขณะเดินทาง อยู่ต่างประเทศ หรือในสถานศึกษา สถานที่ศาสนา\",\"สิ่งที่เจ้าชะตาปรารถนาสูงสุดคือเรือนที่ 3: ความเป็นอิสระ ความกล้าหาญ การเป็นผู้ประกอบการ\",\"ดีต่อการทำธุรกิจส่วนตัว คู่ครองภูมิใจในความสำเร็จของเจ้าชะตามาก\",\"สิ่งที่หล่อเลี้ยงความรักคือเรือนที่ 12: ความใกล้ชิด การนอนร่วมกัน ความสัมพันธ์ทางเพศ และจิตวิญญาณ\",\"การเดินทางแสวงบุญ การเข้าวัดหรืออาศรมด้วยกันช่วยหล่อเลี้ยงความสัมพันธ์\",\"ความเสี่ยงมาจากเรือนที่ 4: ความขัดแย้งกับแม่ของฝ่ายใดฝ่ายหนึ่ง หรือปัญหาเรื่องทรัพย์สิน บ้าน รถ\",\"เพื่อนวัยเด็กหรือคนรู้จักเก่าอาจกลายเป็นภัยต่อความสัมพันธ์\"]"::jsonb),
("7in10",7,10,"เจ้าเรือนที่ 7 อยู่ในเรือนที่ 10","[\"เป็นตำแหน่งที่ต้องใช้ความพยายามมาก ต้อง \\\"ทำงาน\\\" กับความสัมพันธ์จริง ๆ\",\"คู่ครองมักมีความทะเยอทะยาน ต้องการสถานะ และร่วมกันผลักดันเป้าหมายในชีวิต\",\"อาจพบกันในที่ทำงาน หรือทำอาชีพคล้ายกัน บางครั้งเป็นหุ้นส่วนธุรกิจกัน\",\"ต้องระวังอย่าแทรกแซงเส้นทางอาชีพของกันและกันมากเกินไป\",\"สิ่งที่หล่อเลี้ยงความสัมพันธ์คือเรือนที่ 1: ตัวเจ้าชะตาเองต้องทุ่มเท ดูแลความสัมพันธ์เป็นหลัก\",\"ความปรารถนาสูงสุดอยู่ที่เรือนที่ 4: บ้านที่สวยงาม รถหรู ความสะดวกสบายในชีวิต\",\"อาจมีปัญหาเกี่ยวกับลูก หรือไม่เห็นตรงกันเรื่องการเลี้ยงดูลูก\",\"ความเสี่ยงมาจากเรือนที่ 5: ความสัมพันธ์นอกสมรสทั้งจากเจ้าชะตาหรือคู่ครอง หรือปัญหาเกี่ยวกับลูกที่ไม่เชื่อฟัง\"]"::jsonb),
("7in11",7,11,"เจ้าเรือนที่ 7 อยู่ในเรือนที่ 11","[\"ดีมากต่อเรื่องผลประโยชน์ทางวัตถุจากการแต่งงาน การเงิน ความมั่งคั่ง\",\"ต้องมีทัศนคติทางสังคม การเมือง หรือจริยธรรมที่คล้ายกัน จึงจะรักษาความสัมพันธ์ได้\",\"คู่ครองอาจมาจากกลุ่มเพื่อน วงสังคม หรือแนะนำโดยพี่น้อง\",\"ความปรารถนาสูงสุดอยู่ที่เรือนที่ 5: ต้องการมีลูก มีครอบครัว มีชีวิตที่สร้างสรรค์ร่วมกัน\",\"ลูกจะประสบความสำเร็จแต่ไม่เชื่อฟังเท่าไร ต้องปรับตัวในการเลี้ยงดู\",\"สิ่งที่หล่อเลี้ยงความสัมพันธ์คือเรือนที่ 2: การพูดคุย การรับประทานอาหารด้วยกัน การใช้เวลาครอบครัวร่วมกัน\",\"ความเสี่ยงมาจากเรือนที่ 6: ลูกน้อง คนรับใช้ หรือศัตรูในที่ทำงานอาจสร้างปัญหาต่อความสัมพันธ์\",\"ธุรกิจมีโอกาสดีมาก มักมีโอกาสใหม่ ๆ เปิดเข้ามาเสมอ\"]"::jsonb),
("7in12",7,12,"เจ้าเรือนที่ 7 อยู่ในเรือนที่ 12","[\"เป็นตำแหน่งที่มีกรรมเก่าท้าทายเหมือนอยู่เรือนที่ 6 และ 8\",\"มักพบคู่ที่ต่างประเทศ หรือบนโลกออนไลน์ คู่มีพื้นเพต่างวัฒนธรรม หรืออยู่ไกล\",\"ความสัมพันธ์มักมีช่องว่าง เช่น คู่เดินทางบ่อย ทำงานต่างถิ่น ห่างกันบ่อย\",\"เรื่องการเงินเป็นปัจจัยหลักที่ต้องเปิดเผย หลีกเลี่ยงความลับและการปกปิด\",\"ในระยะแรกมักให้มาก แต่ต่อมาอาจเริ่มรู้สึกอยากเก็บหรือรู้สึกกลัวการเสียเปรียบ\",\"คู่ครองมักใช้เงินมาก ทำให้เจ้าชะตารู้สึกไม่มั่นใจ\",\"มีความเสี่ยงสูงด้านการเงิน เช่น ใช้เงินมากเพื่อจะได้อยู่กับคู่ หรือต้องเดินทาง\",\"คู่ครองอาจเจ็บป่วยหรือมีปัญหาสุขภาพ\",\"สิ่งที่หล่อเลี้ยงความสัมพันธ์คือเรือนที่ 3: ทำกิจกรรมร่วมกัน เช่น เดิน วิ่ง เที่ยว เล่นกีฬา\",\"ต้องระวังการพึ่งพาความสัมพันธ์ทางเพศมากเกินไป ทำให้ความสัมพันธ์ตื้นเขิน\",\"ความเสี่ยงมาจากเรือนที่ 7 เอง: คู่ถืออำนาจในการเลิกหรืออยู่ในความสัมพันธ์ เจ้าชะตาอาจรู้สึกไม่มั่นคง\",\"ไม่เหมาะกับการมีธุรกิจร่วมกับผู้อื่น แต่เหมาะกับการทำธุรกิจเกี่ยวกับต่างประเทศ อินเทอร์เน็ต แฟชั่น หรือช่วยเหลือผู้อื่น\",\"เจ้าเรือนที่ 8\"]"::jsonb),
("8in1",8,1,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 1","[\"เจ้าชะตามีลักษณะลึกลับ มีความลึกซึ้งและมีความสามารถในการฟื้นตัวจากวิกฤตต่างๆ ได้ดี\",\"มีแนวโน้มจะมีสุขภาพไม่มั่นคงในวัยเด็ก หรือเจ็บป่วยเป็นๆ หายๆ\",\"เป็นคนที่ต้องเจอกับประสบการณ์ที่เปลี่ยนแปลงชีวิตอย่างรุนแรง เช่น อุบัติเหตุ การเปลี่ยนรูปลักษณ์หรือบุคลิก\",\"อาจมีรอยแผลเป็นจริง หรือแผลเป็นทางจิตใจที่ส่งผลต่อบุคลิกภาพ\",\"ชีวิตมีการเปลี่ยนแปลงด้านอัตลักษณ์หรือรูปลักษณ์ภายนอกอย่างมาก\",\"ชีวิตต้องเผชิญกับความสูญเสียที่ทำให้เติบโตอย่างรวดเร็ว\",\"หากดาวเจ้าเรือนที่ 8 เป็นบาปเคราะห์ เช่น เสาร์ อังคาร ราหู เกตุ อาจเจอความเจ็บปวดทั้งทางกายและใจบ่อยครั้ง\",\"มักสนใจศาสตร์เร้นลับ จิตวิทยา หรือเรื่องเหนือธรรมชาติ\",\"เหมาะกับงานที่ต้องรักษาความลับ หรือเกี่ยวข้องกับการวิจัย\"]"::jsonb),
("8in2",8,2,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 2","[\"การเงินมีความไม่แน่นอนหรือผันผวน มีช่วงล้มละลายหรือสูญเสียเงินอย่างรุนแรงได้\",\"อาจได้รับมรดกจากญาติพี่น้อง หรือมีประสบการณ์เกี่ยวกับหนี้สินของครอบครัว\",\"ปัญหาเกี่ยวกับอาหาร สุขภาพช่องปาก หรือการพูดอาจเกิดขึ้นในชีวิต\",\"มีแนวโน้มจะพูดสิ่งที่สร้างความเจ็บปวดหรือสะเทือนใจให้กับผู้อื่น\",\"ปากเป็นพิษ หรือมีความลับเกี่ยวกับการเงินที่ไม่เปิดเผย\",\"อาจมีความรู้สึกไม่มั่นคงเรื่องคุณค่าในตนเอง และต้องพัฒนาอย่างมากในด้านนี้\",\"การพูดของเจ้าชะตาสามารถเปลี่ยนทิศทางชีวิตของผู้อื่นได้ถ้าใช้ให้ถูกทาง\",\"เหมาะกับงานด้านการเงิน การเงินลับ หรือการให้คำปรึกษาด้านทรัพย์สิน\"]"::jsonb),
("8in3",8,3,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 3","[\"พี่น้องหรือเพื่อนสนิทอาจเป็นผู้ที่นำการเปลี่ยนแปลงใหญ่หลวงมาสู่ชีวิต\",\"อาจมีปัญหาหรือความไม่เข้าใจกับพี่น้อง โดยเฉพาะในวัยเด็ก\",\"ทักษะการสื่อสารมีพลังสูง สามารถใช้คำพูดในการชักจูงหรือเปลี่ยนแปลงจิตใจผู้อื่นได้\",\"ความกลัวและความวิตกกังวลอาจแสดงออกผ่านการสื่อสาร\",\"มีศักยภาพในการเขียนเรื่องลึกลับ หนังสือเกี่ยวกับการเปลี่ยนแปลง หรือการให้แรงบันดาลใจ\",\"เดินทางใกล้อาจไม่ราบรื่น หรือมีอุบัติเหตุเกิดขึ้นจากการเดินทางระยะสั้น\",\"ชีวิตมีการเปลี่ยนทิศทางอย่างรวดเร็วจากการตัดสินใจแบบทันทีทันใด\",\"เหมาะกับการทำงานที่ต้องใช้การเจรจา ต่อรอง หรือเขียนเรื่องราวเฉพาะกลุ่ม\"]"::jsonb),
("8in4",8,4,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 4","[\"ชีวิตในวัยเด็กมักมีความไม่สงบ หรือมีความลับในครอบครัว\",\"อาจมีการสูญเสียแม่ หรือมีความรู้สึกขาดความอบอุ่นจากครอบครัว\",\"บ้านคือจุดเปลี่ยนของชีวิต เจ้าชะตาอาจย้ายบ้านบ่อย หรือมีการเปลี่ยนแปลงที่อยู่อาศัยอย่างรุนแรง\",\"ความผูกพันกับแผ่นดินหรือบ้านเกิดมีความซับซ้อนหรือเจ็บปวด\",\"เหมาะกับงานที่ทำจากบ้าน งานที่เกี่ยวข้องกับพลังงานของจิตวิญญาณ หรือบ้านพักคนชรา\",\"มักสนใจรากเหง้า ประวัติศาสตร์ และความรู้ลึกเกี่ยวกับบรรพบุรุษ\",\"ต้องเรียนรู้การสร้าง “บ้าน” ภายในใจ มากกว่าบ้านภายนอก\"]"::jsonb),
("8in5",8,5,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 5","[\"ลูกหลานอาจนำการเปลี่ยนแปลงครั้งใหญ่ในชีวิต หรือมีปัญหาสุขภาพ\",\"ความรักมักเต็มไปด้วยความลึกลับ ดราม่า หรือความสัมพันธ์ที่ซับซ้อน\",\"มีพรสวรรค์ในการแสดง ออกแบบ หรือสร้างผลงานจากความรู้สึกส่วนลึก\",\"เส้นทางการศึกษามักมีการเปลี่ยนแปลงหลายครั้ง มีช่วงพักหรือเปลี่ยนสาขา\",\"เป็นผู้ที่มีเซนส์แรง หรือมีความสามารถทางจิตวิญญาณ\",\"เหมาะกับงานที่ใช้ญาณทิพย์ การให้คำปรึกษา โหราศาสตร์ หรือพลังงานบำบัด\"]"::jsonb),
("8in6",8,6,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 6","[\"เป็นหนึ่งในตำแหน่ง “วิปรีตรีชโยค” ทำให้สามารถเอาชนะศัตรู โรคภัย และอุปสรรคต่างๆ ได้\",\"สุขภาพอาจอ่อนแอในวัยเด็ก แต่ฟื้นตัวได้แข็งแรงในช่วงกลางชีวิต\",\"อาจมีศัตรูหรือคนที่ขัดแย้งในที่ทำงาน แต่สามารถเอาชนะได้ด้วยความสามารถ\",\"เหมาะกับงานทางการแพทย์ กฎหมาย กีฬา หรือการแก้ปัญหาเฉพาะหน้า\",\"มีกรรมเก่ากับสัตว์เลี้ยงหรือสิ่งมีชีวิตขนาดเล็ก เช่นเคยเป็นหนี้บุญคุณสัตว์\",\"มีความสามารถในการทำงานหนักและต่อสู้จนประสบความสำเร็จ\",\"ต่างแดนอาจเป็นจุดเปลี่ยนชีวิต มีโอกาสตั้งรกรากหรือติดต่อกับวัฒนธรรมต่างชาติ\",\"ควรหลีกเลี่ยงการใช้อำนาจเพื่อเอาชนะผู้อื่นอย่างไม่ถูกต้อง เพราะจะย้อนกลับมาสร้างกรรมให้ตนเอง\"]"::jsonb),
("8in7",8,7,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 7","[\"ความสัมพันธ์แต่งงานมักมีปัญหา มีความซับซ้อนหรือเกิดการเปลี่ยนแปลงครั้งใหญ่\",\"อาจแต่งงานมากกว่าหนึ่งครั้ง หรือมีความสัมพันธ์ที่ไม่เปิดเผย\",\"มักดึงดูดคนที่มีปมลึก ความลับ หรือมีอดีตลึกลับเข้ามาในชีวิต\",\"ความเชื่อใจในคู่ครองเป็นสิ่งที่ยาก มีแนวโน้มไม่ไว้วางใจซึ่งกันและกัน\",\"เป็นความสัมพันธ์ที่มีรากฐานมาจากกรรมในอดีตชาติ ต้องกลับมาเรียนรู้เพื่อปิดจบในชาตินี้\",\"มีแนวโน้มเกิดปัญหาในธุรกิจโดยเฉพาะถ้าทำธุรกิจร่วมกับผู้อื่น อาจเจอการล้มละลายหรือขาดทุนรุนแรง\",\"ส่งผลต่อสุขภาพร่างกายและจิตใจอย่างลึกซึ้ง โดยเฉพาะเมื่อมีปัญหาความสัมพันธ์\",\"ควรหลีกเลี่ยงการเสพติดสิ่งที่ทำลายสุขภาพ เช่น แอลกอฮอล์ ยา หรืออาหาร\",\"ความช่วยเหลือจะมาจากเรือนที่ 10 คือด้านอาชีพและหัวหน้างาน ผู้ใหญ่ในหน้าที่การงานให้การสนับสนุน\"]"::jsonb),
("8in8",8,8,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 8","[\"อยู่ในตำแหน่งเรือนของตนเอง จึงให้พลังภายในสูง มีความแข็งแกร่ง ลึกลับ และเข้าใจด้านจิตวิญญาณลึกซึ้ง\",\"มีความยืนหยุ่นในการฟื้นตัวจากวิกฤต มีพลังในการเอาชนะอุปสรรคชีวิต\",\"มีบุคลิกที่แยกตัว ไม่ยึดติดกับผู้อื่น ต้องการอิสระในการใช้ชีวิต\",\"มีความสนใจในเรื่องลี้ลับ โหราศาสตร์ พลังงานบำบัด หรือศาสตร์ลึกซึ้ง\",\"มีแนวโน้มจะมีปัญหากับขา โดยเฉพาะต้นขา อาจเจ็บป่วยหรือบาดเจ็บได้\",\"ประสบการณ์ในวัยเด็กส่งผลทางจิตใจ รู้สึกแบกรับภาระ หรือถูกตำหนิอย่างไม่เป็นธรรม\",\"มิตรภาพและเพื่อนสนิทเป็นแหล่งพลังใจที่สำคัญ สามารถช่วยเยียวยาได้\",\"ควรระวังปัญหาจากลูกน้องหรือคนรับใช้ มีแนวโน้มจะเกิดความขัดแย้งหรือไม่ซื่อสัตย์\"]"::jsonb),
("8in9",8,9,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 9","[\"มักมีกรรมร่วมกับพ่อ หรือบุคคลในบทบาทผู้สอน เช่น ครู อาจารย์ ผู้ใหญ่\",\"ความสัมพันธ์กับพ่ออาจห่างเหิน ขาดความเข้าใจ หรือเจอการสูญเสียพ่อ\",\"มีประสบการณ์ที่เปลี่ยนแปลงความเชื่อทางศาสนาอย่างรุนแรง อาจกลายเป็นผู้ไม่เชื่อศาสนา\",\"บ้านหรือที่อยู่ในวัยเด็กมีความวุ่นวายหรือความขัดแย้งกับแม่\",\"มีแนวโน้มย้ายบ้านบ่อย หรือหาที่พักอาศัยถาวรไม่ได้ง่าย\",\"อาจไม่อยากซื้อรถหรือบ้าน แต่เลือกใช้บริการหรือเช่ามากกว่า\",\"ต่างประเทศเป็นจุดเปลี่ยนชีวิต อาจต้องเผชิญกับความยากลำบากก่อนที่จะประสบความสำเร็จ\",\"ควรระวังความขัดแย้งกับพี่น้อง โดยเฉพาะน้องคนเล็ก\"]"::jsonb),
("8in10",8,10,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 10","[\"อาชีพการงานคือหัวใจของชีวิต มีผลต่อจิตใจและชะตาชีวิตอย่างลึกซึ้ง\",\"มีแนวโน้มเปลี่ยนอาชีพหลายครั้ง หรือเผชิญเหตุการณ์รุนแรง เช่น การตกงาน เสื่อมชื่อเสียง หรือคดีความ\",\"ความสัมพันธ์กับพ่อหรือผู้มีอำนาจในที่ทำงานอาจมีปัญหา ขาดความเข้าใจ หรือการสื่อสาร\",\"การสนับสนุนที่แท้จริงจะมาจากเรือนที่ 1 คือ ตัวคุณเอง ต้องเรียนรู้การพึ่งพาตนเอง\",\"อาจไม่มีลูก หรือมีความขัดแย้งกับลูก ควรใช้ความเข้าใจและไม่คาดหวังมากเกินไป\",\"หากเจอบาปเคราะห์อยู่ใกล้ดาวเจ้าเรือนที่ 8 จะมีปัญหาด้านอาชีพและชีวิตโดยรวม\",\"หากมีดาวดีให้คุณหรือมีแสงสว่างในจิตใจ จะสามารถเอาชนะและเปลี่ยนแปลงโชคชะตาได้\"]"::jsonb),
("8in11",8,11,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 11","[\"ให้พลังในการฟื้นตัวจากวิกฤตทางการเงิน ช่วยเพิ่มอายุยืนและความแข็งแรง\",\"มีปัญหาในวัยเด็ก โดยเฉพาะด้านมิตรภาพ ความสัมพันธ์ในโรงเรียน หรือความเหงา\",\"รายได้อาจไม่มั่นคง ต้องเจอการสูญเสียเงินหรืองานที่ไม่แน่นอน\",\"การศึกษาอาจมีอุปสรรค ต้องกลับมาเรียนใหม่ในช่วงกลางชีวิต\",\"มิตรภาพมีความเป็นเวรกรรม อาจเคยรู้จักกันในอดีตชาติ\",\"ความสัมพันธ์กับลูกมักมีปัญหา เพราะความคาดหวังสูงเกินไป\",\"มีปัญหากับคู่ครองหากไม่ตรวจสอบความเข้ากันได้ก่อนแต่งงาน\",\"ควรพูดความจริงและยึดหลักศีลธรรมเป็นแนวทาง เพราะเรือนที่ 2 ให้การสนับสนุนด้านคุณค่า\"]"::jsonb),
("8in12",8,12,"ดาวเจ้าเรือนที่ 8 สถิตเรือนที่ 12","[\"เป็นวิปรีตรีชโยคประเภทพิเศษ ให้พลังการฟื้นฟูทางจิตวิญญาณและเส้นทางสู่โมกษะ\",\"มีแนวโน้มเสพติดสิ่งต่างๆ ได้ง่าย เช่น แอลกอฮอล์ ยาเสพติด อาหาร หรือเซ็กซ์\",\"ควรระวังการใช้จ่ายเกินตัว เพราะอาจทำให้การเงินพัง\",\"เหมาะกับงานทางจิตวิญญาณ เช่น โหราศาสตร์ การบำบัด พลังงาน หรือโยคะ\",\"การเดินทางไกลอาจนำมาซึ่งการเปลี่ยนแปลง แต่ไม่ราบรื่น อาจมีปัญหาหรืออุปสรรค\",\"สุขภาพเปราะบาง ต้องควบคุมอาหารและสุขอนามัยให้ดี\",\"ความสัมพันธ์กับคู่ครองมักมีปัญหาความเข้าใจ อาจรู้สึกโดดเดี่ยว\",\"ควรพึ่งพาพี่น้องให้เป็นที่พักใจ เพราะให้การสนับสนุนได้ดี\",\"เจ้าเรือนที่ 9\"]"::jsonb),
("9in1",9,1,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 1","[\"เป็นตำแหน่งที่นำโชคดีอย่างมาก ถือว่าได้รับ “ความโปรดปรานจากพระราชา” ซึ่งในปัจจุบันหมายถึง ผู้มีอำนาจ เจ้านาย หรือรัฐบาลเมตตาสนับสนุน\",\"ผู้คนเห็นคุณค่าบางอย่างในตัวคุณและช่วยดันคุณให้ก้าวหน้า\",\"เรือนที่ 1 แทนชื่อเสียงและภาพลักษณ์ ดาวเจ้าเรือนที่ 9 อยู่ที่นี่จึงส่งเสริมชื่อเสียง ทั้งระดับท้องถิ่นหรือระดับโลก\",\"คุณได้สะสมบุญดีไว้ในอดีตชาติ จึงได้รับผลบุญในชาตินี้\",\"ส่งผลให้ได้รับการศึกษา การเรียนรู้ และความรู้ทางจิตวิญญาณสูง\",\"รูปร่างหน้าตาน่าดึงดูดเพราะเรือนที่ 1 คือร่างกาย\",\"เรือนที่ 1, 5, 9 คือเรือนแห่งโชคลาภ (Lakshmi Sthana) ดังนั้นตำแหน่งนี้จึงนำความมั่งคั่งและโอกาสเข้ามา\",\"อาจมีการติดต่อกับคนต่างชาติ หรือทำธุรกิจต่างประเทศ\",\"ถ้าดวงจันทร์เชื่อมโยงกับเจ้าเรือนที่ 9 โชคดีจะเพิ่มมากขึ้น (เช่น เป็นเจ้าเรือน หรือร่วมเรือนกัน)\",\"ลักษณะของดาวเจ้าเรือนจะกำหนดรูปแบบ เช่น ถ้าเป็นพฤหัส – ได้ปัญญา, ถ้าเป็นพุธ – น่ารัก อารมณ์ดี, ถ้าเป็นอาทิตย์ – ผู้ใหญ่สนับสนุน\",\"เรือนที่ 7 จากเจ้าเรือนที่ 9 แสดงสิ่งที่ควรอธิษฐาน: คู่ครองที่ดี คู่ที่มีศรัทธาทางธรรมะร่วมกัน\",\"เรือนที่ 2 จากเจ้าเรือนแสดงรายได้ที่เพิ่มขึ้น ต้องดูดาวเจ้าเรือนที่ 2 เพื่อยืนยัน\",\"สัมพันธภาพกับพ่อ ลูก และการศึกษา มักเป็นไปในทิศทางที่ดี\",\"หากมีดาวบาปร่วมเรือนกับเจ้าเรือนที่ 9 ควรทำวิธีแก้กรรม\",\"อุปสรรคสำคัญมาจากเรือนที่ 4 (บ้าน แม่) และเรือนที่ 8 (มรดก ญาติฝ่ายคู่)\",\"หากมีดาวอังคารในเรือนที่ 4 พี่น้องชายอาจเป็นอุปสรรค\",\"เรือนที่ 3 คือการสื่อสาร เป็นบททดสอบสำคัญ ต้องสื่อสารด้วยความเมตตา\",\"เรือนที่ 10 คือหน้าที่การงาน ต้องซื่อตรง มีจรรยาบรรณ หากไม่ทำตาม จะเสียโชคลาภทันที\"]"::jsonb),
("9in2",9,2,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 2","[\"เป็นตำแหน่งที่แสดงถึงทักษะเฉพาะตัวที่นำพาความสำเร็จ เช่น พูดเก่ง เขียนเก่ง มีศิลปะ\",\"มีเสน่ห์ทางเพศสูง ความต้องการในรูปแบบประสาทสัมผัสก็สูง เช่น การกิน\",\"ระวังพฤติกรรมการกินมากเกินไป อาจมีปัญหาโรคอ้วน หรือติดแอลกอฮอล์\",\"ต้องควบคุมการบริโภคอย่างมีสติ\",\"การพูดคือกุญแจสำคัญต่อโชคลาภ พูดอย่างซื่อตรงไม่อ้อมค้อมจะเพิ่มพลังบุญ\",\"การโกหกหรือพูดเสียดแทงจะทำลายโชคลาภในทันที\",\"ต้องดูดาวเจ้าเรือนที่ 6 เพื่อหาจุดอ่อนในพฤติกรรมและแก้ไขให้หมดไป\",\"หากมีดาวจันทร์ในเรือนนี้ หรือเชื่อมโยงกับเจ้าเรือนที่ 9 จะเพิ่มโชคลาภ\",\"สามารถเป็นนักเขียน บล็อกเกอร์ ผู้มีชื่อเสียงในสื่อออนไลน์ได้\",\"รายได้อาจมาจากมรดก ธุรกิจครอบครัว หรือกิจการร่วมกับผู้อื่น\",\"หากมีดาวบาปในเรือนหรือร่วมเจ้าเรือน ต้องทำพิธีแก้กรรม\",\"โชคลาภจะมาจากเรือนที่ 6 เช่น งานด้านสุขภาพ การดูแลสัตว์ หรือความช่วยเหลือจากลูกน้อง\",\"อุปสรรคมาจากเรือนที่ 5 (การศึกษา ลูก) และเรือนที่ 9 (พ่อ)\",\"จะถูกทดสอบจากเรือนที่ 4 (แม่ บ้าน) ต้องมีความรับผิดชอบในครอบครัว\",\"เรือนที่ 11 คือหน้าที่รับผิดชอบต่อกลุ่มเพื่อน พี่น้อง ต้องให้การสนับสนุนอย่างจริงใจ\"]"::jsonb),
("9in3",9,3,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 3","[\"พี่น้อง ลูกพี่ลูกน้อง และญาติฝ่ายแม่คือกรรมเก่าที่ส่งผลดีหรือร้าย\",\"จะมีทักษะด้านการสื่อสาร เช่น พูด เขียน ร้องเพลง หรือความสามารถเชิงปฏิบัติอื่นๆ\",\"หากดาวเจ้าเรือนที่ 9 เป็นบาปเคราะห์ อาจสื่อสารกับพ่อได้ไม่ดี ต้องแก้ไขด้วยตนเอง\",\"ถ้าปฏิบัติตามธรรมะ จะได้รับโชคจากคู่ครอง คู่รักจะช่วยเสริมบุญและความมั่นคงในชีวิต\",\"เพื่อนช่วยส่งเสริมชีวิต เป็นตำแหน่งที่ดีสำหรับการมีบ้านหรือได้มรดกจากฝ่ายแม่\",\"อุปสรรคมาจากเรือนที่ 6 (ลูกน้อง เพื่อนร่วมงาน) และเรือนที่ 10 (เจ้านาย)\",\"การถูกทดสอบจะมาจากเรือนที่ 5 (ลูก การศึกษา) และเรือนที่ 12 (หนี้ การใช้จ่ายเกินตัว)\",\"หลีกเลี่ยงการใช้เงินเกินตัว และชำระหนี้อย่างสม่ำเสมอเพื่อคงโชคลาภไว้\"]"::jsonb),
("9in4",9,4,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 4","[\"นำโชคลาภ ความมั่งคั่ง และความสุขเข้ามาในชีวิต\",\"หากปฏิบัติต่อแม่ด้วยความเคารพและมีจิตธรรมะในบ้าน จะยิ่งเพิ่มพูนโชค\",\"อาจมีโชคจากมรดก หรืออสังหาริมทรัพย์\",\"การไปต่างประเทศ หรือการซื้อบ้านที่ต่างแดนจะเป็นมงคล\",\"อุปสรรคจะมาจากเรือนที่ 10 (การงาน) และเรือนที่ 8 (คู่ครอง เพื่อน)\",\"คู่ครอง เพื่อน และเพื่อนร่วมงานอาจทำให้หลุดออกจากเส้นทางธรรมะ ต้องระวัง\",\"จะถูกทดสอบจากคนรอบตัวมาก ต้องมีความอดทน มีธรรมะ และยึดมั่นในความถูกต้อง\",\"หน้าที่ที่สำคัญที่สุดคือการมีจริยธรรมส่วนตัวระดับสูง หากรักษาไว้ได้ โชคลาภจะไม่หายไป\"]"::jsonb),
("9in5",9,5,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 5:","[\"เป็นตำแหน่งที่ให้ผลดีมากในเรื่องของการศึกษา ความสามารถทางปัญญา และความสำเร็จจากอดีตชาติ\",\"เจ้าชะตามีโอกาสเรียนรู้สิ่งต่าง ๆ ได้รวดเร็ว และมักจะเป็นผู้มีพรสวรรค์ทางศิลปะ ดนตรี หรือการแสดงออก\",\"เป็นผู้ที่มีความสนใจในเรื่องของธรรมะ ปรัชญา และมีโอกาสพบครูหรือผู้สอนที่มีอิทธิพลในชีวิต\",\"มีโอกาสได้ลูกที่ดี ลูกมีโชค หรือได้รับโชคจากลูก ๆ\",\"บ้านของคุณคือสถานที่ที่ส่งเสริมโชคลาภ ความมั่นคงในบ้าน หรือการสืบสานความรู้ภายในครอบครัว\",\"จุดท้าทายสำคัญอยู่ที่รายได้และการจัดการทรัพย์สิน (เรือนที่ 2 ซึ่งเป็นเรือนที่ 10 จากเรือนที่ 5)\",\"หากไม่มีการจัดการการเงินที่ดี โชคที่ได้รับอาจหลุดมือไปอย่างรวดเร็ว\"]"::jsonb),
("9in6",9,6,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 6:","[\"เป็นตำแหน่งท้าทายของดาวเจ้าเรือนที่ 9 เพราะเรือนที่ 6 เป็นเรือนของศัตรู โรคภัย หนี้สิน และความขัดแย้ง\",\"เจ้าชะตาอาจต้องเผชิญกับศัตรู อุปสรรค หรือคดีความในชีวิต\",\"อย่างไรก็ตาม หากสามารถรักษาความยุติธรรม ความมีธรรมะ และใช้ปัญญาอย่างถูกต้อง เจ้าชะตาจะสามารถชนะอุปสรรคเหล่านี้ได้\",\"มีโอกาสที่จะมีหน้าที่รับผิดชอบต่อสัตว์เลี้ยง หรือช่วยเหลือผู้ที่อ่อนแอกว่า (งานการกุศล งานสังคม)\",\"การศึกษาระดับสูงอาจถูกขัดขวาง หรือได้รับล่าช้า ควรพยายามอดทนและไม่ยอมแพ้\",\"จุดแข็งคือความสามารถในการรับมือกับวิกฤติ แปรเปลี่ยนวิกฤติให้เป็นโอกาส\",\"บ้านและชีวิตส่วนตัวอาจมีความไม่มั่นคง หรืออาจต้องอยู่ห่างจากบ้านเกิดเพื่อสร้างโชคด้วยตนเอง\"]"::jsonb),
("9in7",9,7,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 7:","[\"โชคและธรรมะของเจ้าชะตาจะเข้ามาผ่านคู่ครอง หรือความสัมพันธ์ระยะยาว\",\"คู่ครองอาจเป็นคนต่างชาติ หรือมีบทบาททางจิตวิญญาณในชีวิตเจ้าชะตา\",\"การแต่งงานหรือการร่วมมือกับผู้อื่นนำมาซึ่งโชคลาภและความเจริญก้าวหน้า\",\"เหมาะกับการทำงานคู่ หรือทำธุรกิจที่ต้องอาศัยความร่วมมือ\",\"จุดท้าทายคือความผูกพันทางอารมณ์ที่ลึกซึ้งจนยากจะปล่อยวาง ต้องระวังเรื่องการคาดหวังสูงจากคู่ครอง\",\"คู่ครองอาจมีคารมดี มีความรู้สูง หรือเป็นนักบวช นักวิชาการ\",\"ชีวิตสมรสควรมีพื้นฐานจากปรัชญา ความเชื่อ หรือเป้าหมายร่วมที่มีธรรมะหนุน\"]"::jsonb),
("9in8",9,8,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 8:","[\"เป็นตำแหน่งที่ลึกซึ้งทางจิตวิญญาณมาก อาจทำให้เจ้าชะตาแสวงหาความหมายชีวิตอย่างลึกซึ้ง\",\"ได้รับโชคลาภผ่านการเปลี่ยนแปลง การสูญเสีย หรือประสบการณ์เหนือธรรมชาติ\",\"มีสัญชาตญาณแม่นยำ สนใจศาสตร์เร้นลับ โหราศาสตร์ หรือธรรมะระดับสูง\",\"ความสัมพันธ์กับพ่ออาจซับซ้อน หรือพ่ออาจมีบทบาทสำคัญในการเปลี่ยนแปลงชีวิต\",\"จุดท้าทายคือเรื่องสุขภาพจิต การจัดการกับความสูญเสีย หรือเรื่องมรดก การเงินร่วม\",\"ความสามารถในการฟื้นตัวหลังผ่านวิกฤติถือเป็นจุดแข็ง\",\"การเรียนรู้ผ่านวิกฤติคือบทเรียนแห่งธรรมะที่เจ้าชะตาต้องเผชิญ\"]"::jsonb),
("9in9",9,9,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 9","[\"เป็นตำแหน่งที่ให้โชคลาภอย่างมาก รวมถึงความมั่งคั่งและความสามารถพิเศษ\",\"เจ้าชะตามักจะหน้าตาดีด้วย เพราะมีแอสเปกต์ถึงลัคนา\",\"เป็นผลมาจากการปฏิบัติดีตามธรรมะในอดีตชาติ และผลบุญนั้นกลับมาในชาตินี้\",\"มักได้รับความช่วยเหลือจากพี่น้อง โดยเฉพาะน้อง ๆ\",\"ความสำเร็จและชื่อเสียงอาจเกิดจากบุญเก่าหรือจิตวิญญาณทางธรรมะในตัวเอง\",\"อย่างไรก็ตาม ต่างประเทศอาจไม่ใช่โชคเสมอไป ต้องพิจารณาเจ้าเรือนที่ 12 และเจ้าเรือนที่ 4 ประกอบ\",\"ชีวิตในบ้านหรือครอบครัวอาจพบกับความวุ่นวาย ไม่สงบ แม้จะมีความมั่งคั่งก็ตาม\",\"อาจมีปัญหากับมารดา หรือมารดาเผชิญชะตากรรมยากลำบาก\",\"หากดาวประจำเรือนที่ 9 เป็นบาปเคราะห์ เช่น เสาร์ อังคาร ราหู เกตุ อาจมีปัญหากับบิดา\",\"เจ้าชะตามีแนวโน้มสูงในการแสวงหาศาสนา ปรัชญา หรือระบบความเชื่อเพื่อยึดเหนี่ยวจิตใจ\",\"มักเรียนรู้ได้ดี โดยเฉพาะในด้านที่ลึกซึ้ง แต่หากดาวประจำเรือนมีบาปเคราะห์ร่วม อาจเรียนช้าหรือสะดุด\",\"มีพรสวรรค์ในการสอน ถ่ายทอดความรู้ ได้โชคจากการสอนหรือจากลูกหลาน\",\"ได้ความนิยมจากคนทั่วไปหรือสุขภาพดีจากแอสเปกต์ไปยังลัคนา\",\"การทดสอบที่ใหญ่ของเจ้าชะตาอยู่ที่พี่น้องผู้ใหญ่ หรือแวดวงเพื่อนฝูง\",\"อาจมองคนผิด หลงเชื่อคนง่าย มีปัญหาเรื่องความไว้ใจในกลุ่มเพื่อน\",\"จุดที่ต้องทำงานหนักและมีภาระทางธรรมะคือเรือนที่ 6 การรับใช้ การดูแลสัตว์ การช่วยเหลือผู้ตกทุกข์\",\"อาจเจอคดีความ หรือปัญหาทางกฎหมาย แต่หากเจ้าชะตามีความซื่อสัตย์ จะไม่ส่งผลเสียระยะยาว\"]"::jsonb),
("9in10",9,10,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 10","[\"เป็นตำแหน่งที่ดีเยี่ยม มีโอกาสประสบความสำเร็จในชีวิตสูง\",\"ได้รับความเมตตาจากผู้ใหญ่ หัวหน้า หรือผู้มีอำนาจ\",\"มีตำแหน่งที่คนยกย่อง เคารพ ไม่ว่าจะอยู่ในระดับใด\",\"ความสำเร็จในอาชีพเกิดจากกรรมเก่าและการทำงานอย่างต่อเนื่อง\",\"เจ้าชะตามีวินัย ขยัน แต่บางครั้งอาจไม่ต้องพยายามเท่าคนอื่นก็ประสบความสำเร็จได้\",\"แต่ชีวิตครอบครัวอาจไม่ราบรื่น อาจต้องย้ายบ้านบ่อย หรือไม่มีความสงบในบ้าน\",\"ความสัมพันธ์กับมารดาอาจถูกทดสอบ\",\"ได้โชคด้านเพื่อนฝูง และมีรายได้หลากหลายช่องทาง\",\"มักเผชิญศัตรู คู่แข่ง และการแข่งขันในอาชีพ แต่สิ่งเหล่านี้กลับยิ่งสร้างชื่อเสียงให้ตน\",\"ระวังเรื่องสุขภาพ เพราะอาจเผลอละเลยหรือหมกมุ่นกับรูปลักษณ์เกินไป\",\"ระวังอีโก้สูง ซึ่งอาจเป็นอุปสรรคในชีวิต\",\"ความสัมพันธ์กับบุตรมีความซับซ้อน อาจมีลูกที่เกิดจากความลับ หรือมีความขัดแย้งกับลูก\",\"ต่างประเทศสร้างความท้าทาย ควรระวังค่าใช้จ่ายที่สูงหรือหนี้สิน\",\"จุดที่ต้องชดใช้กรรมหรือทำหน้าที่ตามธรรมะคือเรือนที่ 7 ต้องดูแลคู่ครองให้ดี ซื่อสัตย์ ตรงไปตรงมา\"]"::jsonb),
("9in11",9,11,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 11","[\"ให้โชคด้านรายได้อย่างมาก มีรายได้หลายทาง\",\"เมื่อถึงคราวจำเป็น โอกาสดีมักปรากฏทันเวลาเสมอ\",\"ได้รับความช่วยเหลือจากพ่อ พี่น้อง พี่สาวพี่ชาย และญาติพี่น้องทั่วไป\",\"มีพรสวรรค์ด้านศิลปะ การสื่อสาร การเขียน การร้องเพลง การแสดง ฯลฯ\",\"เป็นนักเรียนรู้เร็ว เรียนรู้อะไรได้หลากหลาย\",\"มีแอสเปกต์ถึงเรือนที่ 7 ทำให้เก่งด้านการเจรจาธุรกิจ การเป็นที่ปรึกษาทางการเงิน\",\"อาจทำให้คนในครอบครัวอิจฉา เพราะความสำเร็จขยายตัวรวดเร็ว\",\"ศัตรูหรือคู่แข่งในที่ทำงานอาจอิจฉา ต้องระวังคนรอบข้าง\",\"เจ้าชะตามีพันธะกรรมในการช่วยเหลือผู้อื่น ยิ่งให้เท่าไร ยิ่งได้คืน\",\"ต้องพิสูจน์ตัวเองผ่านการช่วยเหลือผู้อื่น และผ่านการเปลี่ยนแปลงภายใน (เรือนที่ 8)\",\"สามารถเป็นนักบำบัด ผู้ให้คำปรึกษา นักโหราศาสตร์ ฯลฯ\",\"เมื่อเผชิญวิกฤตส่วนตัว มักสามารถพลิกฟื้นกลับมาได้ดีขึ้นกว่าเดิม\"]"::jsonb),
("9in12",9,12,"ดาวเจ้าเรือนที่ 9 สถิตเรือนที่ 12","[\"เป็นตำแหน่งในเรือนทุกข์ ต้องดูบทสวดหรือการแก้กรรมประกอบ\",\"ชีวิตอาจรู้สึกไร้ทิศทาง ขาดความมั่นใจในจุดหมาย\",\"แต่จะได้โชคเมื่ออยู่ในต่างแดน ห่างจากบ้านเกิด\",\"รายได้และโอกาสมักมาจากแหล่งต่างประเทศหรือองค์กรใหญ่\",\"เรียนหรือทำงานในโรงพยาบาล สถานพยาบาล โรงเรียน คุก ฯลฯ มักมีโชค\",\"ไม่เหมาะกับการทำงานอิสระเท่าไร ควรมีโครงสร้างชีวิตที่ชัดเจน\",\"ยิ่งให้การศึกษาแก่เด็ก ยิ่งให้ทานด้านความรู้ ยิ่งได้ผลบุญกลับคืน\",\"มีความสามารถในด้านศาสตร์ลึก เช่น โหราศาสตร์ ไสยศาสตร์ จิตวิญญาณ\",\"ความสัมพันธ์กับบิดาอาจมีระยะห่าง หรือมีกรรมเก่าร่วมกัน\",\"ความสัมพันธ์ในครอบครัวอาจซับซ้อน โดยเฉพาะกับพี่น้อง ญาติ\",\"มีพันธะทางวิญญาณกับมารดา อาจได้รับแรงสนับสนุนจากแม่\",\"ความสัมพันธ์กับคู่ครองต้องอาศัยความอดทนสูง มีกรรมเกี่ยวกับสุขภาพของคู่หรือของตน\",\"จุดที่ต้องทำหน้าที่ทางธรรมะคือการศึกษา ห้ามละทิ้งโอกาสทางการเรียนรู้โดยเด็ดขาด\",\"จะได้พบครูทางจิตวิญญาณหรือปรัชญาที่เปลี่ยนชีวิต\",\"ต้องมอบตัวและเปิดใจให้กับประสบการณ์ทางจิตวิญญาณเพื่อเติบโต\",\"เจ้าเรือนที่ 10\"]"::jsonb),
("10in1",10,1,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 1:","[\"แสดงถึงชื่อเสียง ความฉลาด ทักษะ และความสามารถสูงในอาชีพ\",\"มีเกียรติยศในระดับหนึ่ง ไม่ว่าจะเป็นในที่ทำงาน หรือในระดับประเทศ\",\"เป็นตำแหน่งราชโยค หากไม่มีบาปเคราะห์มากระทบ\",\"มีความสามารถในการใช้คำพูดเพื่อความก้าวหน้าในอาชีพ เช่น นักเขียน นักข่าว นักพูด\",\"วัยเด็กอาจมีอุปสรรค โดยเฉพาะกับแม่ หรือสุขภาพ แต่หลังจากนั้นชีวิตจะดีขึ้นมาก\",\"มีความมุ่งมั่นและควบคุมชีวิตการงานได้ดี\",\"ชอบทำงานกับผู้อื่น ร่วมมือในธุรกิจ และชอบงานที่มีความคิดสร้างสรรค์\"]"::jsonb),
("10in2",10,2,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 2:","[\"เป็นตำแหน่งที่ทำให้มีรายได้มาก มีทักษะในการเก็บเงิน สนับสนุนครอบครัว\",\"มีความสามารถในการพูดจาที่ทำให้คนเชื่อถือ เป็นจุดเด่นของอาชีพ\",\"อย่าเปรียบเทียบตัวเองกับคนอื่นเรื่องเงินทอง อาจเกิดกรรมไม่ดี\",\"มีความสุขจากงานที่เกี่ยวข้องกับการสอน การแนะแนว งานสร้างสรรค์\",\"ต้องระวังการเมืองในที่ทำงาน และคู่แข่งที่อาจทำให้ลำบากใจ\"]"::jsonb),
("10in3",10,3,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 3:","[\"ทำให้เป็นคนขยัน ชอบทำงานระยะสั้น หรืองานหลายอย่างพร้อมกัน\",\"ทำงานกับมือได้ดี เหมาะกับงานช่าง ศิลปะ งานเขียน งานที่ใช้สกิลเฉพาะ\",\"สามารถสื่อสารโน้มน้าวใจคนได้ดี ให้กำลังใจผู้อื่นได้\",\"เหมาะกับการเดินทางไปต่างประเทศ หรือทำงานที่มีความเชื่อมโยงกับต่างชาติ\",\"มักได้ผลตอบแทนจากคู่ครอง หรือทำงานกับคู่ครองได้ดี\"]"::jsonb),
("10in4",10,4,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 4:","[\"ทำงานด้วยใจ มีความสุขกับการทำงาน มักทำงานจากบ้าน หรือธุรกิจส่วนตัว\",\"เหมาะกับงานเกี่ยวกับอสังหาริมทรัพย์ การออกแบบภายใน หรือที่ทำงานที่ให้ความรู้สึกเหมือนบ้าน\",\"ใส่ใจในครอบครัว โดยเฉพาะแม่ และมักมีกรรมที่ต้องดูแลแม่\",\"เมื่อเปลี่ยนงานมักได้สิ่งดีๆ ตอบแทน\",\"ระวังปัญหาจากเพื่อนร่วมงานที่ทำให้เครียดในระยะยาว\"]"::jsonb),
("10in5",10,5,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 5:","[\"มีความรู้กว้างขวาง ชอบเรียนรู้ มักได้ความสำเร็จทางวิชาการ\",\"เป็นตำแหน่งที่สร้างสรรค์ เหมาะกับงานศิลปะ ดนตรี เขียนบท หรือการแสดง\",\"ชอบศึกษาความลี้ลับ เช่น โหราศาสตร์ จิตวิญญาณ หรือจิตวิทยา\",\"เหมาะกับการเป็นครู ผู้แนะนำ หรือโค้ช\",\"การศึกษาสูงจะนำความสำเร็จมาให้มากขึ้น\",\"ต่างประเทศ และผู้ใหญ่ที่เป็นครูจะนำโชค\"]"::jsonb),
("10in6",10,6,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 6:","[\"มีทักษะทางเทคนิคและศิลปะโดยเฉพาะแบบลงมือปฏิบัติ เช่น แพทย์ นักบำบัด ช่าง\",\"มักเจออุปสรรคหรือการแข่งขันสูงในอาชีพ ต้องอดทน\",\"บางครั้งมีชื่อเสียงหลังเสียชีวิต หรือชื่อเสียงที่ยั่งยืน\",\"ทำงานในโรงพยาบาล ศูนย์สงเคราะห์ หรือกับสัตว์จะดี\",\"ได้แรงบันดาลใจจากครู หรือพ่อ และต้องเรียนรู้ที่จะพึ่งพาตนเอง\"]"::jsonb),
("10in7",10,7,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 7:","[\"มีความสามารถในการทำธุรกิจ ความสัมพันธ์สาธารณะ และงานขาย\",\"คู่ครองมีบทบาทสำคัญในอาชีพ อาจพบคู่จากที่ทำงาน หรือทำงานกับคู่\",\"ได้รับการสนับสนุนจากหัวหน้า หรือผู้อาวุโส\",\"แต่ต้องระวังการแข่งขัน หรือปัญหาจากคนรอบข้างที่ทำงาน\",\"ควรหาสถานที่ทำงานที่รู้สึกว่าเหมาะกับตัวเอง และให้ความรู้สึกอบอุ่น\"]"::jsonb),
("10in8",10,8,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 8:","[\"มีทัศนคติต่องานที่ไม่เหมือนใคร อาจไม่ยึดติดกับสถานะ เงิน หรือชื่อเสียง\",\"ยากที่จะอยู่กับงานเดิมนานๆ มักเปลี่ยนอาชีพบ่อย\",\"เหมาะกับอาชีพด้านการบำบัด เยียวยา จิตวิญญาณ จิตวิทยา หรือปรึกษา\",\"มักให้ความช่วยเหลือผู้อื่น และไม่สนใจการยกย่องภายนอก\",\"ต้องระวังอย่าวิจารณ์หรือขัดแย้งกับคนอื่นมากเกินไป จะทำให้ไม่มีความสุขในงาน\",\"มีหัวใจที่เสียสละและจิตใจกว้างขวาง\"]"::jsonb),
("10in9",10,9,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 9","[\"แม้ดูเหมือนจะไม่มั่นคงในอาชีพ แต่แท้จริงแล้วเป็นจุดเริ่มต้นของเส้นทางที่ต่างจากที่คุณเคยคาดคิด\",\"มีโชคเกี่ยวกับอาชีพตั้งแต่เด็ก แต่ยังไม่แน่ใจทิศทาง\",\"หากยึดมั่นในหลักธรรมะ ซื่อสัตย์ โปร่งใส จะได้รับเกียรติ ชื่อเสียง ความมั่งคั่ง\",\"หากผิดหลักธรรมะ มีเล่ห์เหลี่ยม จะล่มจมอย่างรวดเร็ว\",\"ต่างแดนมีบทบาทสำคัญในอาชีพ มีโอกาสเดินทางหรืออยู่อาศัยในต่างประเทศ\",\"ความมั่งคั่งอาจไม่มั่นคงเต็มที่ แต่สามารถมีได้จากการแบ่งปัน ไม่ยึดติด\",\"มีกรรมเกี่ยวกับลูก บางคนอาจมีลูกหลายคน\",\"การเปลี่ยนแปลงในหน้าที่การงานมักสัมพันธ์กับสถานการณ์ภายในบ้าน\",\"สนใจด้านปรัชญา ศาสนา การเขียน การสอน ระดับสูง\"]"::jsonb),
("10in10",10,10,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 10","[\"ถือเป็น \\\"สิทธิ์โยคะ\\\" (Siddhi Yoga) บ่งบอกถึงพลัง ความสามารถ และความสำเร็จอย่างสูง\",\"มีความกล้า ความพากเพียร ตั้งใจแน่วแน่ ทำอะไรก็สำเร็จได้\",\"เป็นแบบอย่างแก่ผู้อื่น แต่หากทำผิดศีลธรรม ชื่อเสียงจะเสียหายมาก\",\"มีศักยภาพสูงสุด ทะลุขีดจำกัดทางกาย ใจ หรือสังคมได้\",\"อย่าพยายามเลียนแบบผู้อื่น ต้องเป็นตัวของตัวเอง จะได้ความสำเร็จและชื่อเสียง\",\"อาจไม่ได้เป็น CEO โดยตรง แต่อยู่ในตำแหน่งที่ประสบความสำเร็จ มีความรับผิดชอบสูง\",\"หากสูญเสียแรงสนับสนุนจากผู้คน จะกระทบอาชีพอย่างแรง\"]"::jsonb),
("10in11",10,11,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 11","[\"นำไปสู่รายได้และกำไรเพิ่มขึ้น แต่ขึ้นอยู่กับ \\\"ใครที่คุณรู้จัก\\\" มากกว่า \\\"คุณรู้อะไร\\\"\",\"เครือข่าย สังคม กลุ่มคนทำงาน มีผลต่อความสำเร็จในอาชีพอย่างมาก\",\"ดีสำหรับคนที่ทำธุรกิจส่วนตัว งานบริการ หรืออาชีพสร้างสรรค์ เช่น การเขียน การแสดง\",\"ต้องมีทักษะเฉพาะ และอัปเดตทักษะเสมอ เพื่อไม่ให้ตกยุค\",\"อุปสรรคใหญ่คือศัตรู คู่แข่ง การฟ้องร้อง และสุขภาพขณะทำงาน\",\"ความปรารถนาในอาชีพคือการสร้างผลงานที่สร้างสรรค์ มีผลกระทบเชิงบวกต่อผู้อื่น\"]"::jsonb),
("10in12",10,12,"ดาวเจ้าเรือนที่ 10 สถิตเรือนที่ 12","[\"มีความกังวล ความไม่มั่นคงในอาชีพบ้าง โดยเฉพาะเรื่องการเงิน ความมั่นคง\",\"ต้องเชื่อมั่นในพรสวรรค์ของตนเอง มีทักษะเฉพาะ เช่น เขียน โปรแกรม จิตวิทยา โหราศาสตร์\",\"สื่อสารกับคนทั่วโลกผ่านอินเทอร์เน็ตได้ผลดี\",\"ชอบทำงานในที่เงียบ สันโดษ ห่างไกล หรือองค์กรขนาดใหญ่ เช่น โรงเรียน โรงพยาบาล\",\"ต้องดูแลด้านสุขภาพจิต มีการพักผ่อน นั่งสมาธิเป็นประจำ\",\"ความสัมพันธ์ส่วนตัวกระทบอาชีพอย่างมาก ต้องเลือกคู่ชีวิตที่เหมาะสม\",\"ไม่เหมาะกับธุรกิจที่มีพาร์ทเนอร์มาก ควรทำคนเดียวหรือในองค์กรใหญ่\",\"ต้องจัดการกับเงาด้านใน ความกลัว ความวิตก เพื่อไม่ให้กระทบความสำเร็จ\",\"หากจัดการได้ จะมีความสำเร็จอย่างลึกซึ้ง เป็นผู้เชี่ยวชาญเฉพาะทางที่มีพลังสูง\",\"เจ้าเรือนที่ 11\"]"::jsonb),
("11in1",11,1,"ดาวเจ้าเรือนที่ 11 สถิตเรือนที่ 1","[\"เจ้าชะตามีแรงผลักดันอย่างมากในการสร้างความสัมพันธ์ทางสังคมด้วยตนเอง ไม่รอให้ใครเข้ามาหา แต่จะเดินเข้าไปหาความสัมพันธ์เอง\",\"เป็นตำแหน่งที่ส่งผลให้เจ้าชะตามีแรงจูงใจสูงในการหาผลประโยชน์จากการติดต่อสื่อสารกับผู้อื่น มีแรงผลักดันในการประสบความสำเร็จจากเครือข่ายรอบตัว\",\"มักเป็นคนที่ดึงดูดกลุ่มเพื่อนหรือเครือข่ายที่มีอิทธิพล มีแรงบันดาลใจอยากสร้างอิทธิพลให้ผู้อื่น\",\"ชอบเข้าสังคมมาก มีความทะเยอทะยานสูง และต้องการการยอมรับจากกลุ่มสังคมหรือเพื่อนฝูง\",\"หากดาวเจ้าเรือนนี้เป็นประโยชน์ จะทำให้เจ้าชะตามีความเป็นผู้นำในกลุ่มสังคม มีความสามารถในการรวมกลุ่มและจัดการเครือข่ายได้อย่างมีประสิทธิภาพ\",\"หากเป็นบาปเคราะห์ อาจทำให้ความสัมพันธ์กับเพื่อนมีปัญหา เช่น การหักหลัง การแย่งผลประโยชน์ การทะเลาะเบาะแว้ง\",\"สิ่งที่ทำให้เจ้าชะตามีความสุขคือความรู้สึกว่าตนเองมีคุณค่าในสายตาสังคม และได้รับการยอมรับจากคนรอบข้าง\"]"::jsonb),
("11in2",11,2,"ดาวเจ้าเรือนที่ 11 สถิตเรือนที่ 2","[\"การมีรายได้ การสะสมทรัพย์ และความมั่งคั่งเกี่ยวข้องกับเครือข่ายหรือกลุ่มเพื่อนเป็นอย่างมาก\",\"เจ้าชะตาอาจได้ประโยชน์จากการทำธุรกิจร่วมกับเพื่อน หรือมีรายได้จากการเข้าสังคม การพูดคุย หรือการนำเสนอสิ่งที่เป็นประโยชน์ต่อกลุ่ม\",\"อาจเป็นคนที่มีทักษะการเจรจาต่อรองเพื่อผลประโยชน์ของตนเองหรือกลุ่มได้ดี มีความสามารถในการสร้างรายได้จากเครือข่ายโดยตรง\",\"หากดาวนี้เป็นบาปเคราะห์ อาจเกิดปัญหาเรื่องการเงินกับเพื่อน เช่น ถูกหลอก หรือความคาดหวังไม่ตรงกันเรื่องผลประโยชน์\",\"ความสุขของเจ้าชะตามาจากความมั่นคงทางการเงิน และการได้แบ่งปันสิ่งของหรือเงินทองให้กับกลุ่มที่ตนเองรู้สึกผูกพันด้วย\"]"::jsonb),
("11in3",11,3,"ดาวเจ้าเรือนที่ 11 สถิตเรือนที่ 3","[\"เพื่อนและเครือข่ายมีบทบาทอย่างมากในเรื่องการสื่อสาร การเขียน การพูด การเรียนรู้ และการเดินทางระยะสั้น\",\"เจ้าชะตาอาจมีเพื่อนเป็นนักเขียน นักพูด หรือนักเดินทาง และได้รับแรงบันดาลใจหรือโอกาสจากกลุ่มคนเหล่านี้\",\"อาจมีความสามารถในการนำเสนอแนวคิดสู่สาธารณะ โดยได้รับการสนับสนุนหรือผลักดันจากเพื่อนฝูง\",\"การร่วมมือกับพี่น้องหรือคนในครอบครัว (โดยเฉพาะพี่น้อง) เพื่อน หรือญาติ อาจสร้างรายได้หรือชื่อเสียง\",\"หากดาวเป็นบาปเคราะห์ อาจเกิดการขัดแย้งในเรื่องความคิด การสื่อสาร หรือมีเพื่อนที่ให้ข้อมูลผิดพลาดหรือชักนำไปในทางที่ไม่ดี\",\"ความสุขของเจ้าชะตาอยู่ที่การได้แลกเปลี่ยนความรู้ การสื่อสาร และการเรียนรู้ร่วมกับคนที่มีจิตใจคล้ายกัน\"]"::jsonb),
("11in4",11,4,"ดาวเจ้าเรือนที่ 11 สถิตเรือนที่ 4","[\"มีกรรมที่ลึกกับบ้านเกิดหรือวัฒนธรรมของแม่ และมักได้รับประโยชน์จากฝั่งแม่มากกว่าฝั่งพ่อ\",\"อาจเผชิญปัญหาด้านพัฒนาการในวัยเด็ก โดยเฉพาะถ้าดาวเป็นบาปเคราะห์\",\"ได้รับรายได้จากอสังหาริมทรัพย์ ที่ดิน หรือธุรกิจเกี่ยวกับบ้าน\",\"มีความปรารถนาลึก ๆ ที่จะเป็นที่ยอมรับในสังคม มีชื่อเสียง มีสถานะ\",\"ความพึงพอใจลึกสุดมาจากคู่ชีวิตหรือหุ้นส่วนธุรกิจที่ช่วยสร้างสมดุลในชีวิต\"]"::jsonb),
("11in5",11,5,"ดาวเจ้าเรือนที่ 11 สถิตเรือนที่ 5","[\"เป็นตำแหน่งที่โชคดีมาก คุณเกิดมาเพื่อเรียนรู้สิ่งที่ยังไม่จบในอดีตชาติ โดยเฉพาะด้านวิญญาณและมนตรา\",\"การเรียนรู้ การศึกษา เป็นปัจจัยสำคัญในการประสบความสำเร็จ\",\"มีพรสวรรค์ด้านศิลปะ ดนตรี การเต้น การแสดง และอาจเป็นนักแสดง ครู หรือวิทยากร\",\"การมีลูกจะนำโชคและการเปลี่ยนแปลงเชิงบวก\",\"ได้รับความพึงพอใจจากการศึกษาศาสตร์ลึกลับ เช่น โหราศาสตร์ ประวัติศาสตร์ หรือโบราณคดี\"]"::jsonb),
("11in6",11,6,"ดาวเจ้าเรือนที่ 11 สถิตเรือนที่ 6","[\"คุณมีคู่แข่งจากชาติปางก่อนที่กลับมาเกิดร่วมกันเพื่อแก้กรรม อาจเป็นเพื่อน หุ้นส่วน หรือญาติ\",\"สถานการณ์ชีวิตมักเต็มไปด้วยความท้าทาย ความขัดแย้ง และการแข่งขัน\",\"หากจัดการไม่ดี อาจเกิดปัญหาสุขภาพหรือภาวะเสพติด เช่น อาหาร เหล้า การพนัน ฯลฯ\",\"ทางออกคือการให้อภัย ไม่เอาชนะใคร และไม่ตกเป็นเหยื่อของกรรมซ้ำ\",\"อาจประสบความสำเร็จในสายงานด้านกฎหมาย การแพทย์ หรือการดูแลสุขภาพของผู้อื่น\",\"ความสำเร็จที่แท้จริงเกิดจากการออกจากบ้านเกิดและเดินทางไกล เช่น ไปต่างประเทศ หาครูทางจิตวิญญาณ หรือพัฒนาตัวเองในต่างแดน\",\"11th Lord in 7th House\",\"ดาวเจ้าเรือนที่ 11 สถิตเรือนที่ 7 หมายถึงคุณมีความปรารถนาอย่างลึกซึ้งที่จะมีความสัมพันธ์กับคู่ครองในชาตินี้\",\"เป็นความปรารถนาที่สั่งสมมาหลายชาติ เกิดมาเพื่อพบเจอความสัมพันธ์นี้\",\"หากดาวเจ้าเรือนที่ 11 เป็นบาปเคราะห์ เช่น อังคาร เสาร์ ราหู เกตุ อาจมีความท้าทายในความสัมพันธ์ใกล้ชิด\",\"คุณมักทุ่มเทให้กับคู่ครองมากเกินไป ต้องระวังอย่าให้ตัวเองถูกรังแกหรือเอาเปรียบ\",\"ความสัมพันธ์มักเริ่มต้นจากกลุ่มเพื่อนหรือการเดินทาง\",\"มีลักษณะเป็นคนเปิดกว้าง เป็นมิตร ดึงดูดความสนใจจากผู้อื่นและชอบผู้คน\",\"เหมาะสำหรับการทำธุรกิจ การเป็นผู้ประกอบการ หรือทำงานอิสระ\",\"คู่สมรสหรือนักธุรกิจร่วมมือกันสามารถให้ผลประโยชน์อย่างมาก\",\"คุณยังได้รับผลประโยชน์จากครอบครัวของคู่สมรสด้วย เช่น เครือข่ายทางสังคม การติดต่อ\",\"ความสุขที่ลึกซึ้งมักมาจากการยอมรับในงานหรืออาชีพ ความสำเร็จในอาชีพมีผลต่อความพึงพอใจของคุณ\",\"11th Lord in 8th House\",\"คุณมีความปรารถนาแรงกล้าที่จะมีอิสระในการหาเงินด้วยตนเอง\",\"มักเป็นคนทำงานอิสระหรือเจ้าของกิจการ\",\"รายได้มีความผันผวนสูง จากกรรมเก่าที่เชื่อมโยงกับเรือนที่ 8\",\"การเปลี่ยนแปลงแบบฉับพลัน เช่น ตกงานกะทันหัน หรือมีการปลดออกจากงานบ่อยครั้ง\",\"อย่างไรก็ตาม การเปลี่ยนแปลงเหล่านี้มักนำคุณไปสู่โอกาสที่ดีกว่า\",\"คุณสามารถหากำไรจากการช่วยเหลือผู้อื่นในภาวะวิกฤต เช่น หมอ นักจิตบำบัด นักโหราศาสตร์\",\"มีความปรารถนาจะมีความมั่นคงทางการเงินและครอบครัว แต่ต้องเผชิญกับความผันผวนจากสมาชิกครอบครัวเช่นกัน\",\"หากดาวไม่เสียมาก อาจได้ผลกำไรจากตลาดหลักทรัพย์ การลงทุน\",\"เพื่อนและเครือข่ายทางสังคมให้ความสุขอย่างมาก แต่ก็อาจเปลี่ยนแปลงโดยไม่คาดคิด\",\"ระวังเพื่อนร่วมงานที่อิจฉา หรือมีแรงจูงใจแอบแฝง\",\"ควรเก็บแผนงานไว้เป็นความลับ และเลือกไว้วางใจคนรอบข้างอย่างรอบคอบ\",\"11th Lord in 9th House\",\"เป็นตำแหน่งที่ดีมาก คุณกำลังได้รับผลของกรรมดีจากอดีตชาติ\",\"ได้รับโชคและความสำเร็จอย่างมาก โดยเฉพาะผ่านการเดินทางและการเรียนรู้\",\"คุณจะมีความฉลาด มีความสามารถในการเรียนรู้ และมีโอกาสเพิ่มพูนความมั่งคั่ง\",\"ชีวิตมีการเดินทางบ่อยครั้ง ไปยังที่ที่เคยปรารถนาไว้ในอดีตชาติ\",\"พูดความจริง รักความถูกต้อง มีครูอาจารย์ที่ส่งเสริม\",\"มีสายสัมพันธ์ทางกรรมลึกซึ้งกับบิดา บางคนได้รับทรัพย์สินจากบิดา หรือความเมตตาในรูปแบบอื่น\",\"พี่น้องไม่ว่าจะอายุน้อยหรือมากให้การสนับสนุนที่ดี\",\"บางคนจะมีถิ่นพำนักในต่างประเทศไม่ว่าจะถาวรหรือชั่วคราว และได้รับความสุขจากที่นั้น\",\"ความสุขลึกซึ้งมาจากการเรียนรู้ การฝึกสมาธิ การปลีกวิเวกทางจิตวิญญาณ\",\"ต้องระวังการถูกชักจูงไปทำกิจกรรมที่ไม่เหมาะสมจากเพื่อนหรือเครือข่ายทางสังคม\",\"มีโอกาสก้าวหน้าในการสื่อสาร การเขียน การเผยแพร่\",\"11th Lord in 10th House\",\"แม้จะดูเหมือนเป็นตำแหน่งเสีย (ไปอยู่เรือนที่ 12 จากตัวเอง) แต่จริง ๆ แล้วให้ผลดีมาก\",\"เป็นการสานต่ออาชีพ ความปรารถนา หรือความทะเยอทะยานจากอดีตชาติ\",\"มีความทะเยอทะยานสูง มุ่งมั่น ขยัน และมีระเบียบวินัยสูง\",\"มีพรสวรรค์ทางสติปัญญา ความรู้เฉพาะทางที่ติดตัวมาตั้งแต่เด็ก\",\"หากดาวเสีย อาจมีความสับสนหรืออุปสรรคบ้าง แต่ควรฟังเสียงภายในและทำตามเส้นทางที่รู้ว่าถูกต้อง\",\"มีความลับ มีความปรารถนาจะทำงานจากบ้าน หรือวางแผนจากพื้นที่ส่วนตัวก่อนแสดงออกสู่สาธารณะ\",\"มีชื่อเสียง ได้รับเกียรติจากผู้มีอำนาจ เช่น รัฐบาล หัวหน้า หรือบุคคลระดับสูง\",\"ต้องระวังเพื่อนร่วมงานที่ไม่ซื่อสัตย์ หรือมีจุดประสงค์แอบแฝง\",\"มีความสุขเมื่อได้รับการยอมรับ ยกย่อง หรือคำชมจากสังคม\",\"ชีวิตการงานขึ้นเร็วและตกเร็ว ต้องปรับตัวให้ได้กับความเปลี่ยนแปลงอย่างรวดเร็ว\",\"การทำงานจากบ้าน หรือการมีสำนักงานในบ้านให้ผลดีมาก ลดความตึงเครียดจากการแข่งขันภายนอก\",\"11th Lord in 11th House\",\"ดาวเจ้าเรือนที่ 11 สถิตเรือนของตนเองเป็นตำแหน่งที่แข็งแรงมาก มีพลังให้ผลดีสูง\",\"เป็นกรรมเก่าที่มีความปรารถนาแรงกล้ารอการเติมเต็ม โดยเฉพาะในด้านความรู้หรือทักษะเฉพาะทาง\",\"จะมีโอกาสเรียนรู้หรือพัฒนาทักษะเฉพาะอย่างมากในช่วงมหาดาวของดาวเจ้าเรือนที่ 11\",\"เรือนที่ 5 ซึ่งเป็นเรือนที่ได้รับการส่งพลังโดยตรง บ่งชี้ถึงพรสวรรค์ ความคิดสร้างสรรค์ การแสดง การเรียนรู้\",\"เหมาะสำหรับงานแสดง ศิลปะ การเต้น การร้องเพลง การเขียน หรือการเรียนรู้ในระดับลึก\",\"เป็นผู้นำในกลุ่มสังคม หรือเพื่อนฝูงมักมองว่าคุณคือผู้นำ\",\"เพื่อนบางคนช่วยสนับสนุนอย่างดี บางคนอาจสร้างอันตราย ต้องระวัง\",\"เหมาะกับงานบริหาร การเป็นหัวหน้าโครงการ หรือครูผู้ถ่ายทอดความรู้\",\"ให้ผลดีในเรื่องทรัพย์สิน ความมั่งคั่ง และการกินอาหาร คุณอาจมีรายได้จากธุรกิจอาหาร หรือชอบทำอาหาร\",\"11th Lord in 12th House\",\"มีแนวโน้มได้รับรายได้จากต่างประเทศ หรือจากคนที่อยู่ห่างไกลถิ่นกำเนิด\",\"ความสัมพันธ์กับเพื่อนหรือคู่รักอาจมีเส้นแบ่งไม่ชัดเจน มีความสับสน หรือซ่อนเร้น\",\"เป็นคนโรแมนติกสูง มีเสน่ห์ทางเพศแรง ซึ่งนำไปสู่ความซับซ้อนในความสัมพันธ์\",\"ใส่ใจภาพลักษณ์และสิ่งที่ผู้อื่นคิดมาก\",\"การเดินทางไกลสามารถเพิ่มรายได้ การมีเครือข่ายต่างประเทศให้ผลดี\",\"มักใช้จ่ายเท่าที่หาได้ หรือมากกว่าที่หาได้ ต้องระวังการใช้เงินเกินตัว\",\"เป็นคนใจกว้าง มีความเมตตา การบริจาคหรือทำงานเพื่อสังคมช่วยลดการสูญเสียรายได้\",\"ทำงานในองค์กรใหญ่ เช่น โรงพยาบาล โรงเรียน สถานพยาบาล หรือองค์กรบริการสังคม ให้ผลดี\",\"ความปรารถนาลึกซึ้งคือการช่วยเหลือผู้อื่น เช่น งานแพทย์ งานกฎหมาย งานเพื่อสิ่งมีชีวิตอื่น ๆ\",\"ความสุขลึกซึ้งมาจากเรือนที่ 3 เช่น การเขียน การสื่อสาร การทำงานกับพี่น้องหรือญาติ\",\"เจ้าเรือนที่ 12\"]"::jsonb),
("12in1",12,1,"ดาวเจ้าเรือนที่ 12 สถิตเรือนที่ 1","[\"ค่าใช้จ่ายหรือสิ่งที่ต้องสูญเสียจะตกมาที่เจ้าชะตาโดยตรง\",\"มักจะเป็นคนที่ชอบใช้เงิน ใช้จ่ายเยอะ ไม่ค่อยเป็นคนเก็บออม ยกเว้นว่ามีปัจจัยอื่นในดวงช่วย\",\"ถ้าเป็นดาวที่ให้คุณ เช่น พฤหัส ศุกร์ หรือพุธ จะไม่ค่อยมีปัญหา เพราะแม้จะเสียก็จะได้รับกลับคืน\",\"เจ้าชะตาเป็นคนใจกว้าง ชอบช่วยเหลือผู้อื่น มีความเมตตาโดยธรรมชาติ\",\"ถ้าเป็นดาวบาปเคราะห์ เช่น อังคาร เสาร์ ราหู เกตุ หรือร่วมกับดาวเหล่านี้ในเรือนที่ 1 จะส่งผลให้การเงินมีปัญหา ใช้จ่ายเกินตัว และจัดการรายจ่ายได้ยาก\",\"เจ้าชะตาจะเป็นคนลึกซึ้ง ซ่อนอะไรไว้ข้างใน ไม่เปิดเผยตัวง่าย ๆ คนอื่นอาจรู้สึกว่าเข้าใจยาก หรือรู้สึกว่าคุณมีอะไรปกปิดอยู่เสมอ\",\"มักจะมีปัญหาเรื่องพี่น้อง โดยเฉพาะพี่น้องที่อายุน้อยกว่า อาจไม่ค่อยติดต่อสื่อสารกัน หรือไม่ใส่ใจเรื่องความสัมพันธ์กับพี่น้องเท่าที่ควร\",\"เรื่องบ้าน ที่อยู่อาศัย หรือความสัมพันธ์กับแม่ มักจะมีความละเอียดอ่อน หรือมีปมในใจที่ฝังลึกอยู่\",\"ความสัมพันธ์กับแม่อาจเป็นไปได้สองทางคือผูกพันแน่นแฟ้นมาก หรือห่างเหินและขาดการเชื่อมโยงกัน\",\"เจ้าชะตามักมีความกลัวเรื่องความล้มเหลวในหน้าที่การงาน หรือขาดความมั่นใจที่จะผลักดันตนเอง\",\"ส่งผลให้ความก้าวหน้าในหน้าที่การงานมาช้า หรือในบางคนอาจพยายามผลักดันตนเองมากเกินไปเพื่อกลบความไม่มั่นใจ ซึ่งอาจทำให้เกิดปัญหาในความสัมพันธ์กับเพื่อนร่วมงานหรือคู่ค้า\",\"เรื่องความสัมพันธ์ คู่ครอง หรือการแต่งงาน มักมีความคาดหวังในอุดมคติสูงมาก ทำให้ผิดหวังได้ง่ายเมื่อไม่เป็นตามฝัน\",\"จำเป็นต้องมีทัศนคติแบบ \\\"การรับใช้\\\" คู่ครอง คือคอยช่วยเหลือ สนับสนุน และวางอีโก้ของตนลง ความสัมพันธ์จึงจะราบรื่น\",\"มักพบว่าความสัมพันธ์ของเจ้าชะตาเกี่ยวข้องกับต่างประเทศ เช่น คบคนต่างชาติ หรือมีความรักระยะไกล เพราะพลังของเรือนที่ 12\"]"::jsonb),
("12in2",12,2,"ดาวเจ้าเรือนที่ 12 สถิตเรือนที่ 2","[\"รายได้และความมั่งคั่งอาจหลุดลอยไป หรือสะสมยาก มีแนวโน้มใช้เงินเกินตัวหรือควบคุมการใช้จ่ายไม่ได้\",\"เรือนที่ 12 คือเรือนของฤๅษีและค่านิยมที่สูงส่ง ถ้าหารายได้จากแหล่งที่ผิดศีลธรรม เช่น การเบียดเบียนผู้อื่น ทรัพย์นั้นจะไม่อยู่กับเจ้าชะตานาน\",\"แต่หากใช้เงินเพื่อการกุศล หรือช่วยเหลือครอบครัว จะสามารถรักษาและเพิ่มพูนความมั่งคั่งได้\",\"ไม่ควรยึดติดกับทรัพย์สินเงินทองหรือเห็นแก่ตัวในเรื่องทรัพย์\",\"ดาวเจ้าเรือนที่ 12 ยังหมายถึงความลับ ถ้าเจ้าชะตาเก็บความลับเกี่ยวกับการเงินหรือมีเล่ห์เหลี่ยมเรื่องเงินทอง อาจส่งผลเสีย\",\"การพูดจาควรใช้ให้เกิดประโยชน์ ไม่ควรพูดจาด้วยเจตนาแอบแฝงหรือหลอกลวง เพราะอาจย้อนกลับมาทำร้ายตนเอง\",\"ชีวิตวัยเด็กหรือความผูกพันกับบ้านเกิดอาจไม่แน่นแฟ้น หรือมีเหตุให้ต้องจากบ้านเดิม\",\"มีปฏิกิริยาไวต่อการเรียนรู้หรือการศึกษา อาจเกิดอารมณ์รุนแรงหากเผชิญความล้มเหลวในการเรียน\",\"ความสัมพันธ์กับลูกหรือเรื่องลูกอาจมีความอ่อนไหว หรือในบางกรณีอาจไม่มีลูกเลย\",\"รายได้ (เรือนที่ 11) จะขึ้นๆ ลงๆ บางช่วงดี บางช่วงไม่มีเลย ควรฝึกปล่อยวางและเชื่อมั่นในพลังเหนือธรรมชาติ\",\"เพื่อนฝูงและเครือข่ายสังคมอาจเปลี่ยนแปลงบ่อย ทำให้รู้สึกไม่มั่นคง ควรยอมรับการเปลี่ยนแปลงเหล่านี้และไม่ยึดติ\"]"::jsonb),
("12in3",12,3,"ดาวเจ้าเรือนที่ 12 สถิตเรือนที่ 3","[\"อาจได้รับการสนับสนุนจากพี่น้อง โดยเฉพาะน้องคนเล็ก แต่ต้องไม่ยึดติด\",\"การมีระยะห่างหรือปล่อยวางในความสัมพันธ์กับพี่น้องจะช่วยให้ความสัมพันธ์ราบรื่นขึ้น\",\"กลายเป็นคนมีความตั้งใจแน่วแน่ (self-willed) สูง มีแรงผลักจากอดีตหรือความเจ็บปวด\",\"มีแนวโน้มจะจดจำความแค้นหรือเหตุการณ์ลบ ต้องระวังไม่ให้สิ่งนี้ทำลายความสัมพันธ์กับผู้อื่น\",\"ระวังคำพูด การสื่อสาร หรือสิ่งที่เขียนออนไลน์ — อาจย้อนกลับมาทำร้ายในภายหลัง\",\"มีแนวโน้มหมดแรงจูงใจในการเลี้ยงดูลูก โดยเฉพาะลูกชาย\",\"มีพรสวรรค์ทางการเรียนรู้ที่ลึกซึ้ง แต่ขาดแรงขับในการศึกษาในระบบ\",\"ชอบเดินทางหรือเคลื่อนไหวอยู่เสมอ แต่ต่างประเทศอาจไม่ราบรื่น\",\"มีความขัดแย้งด้านความเชื่อ ศาสนา หรือความหมายชีวิต\",\"มีโอกาสเกิดปัญหากับบิดา หรือความไม่เข้าใจเชิงคุณค่า\",\"ต้องค้นหาความหมายชีวิตจากข้างใน (เรือนที่ 10 จากเรือนที่ 12 คือเรือนที่ 12 เอง)\",\"การปลีกวิเวก ทำสมาธิ หรือฝึกสติจะช่วยรักษาสมดุลในชีวิตได้มาก\"]"::jsonb),
("12in4",12,4,"ดาวเจ้าเรือนที่ 12 สถิตเรือนที่ 4","[\"บ้านหรือชีวิตวัยเด็กอาจมีความไม่สงบ มีความสูญเสียหรือขาดหายบางอย่าง\",\"ความสัมพันธ์กับมารดาอาจซับซ้อน เช่น มารดาเจ็บป่วย, ห่างเหิน, หรือสูญเสียไป\",\"ญาติฝ่ายแม่มักไม่ค่อยช่วยเหลือหรืออยู่ห่างไกล\",\"ควรพิจารณาว่าดาวเจ้าเรือนที่ 4 อยู่ตรงไหน อาจมีปัจจัยช่วยลดผลร้ายได้\",\"ควรระวังเรื่องการซื้อ-ขายอสังหาริมทรัพย์ อาจเกิดการสูญเสียหรือผิดพลาด\",\"อาชีพการงานอาจมีความวุ่นวาย สับสน หรือหาทางที่เหมาะสมไม่เจอ\",\"มีแนวโน้มจะลองผิดลองถูก หางานแล้วลาออกบ่อย\",\"ต้องยอมสละบางอย่างในเส้นทางอาชีพเพื่อจะได้พบสิ่งที่เหมาะสมจริงๆ\",\"ความสำเร็จในหน้าที่การงานอาจมาช้า แต่จะเกิดจากการช่วยเหลือผู้อื่นหรือการเสียสละ\",\"ภาระครอบครัว โดยเฉพาะเรื่องบ้านและครอบครัว เป็นกรรมใหญ่ที่ต้องชดใช้\",\"ขาดความเชื่อมั่นในตัวเอง ต้องใช้เวลาเพื่อฟื้นพลังและความมั่นใจ\"]"::jsonb),
("12in5",12,5,"ดาวเจ้าเรือนที่ 12 สถิตเรือนที่ 5","[\"มีความท้าทายเกี่ยวกับลูก โดยเฉพาะลูกชายในดวงผู้หญิง อาจมีปัญหาเรื่องการตั้งครรภ์หรือคลอด\",\"แต่หากมีดาวพฤหัสช่วย อิทธิพลด้านลบจะลดลงอย่างมาก\",\"ต้องเสียสละเพื่อบุตร ความสัมพันธ์กับลูกจึงจะสงบสุขและงอกงาม\",\"เป็นตำแหน่งที่ดีมากทางจิตวิญญาณ — ได้รับปัญญาจากโลกภายใน มีสัมผัสพิเศษ และความเข้าใจในธรรมะ\",\"ควรฝึกสมาธิ มนตรา หรือภาวนา จะช่วยเพิ่มพลังชีวิต\",\"ระวังการลงทุน เสี่ยงโชค หรือการพนัน มีแนวโน้มขาดทุนสูง\",\"ทำธุรกิจไม่เหมาะนัก เพราะเรือนที่ 3 (การค้าขาย) เป็นจุดที่เกิดความเบื่อหน่ายหรือเฉยชา\",\"หุ้นส่วนทางธุรกิจอาจทำให้ล้มเหลว หรือขาดแรงร่วมมือ\",\"กรรมจากดาวเจ้าเรือนที่ 12 ไปยังเรือนที่ 2 คือ “การปล่อยวางเรื่องการเงิน”\",\"อย่ากังวลเรื่องรายได้หรืออนาคตทางการเงินมากเกินไป\"]"::jsonb),
("12in6",12,6,"ดาวเจ้าเรือนที่ 12 สถิตเรือนที่ 6","[\"ต้องระวังเป็นพิเศษ มีกรรมจากอดีตชาติที่อาจนำพาไปสู่สถานการณ์ที่ยากลำบาก\",\"โดยเฉพาะเรื่องความสัมพันธ์ — ห้ามโกหก ปิดบัง หรือทำสิ่งไม่ถูกต้อง จะส่งผลรุนแรงกลับมา\",\"เป็นตำแหน่งที่ให้ความโกรธหรือความหัวร้อนง่าย มีคู่แข่งมาก ปัญหาทางกฎหมายก็บ่อย\",\"ที่ทำงานอาจมีแต่ความขัดแย้ง หรือสภาพแวดล้อมไม่เป็นมิตร\",\"อาจมีปัญหากับพี่น้องโดยเฉพาะเรื่องการสื่อสารและการแข่งขัน\",\"ปัญหาสุขภาพก็ควรเฝ้าระวัง โดยเฉพาะความเครียด\",\"วิธีแก้: ชำระล้างกรรมของเรือนที่ 6 โดยทำบุญให้สัตว์เล็ก บริจาค ช่วยงานการแพทย์\",\"ดาวเจ้าเรือนที่ 12 ยังหมายถึง “โรงพยาบาล โรงเรียนพิเศษ หรือสถานกักกัน” — การทำงานหรือรับใช้ในสถานที่เหล่านี้จะช่วยลดกรรม\",\"ชีวิตจะดีขึ้นเมื่อปล่อยวางความช่างวิจารณ์ทั้งต่อผู้อื่นและต่อตัวเอง\",\"เส้นทางการใช้ชีวิตแบบ “ผู้รับใช้” จะทำให้เกิดความสุขใจลึกๆ\"]"::jsonb),
("12in7",12,7,"ดาวเจ้าเรือนที่ 12 สถิตในเรือนที่ 7","[\"ความสัมพันธ์อาจมีปัญหา ดาวเจ้าเรือนที่ 12 จะพาไปสู่บทเรียนทางจิตวิญญาณผ่านคู่ครอง\",\"ความสัมพันธ์มีแนวโน้มเกิดวิกฤตซ้ำ ๆ โดยเฉพาะความสัมพันธ์ลึกซึ้งหรือคู่สมรส\",\"คู่ครองอาจมาจากแดนไกล หรือต่างประเทศ หรือคุณอาจต้องเดินทางไปเจอเขา\",\"จำเป็นต้องมีทัศนคติแห่งการ “รับใช้” ต่อคู่ครอง ความอดทน การให้อภัย จะนำมาซึ่งความสงบ\",\"มีโอกาสเกิดความสูญเสียทางการเงินเกี่ยวกับคู่ครอง\",\"ธุรกิจส่วนตัวหรือพาร์ทเนอร์ทางธุรกิจอาจไม่มั่นคงหรือเสี่ยงสูง\",\"อาจรู้สึกเบื่อหน่ายหรือไม่สนใจความสัมพันธ์กับบิดาและการศึกษาขั้นสูง\",\"ควรปล่อยวางเรื่องบ้านหรือความเป็นอยู่ อย่าควบคุมหรือเครียดมากเกินไป\"]"::jsonb),
("12in8",12,8,"ดาวเจ้าเรือนที่ 12 สถิตในเรือนที่ 8","[\"ตำแหน่งนี้จัดเป็น “วิโปรีต ราชโยค” (Vipreet Raj Yoga) คือได้ผลดีผ่านความลำบาก\",\"อาจเกิดการเปลี่ยนแปลงเฉียบพลัน เช่น สูญเสียบ้าน งาน คู่ครอง หรือสุขภาพ\",\"ทุกครั้งที่เกิดการสูญเสีย คุณจะเกิดใหม่ในรูปแบบที่เข้มแข็งกว่าเดิม\",\"มักไม่ผลักดันตัวเองในอาชีพ อาจรู้สึกเบื่อหน่าย ขาดแรงบันดาลใจ\",\"แต่อาจทำงานหนักแบบเงียบ ๆ ไม่สนใจคำพูดคนอื่น\",\"อ่อนไหวมากกับเรื่องรายได้และการสูญเสียทางการเงิน\",\"ความสัมพันธ์กับเพื่อนหรือกลุ่มสังคมอาจแปรเปลี่ยนบ่อยครั้งและทำให้คุณอ่อนไหว\",\"อาจขาดศรัทธาในความสามารถสร้างสรรค์ของตนเอง\",\"การทำธุรกิจส่วนตัวสามารถสำเร็จได้ถ้าไม่เสี่ยงเกินไป และอย่าผลักดันตัวเองมาก\"]"::jsonb),
("12in9",12,9,"ดาวเจ้าเรือนที่ 12 สถิตในเรือนที่ 9","[\"เป็นตำแหน่งที่ค่อนข้างดี เพราะดาวพฤหัส (ปัตนิแห่งเรือนที่ 9) และดาวเสาร์ (แทนเรือนที่ 12) ทำงานร่วมกันได้\",\"คุณแสวงหาปัญญาและศรัทธา แต่ช่วงต้นชีวิตอาจพบกับความสับสนทางศาสนา\",\"อาจมีปัญหากับศาสนาของครอบครัวหรือพ่อ\",\"มีโอกาสขัดแย้งกับครู อาจารย์ หรือผู้นำทางจิตวิญญาณ แต่คุณจะไม่หยุดค้นหาความจริง\",\"คุณมีแนวโน้มเปลี่ยนเส้นทางศาสนาไปเรื่อย ๆ จนตระหนักว่าทุกศาสนานำไปสู่สิ่งเดียวกัน\",\"การเดินทางไปต่างแดนมักมีปัญหา หรือไม่ราบรื่นตามที่หวัง\",\"มีแนวโน้มทะเลาะกับพี่น้อง เรื่องความเชื่อหรือปรัชญา\",\"หลีกเลี่ยงการฟ้องร้อง การแข่งขัน หรือการโต้เถียง เพราะจะทำให้รู้สึกพ่ายแพ้เสมอ\"]"::jsonb),
("12in10",12,10,"ดาวเจ้าเรือนที่ 12 สถิตในเรือนที่ 10","[\"เด็กที่มีตำแหน่งนี้มักมีวัยเด็กที่ยากลำบาก โดยเฉพาะในบ้าน (เรือนที่ 4 ตรงข้ามเรือนที่ 10)\",\"อาจมีชื่อเสียงทางการงานขึ้นเร็ว แต่รู้สึกไม่พึงพอใจภายใน และอยากหนีหาย\",\"แม้ประสบความสำเร็จสูง ก็ยังรู้สึกว่างเปล่าหรือไม่ใช่สิ่งที่ต้องการจริง ๆ\",\"ความสำเร็จที่มาจากอัตตา หรือชื่อเสียงภายนอก จะไม่ทำให้คุณมีความสุข\",\"อาชีพที่ให้บริการคนอื่น หรือทำงานในโรงพยาบาล เรือนจำ หรือสถาบันจิตใจ จะทำให้รู้สึกเติมเต็ม\",\"ความสัมพันธ์หรือคู่ครองอาจควบคุมไม่ได้และต้องยอมรับอย่างสงบ\",\"อาจไม่เหมาะกับธุรกิจส่วนตัว ยกเว้นมีหุ้นส่วนที่เข้าใจและมั่นคง\"]"::jsonb),
("12in11",12,11,"ดาวเจ้าเรือนที่ 12 สถิตในเรือนที่ 11","[\"ตำแหน่งนี้ดี เพราะเรือนที่ 11 มีดาวพฤหัสเป็นตัวแทน ซึ่งเป็นพลังงานบวก\",\"แม้จะมีค่าใช้จ่ายหรือสูญเสียบ้าง คุณก็สามารถฟื้นตัวทางการเงินได้เสมอ\",\"คุณให้ความสำคัญกับครอบครัว แต่ก็อ่อนไหวและอาจมีประสบการณ์ไม่ราบรื่นในวัยเด็ก\",\"ต้องระวังเรื่องเพื่อนสนิทและกลุ่มสังคม เพราะอาจก่อให้เกิดความสูญเสีย\",\"อาจมีการเปลี่ยนแปลงในกลุ่มเพื่อนหรือวงสังคมอยู่เรื่อย ๆ\",\"ต้องระวังคนในที่ทำงาน โดยเฉพาะข้อมูลที่เปิดเผยกับเพื่อนร่วมงาน\",\"เรือนนี้เกี่ยวกับชุมชนด้วย คุณจะได้รับผลดีถ้ามีทัศนคติรับใช้สังคม\"]"::jsonb),
("12in12",12,12,"ดาวเจ้าเรือนที่ 12 สถิตในเรือนที่ 12","[\"เป็นตำแหน่งที่เข้มแข็งเพราะดาวเจ้าเรือนได้อยู่ในเรือนของตนเอง\",\"แม้มีค่าใช้จ่ายหรือความสูญเสีย แต่คุณสามารถควบคุมหรือจำกัดมันได้\",\"อาจใช้ชีวิตแบบประหยัด เรียบง่าย หรือมีแนวโน้มใช้จ่ายเพื่อการกุศล\",\"มีแรงปรารถนาอย่างแรงกล้าในการแสวงหาจิตวิญญาณ ความสงบภายใน และความสันโดษ\",\"มีแนวโน้มเกี่ยวข้องกับโรงพยาบาล สถานกักกัน หรือสถาบันเพื่อช่วยเหลือคนอื่น\",\"หากดาวประจำเรือนที่ 12 เป็นดาวบาป อาจมีแนวโน้มอยู่ห่างจากสังคม ใช้เวลาอยู่คนเดียวมาก\",\"การสื่อสารอาจเต็มไปด้วยอารมณ์ และความสัมพันธ์กับพี่น้องอาจเกิดความขัดแย้ง\",\"อาจรู้สึกเบื่อหน่ายต่อค่านิยมของครอบครัว หรือความเชื่อศาสนาของพ่อ\",\"แม้จะมีการศึกษาในระดับสูง แต่อาจไม่ได้ใช้ประโยชน์เต็มที่ในชีวิตจริง\",\"การเดินทางไปต่างประเทศอาจไม่ได้ผลลัพธ์อย่างที่หวัง แต่การเดินทางทางจิตวิญญาณภายในจะนำไปสู่ความสำเร็จ\"]"::jsonb),
("11in7",11,7,"11th Lord in 7th House","[\"ดาวเจ้าเรือนที่ 11 สถิตเรือนที่ 7 หมายถึงคุณมีความปรารถนาอย่างลึกซึ้งที่จะมีความสัมพันธ์กับคู่ครองในชาตินี้\",\"เป็นความปรารถนาที่สั่งสมมาหลายชาติ เกิดมาเพื่อพบเจอความสัมพันธ์นี้\",\"หากดาวเจ้าเรือนที่ 11 เป็นบาปเคราะห์ เช่น อังคาร เสาร์ ราหู เกตุ อาจมีความท้าทายในความสัมพันธ์ใกล้ชิด\",\"คุณมักทุ่มเทให้กับคู่ครองมากเกินไป ต้องระวังอย่าให้ตัวเองถูกรังแกหรือเอาเปรียบ\",\"ความสัมพันธ์มักเริ่มต้นจากกลุ่มเพื่อนหรือการเดินทาง\",\"มีลักษณะเป็นคนเปิดกว้าง เป็นมิตร ดึงดูดความสนใจจากผู้อื่นและชอบผู้คน\",\"เหมาะสำหรับการทำธุรกิจ การเป็นผู้ประกอบการ หรือทำงานอิสระ\",\"คู่สมรสหรือนักธุรกิจร่วมมือกันสามารถให้ผลประโยชน์อย่างมาก\",\"คุณยังได้รับผลประโยชน์จากครอบครัวของคู่สมรสด้วย เช่น เครือข่ายทางสังคม การติดต่อ\",\"ความสุขที่ลึกซึ้งมักมาจากการยอมรับในงานหรืออาชีพ ความสำเร็จในอาชีพมีผลต่อความพึงพอใจของคุณ\"]"::jsonb),
("11in8",11,8,"11th Lord in 8th House","[\"คุณมีความปรารถนาแรงกล้าที่จะมีอิสระในการหาเงินด้วยตนเอง\",\"มักเป็นคนทำงานอิสระหรือเจ้าของกิจการ\",\"รายได้มีความผันผวนสูง จากกรรมเก่าที่เชื่อมโยงกับเรือนที่ 8\",\"การเปลี่ยนแปลงแบบฉับพลัน เช่น ตกงานกะทันหัน หรือมีการปลดออกจากงานบ่อยครั้ง\",\"อย่างไรก็ตาม การเปลี่ยนแปลงเหล่านี้มักนำคุณไปสู่โอกาสที่ดีกว่า\",\"คุณสามารถหากำไรจากการช่วยเหลือผู้อื่นในภาวะวิกฤต เช่น หมอ นักจิตบำบัด นักโหราศาสตร์\",\"มีความปรารถนาจะมีความมั่นคงทางการเงินและครอบครัว แต่ต้องเผชิญกับความผันผวนจากสมาชิกครอบครัวเช่นกัน\",\"หากดาวไม่เสียมาก อาจได้ผลกำไรจากตลาดหลักทรัพย์ การลงทุน\",\"เพื่อนและเครือข่ายทางสังคมให้ความสุขอย่างมาก แต่ก็อาจเปลี่ยนแปลงโดยไม่คาดคิด\",\"ระวังเพื่อนร่วมงานที่อิจฉา หรือมีแรงจูงใจแอบแฝง\",\"ควรเก็บแผนงานไว้เป็นความลับ และเลือกไว้วางใจคนรอบข้างอย่างรอบคอบ\"]"::jsonb),
("11in9",11,9,"11th Lord in 9th House","[\"เป็นตำแหน่งที่ดีมาก คุณกำลังได้รับผลของกรรมดีจากอดีตชาติ\",\"ได้รับโชคและความสำเร็จอย่างมาก โดยเฉพาะผ่านการเดินทางและการเรียนรู้\",\"คุณจะมีความฉลาด มีความสามารถในการเรียนรู้ และมีโอกาสเพิ่มพูนความมั่งคั่ง\",\"ชีวิตมีการเดินทางบ่อยครั้ง ไปยังที่ที่เคยปรารถนาไว้ในอดีตชาติ\",\"พูดความจริง รักความถูกต้อง มีครูอาจารย์ที่ส่งเสริม\",\"มีสายสัมพันธ์ทางกรรมลึกซึ้งกับบิดา บางคนได้รับทรัพย์สินจากบิดา หรือความเมตตาในรูปแบบอื่น\",\"พี่น้องไม่ว่าจะอายุน้อยหรือมากให้การสนับสนุนที่ดี\",\"บางคนจะมีถิ่นพำนักในต่างประเทศไม่ว่าจะถาวรหรือชั่วคราว และได้รับความสุขจากที่นั้น\",\"ความสุขลึกซึ้งมาจากการเรียนรู้ การฝึกสมาธิ การปลีกวิเวกทางจิตวิญญาณ\",\"ต้องระวังการถูกชักจูงไปทำกิจกรรมที่ไม่เหมาะสมจากเพื่อนหรือเครือข่ายทางสังคม\",\"มีโอกาสก้าวหน้าในการสื่อสาร การเขียน การเผยแพร่\"]"::jsonb),
("11in10",11,10,"11th Lord in 10th House","[\"แม้จะดูเหมือนเป็นตำแหน่งเสีย (ไปอยู่เรือนที่ 12 จากตัวเอง) แต่จริง ๆ แล้วให้ผลดีมาก\",\"เป็นการสานต่ออาชีพ ความปรารถนา หรือความทะเยอทะยานจากอดีตชาติ\",\"มีความทะเยอทะยานสูง มุ่งมั่น ขยัน และมีระเบียบวินัยสูง\",\"มีพรสวรรค์ทางสติปัญญา ความรู้เฉพาะทางที่ติดตัวมาตั้งแต่เด็ก\",\"หากดาวเสีย อาจมีความสับสนหรืออุปสรรคบ้าง แต่ควรฟังเสียงภายในและทำตามเส้นทางที่รู้ว่าถูกต้อง\",\"มีความลับ มีความปรารถนาจะทำงานจากบ้าน หรือวางแผนจากพื้นที่ส่วนตัวก่อนแสดงออกสู่สาธารณะ\",\"มีชื่อเสียง ได้รับเกียรติจากผู้มีอำนาจ เช่น รัฐบาล หัวหน้า หรือบุคคลระดับสูง\",\"ต้องระวังเพื่อนร่วมงานที่ไม่ซื่อสัตย์ หรือมีจุดประสงค์แอบแฝง\",\"มีความสุขเมื่อได้รับการยอมรับ ยกย่อง หรือคำชมจากสังคม\",\"ชีวิตการงานขึ้นเร็วและตกเร็ว ต้องปรับตัวให้ได้กับความเปลี่ยนแปลงอย่างรวดเร็ว\",\"การทำงานจากบ้าน หรือการมีสำนักงานในบ้านให้ผลดีมาก ลดความตึงเครียดจากการแข่งขันภายนอก\"]"::jsonb),
("11in11",11,11,"11th Lord in 11th House","[\"ดาวเจ้าเรือนที่ 11 สถิตเรือนของตนเองเป็นตำแหน่งที่แข็งแรงมาก มีพลังให้ผลดีสูง\",\"เป็นกรรมเก่าที่มีความปรารถนาแรงกล้ารอการเติมเต็ม โดยเฉพาะในด้านความรู้หรือทักษะเฉพาะทาง\",\"จะมีโอกาสเรียนรู้หรือพัฒนาทักษะเฉพาะอย่างมากในช่วงมหาดาวของดาวเจ้าเรือนที่ 11\",\"เรือนที่ 5 ซึ่งเป็นเรือนที่ได้รับการส่งพลังโดยตรง บ่งชี้ถึงพรสวรรค์ ความคิดสร้างสรรค์ การแสดง การเรียนรู้\",\"เหมาะสำหรับงานแสดง ศิลปะ การเต้น การร้องเพลง การเขียน หรือการเรียนรู้ในระดับลึก\",\"เป็นผู้นำในกลุ่มสังคม หรือเพื่อนฝูงมักมองว่าคุณคือผู้นำ\",\"เพื่อนบางคนช่วยสนับสนุนอย่างดี บางคนอาจสร้างอันตราย ต้องระวัง\",\"เหมาะกับงานบริหาร การเป็นหัวหน้าโครงการ หรือครูผู้ถ่ายทอดความรู้\",\"ให้ผลดีในเรื่องทรัพย์สิน ความมั่งคั่ง และการกินอาหาร คุณอาจมีรายได้จากธุรกิจอาหาร หรือชอบทำอาหาร\"]"::jsonb),
("11in12",11,12,"11th Lord in 12th House","[\"มีแนวโน้มได้รับรายได้จากต่างประเทศ หรือจากคนที่อยู่ห่างไกลถิ่นกำเนิด\",\"ความสัมพันธ์กับเพื่อนหรือคู่รักอาจมีเส้นแบ่งไม่ชัดเจน มีความสับสน หรือซ่อนเร้น\",\"เป็นคนโรแมนติกสูง มีเสน่ห์ทางเพศแรง ซึ่งนำไปสู่ความซับซ้อนในความสัมพันธ์\",\"ใส่ใจภาพลักษณ์และสิ่งที่ผู้อื่นคิดมาก\",\"การเดินทางไกลสามารถเพิ่มรายได้ การมีเครือข่ายต่างประเทศให้ผลดี\",\"มักใช้จ่ายเท่าที่หาได้ หรือมากกว่าที่หาได้ ต้องระวังการใช้เงินเกินตัว\",\"เป็นคนใจกว้าง มีความเมตตา การบริจาคหรือทำงานเพื่อสังคมช่วยลดการสูญเสียรายได้\",\"ทำงานในองค์กรใหญ่ เช่น โรงพยาบาล โรงเรียน สถานพยาบาล หรือองค์กรบริการสังคม ให้ผลดี\",\"ความปรารถนาลึกซึ้งคือการช่วยเหลือผู้อื่น เช่น งานแพทย์ งานกฎหมาย งานเพื่อสิ่งมีชีวิตอื่น ๆ\",\"ความสุขลึกซึ้งมาจากเรือนที่ 3 เช่น การเขียน การสื่อสาร การทำงานกับพี่น้องหรือญาติ\"]"::jsonb);